/* Deutsch A1 – Wortschatz für Türkischsprechende (Übersetzungen und Hinweise auf Türkisch)
 * Format: { id, t, pl, pos, n, ex, exn, topic, note }
 *  t   = deutsches Wort (Nomen immer mit Artikel)   pl = Plural (nur wenn üblich)
 *  pos = n | v | adj | adv | phr | x                  topic = Wortfeld-ID aus K.wordfields
 * IDs NIE ändern oder wiederverwenden – daran hängt der Lernfortschritt. Neue Wörter → nächste freie Nummer.
 */
(function (K) {
K.addVocab('de-a1', [
  /* ---------- greet: Begrüßung & Höflichkeit ---------- */
  { id: "de-a1.w001", t: "hallo", pos: "x", n: "merhaba, selam", ex: "Hallo, ich bin Deniz.", exn: "Selam, ben Deniz.", topic: "greet" },
  { id: "de-a1.w002", t: "Guten Morgen!", pos: "phr", n: "günaydın", ex: "Guten Morgen, Frau Weber!", exn: "Günaydın Weber Hanım!", topic: "greet", note: "Genelde sabah saat 10–11'e kadar kullanılır." },
  { id: "de-a1.w003", t: "Guten Tag!", pos: "phr", n: "iyi günler; merhaba (resmî)", ex: "Guten Tag, mein Name ist Kaya.", exn: "İyi günler, benim adım Kaya.", topic: "greet", note: "Gün içinde, özellikle tanımadığın kişilere söylenen resmî selamdır. Arkadaşlar arasında daha çok „Hallo“ denir." },
  { id: "de-a1.w004", t: "Guten Abend!", pos: "phr", n: "iyi akşamlar", ex: "Guten Abend, Herr Schulz!", exn: "İyi akşamlar Schulz Bey!", topic: "greet" },
  { id: "de-a1.w005", t: "Gute Nacht!", pos: "phr", n: "iyi geceler", ex: "Gute Nacht, schlaf gut!", exn: "İyi geceler, iyi uykular!", topic: "greet", note: "Sadece yatmaya giderken ya da gece vedalaşırken kullanılır. Akşam birine rastlayınca „Guten Abend“ denir." },
  { id: "de-a1.w006", t: "tschüss", pos: "x", n: "hoşça kal, görüşürüz (samimi)", ex: "Tschüss, bis morgen!", exn: "Hoşça kal, yarın görüşürüz!", topic: "greet", note: "Samimi bir vedadır. Resmî ortamda „Auf Wiedersehen“ daha uygundur." },
  { id: "de-a1.w007", t: "Auf Wiedersehen!", pos: "phr", n: "hoşça kalın, görüşmek üzere (resmî)", ex: "Auf Wiedersehen und vielen Dank!", exn: "Hoşça kalın, çok teşekkürler!", topic: "greet", note: "Telefonda „Auf Wiederhören!“ denir, çünkü birbirinizi görmüyorsunuz." },
  { id: "de-a1.w008", t: "bitte", pos: "x", n: "lütfen; buyurun; rica ederim", ex: "Einen Tee, bitte.", exn: "Bir çay lütfen.", topic: "greet", note: "Üç anlamı var: bir şey isterken (lütfen), bir şey uzatırken (buyurun) ve teşekküre cevap olarak (rica ederim)." },
  { id: "de-a1.w009", t: "danke", pos: "x", n: "teşekkürler, sağ ol", ex: "Danke für die Hilfe!", exn: "Yardımın için teşekkürler!", topic: "greet", note: "Daha kibar: „Vielen Dank!“ ya da „Danke schön!“" },
  { id: "de-a1.w010", t: "Entschuldigung!", pos: "phr", n: "affedersiniz, pardon", ex: "Entschuldigung, wo ist die Toilette?", exn: "Affedersiniz, tuvalet nerede?", topic: "greet", note: "Birine bir şey sormadan önce de, özür dilerken de kullanılır." },
  { id: "de-a1.w011", t: "Wie geht's?", pos: "phr", n: "nasılsın?", ex: "Hallo Lea, wie geht's?", exn: "Selam Lea, nasılsın?", topic: "greet", note: "Resmî hâli: „Wie geht es Ihnen?“ – Cevap: „Gut, danke. Und Ihnen?“" },
  { id: "de-a1.w012", t: "Es tut mir leid.", pos: "phr", n: "üzgünüm; kusura bakma", ex: "Es tut mir leid, ich komme zu spät.", exn: "Kusura bakma, geç kaldım.", topic: "greet", note: "Kötü bir haber duyunca „geçmiş olsun / çok üzüldüm“ anlamında da kullanılır." },
  { id: "de-a1.w013", t: "Wie bitte?", pos: "phr", n: "efendim? pardon, anlamadım", ex: "Wie bitte? Ich habe Sie nicht verstanden.", exn: "Efendim? Sizi anlayamadım.", topic: "greet", note: "Bir şeyi duymadığında ya da anlamadığında kibarca böyle sorarsın. Sadece „Was?“ demek kaba kaçabilir." },
  { id: "de-a1.w014", t: "Freut mich!", pos: "phr", n: "memnun oldum", ex: "Ich bin Murat. – Freut mich!", exn: "Ben Murat. – Memnun oldum!", topic: "greet" },
  { id: "de-a1.w015", t: "ja", pos: "x", n: "evet", ex: "Ja, das stimmt.", exn: "Evet, doğru.", topic: "greet", note: "„j“ Almancada „y“ okunur: ja = ya." },
  { id: "de-a1.w016", t: "nein", pos: "x", n: "hayır", ex: "Nein, danke. Ich habe keinen Hunger.", exn: "Hayır, teşekkürler. Aç değilim.", topic: "greet", note: "„ei“ = ay: nein = nayn." },
  { id: "de-a1.w017", t: "der Name", pl: "die Namen", pos: "n", n: "isim, ad", ex: "Wie ist Ihr Name?", exn: "Adınız nedir?", topic: "greet", note: "der Vorname = ad, der Nachname = soyadı. Formlarda ikisi ayrı sorulur." },
  { id: "de-a1.w018", t: "heißen", pos: "v", n: "adı … olmak", ex: "Ich heiße Elif. Und du?", exn: "Benim adım Elif. Ya senin?", topic: "greet", note: "Ad sorarken „wie“ kullanılır: Wie heißt du? („Was heißt du?“ yanlış.)" },
  { id: "de-a1.w019", t: "der Herr", pl: "die Herren", pos: "n", n: "bey, beyefendi", ex: "Herr Becker ist mein Nachbar.", exn: "Becker Bey benim komşum.", topic: "greet", note: "Almancada soyadıyla kullanılır: Herr Yılmaz (Yılmaz Bey). Adla kullanılmaz: „Herr Ahmet“ yanlış." },
  { id: "de-a1.w020", t: "Bis morgen!", pos: "phr", n: "yarın görüşürüz!", ex: "Schönen Abend noch! Bis morgen!", exn: "İyi akşamlar! Yarın görüşürüz!", topic: "greet", note: "Aynı kalıpla: Bis später! (Sonra görüşürüz), Bis bald! (Yakında görüşürüz)." },

  /* ---------- people: Personen & Familie ---------- */
  { id: "de-a1.w021", t: "der Mann", pl: "die Männer", pos: "n", n: "adam, erkek; koca", ex: "Das ist mein Mann, Emre.", exn: "Bu benim kocam Emre.", topic: "people", note: "„mein Mann“ = kocam. Ayrı bir „koca“ kelimesine gerek yoktur." },
  { id: "de-a1.w022", t: "die Frau", pl: "die Frauen", pos: "n", n: "kadın; eş; hanım", ex: "Frau Arslan wohnt im zweiten Stock.", exn: "Arslan Hanım ikinci katta oturuyor.", topic: "people", note: "Üç anlamı var: kadın, eş („meine Frau“ = karım/eşim) ve soyadıyla „Hanım“ (Frau Arslan)." },
  { id: "de-a1.w023", t: "das Kind", pl: "die Kinder", pos: "n", n: "çocuk", ex: "Wir haben zwei Kinder.", exn: "İki çocuğumuz var.", topic: "people" },
  { id: "de-a1.w024", t: "die Mutter", pl: "die Mütter", pos: "n", n: "anne", ex: "Meine Mutter kocht sehr gut.", exn: "Annem çok güzel yemek yapar.", topic: "people", note: "Günlük dilde „Mama“ da denir." },
  { id: "de-a1.w025", t: "der Vater", pl: "die Väter", pos: "n", n: "baba", ex: "Mein Vater arbeitet in Köln.", exn: "Babam Köln'de çalışıyor.", topic: "people", note: "„V“ burada „f“ okunur: Vater = faater." },
  { id: "de-a1.w026", t: "die Eltern", pos: "n", n: "anne baba, ebeveyn", ex: "Meine Eltern wohnen in Izmir.", exn: "Annemle babam İzmir'de oturuyor.", topic: "people", note: "Günlük dilde sadece çoğul kullanılır: die Eltern sind …" },
  { id: "de-a1.w027", t: "der Bruder", pl: "die Brüder", pos: "n", n: "erkek kardeş; ağabey", ex: "Mein Bruder ist 15 Jahre alt.", exn: "Erkek kardeşim 15 yaşında.", topic: "people", note: "Almancada ağabey/küçük erkek kardeş ayrımı yoktur. Gerekirse: mein älterer / jüngerer Bruder." },
  { id: "de-a1.w028", t: "die Schwester", pl: "die Schwestern", pos: "n", n: "kız kardeş; abla", ex: "Meine Schwester studiert in Berlin.", exn: "Kız kardeşim Berlin'de üniversite okuyor.", topic: "people", note: "Abla için de „Schwester“ denir. Hastanede „Schwester“ ayrıca hemşire demektir." },
  { id: "de-a1.w029", t: "die Geschwister", pos: "n", n: "kardeşler", ex: "Hast du Geschwister?", exn: "Kardeşin var mı?", topic: "people", note: "Kız ve erkek kardeşlerin hepsi için ortak kelime; çoğul kullanılır." },
  { id: "de-a1.w030", t: "der Sohn", pl: "die Söhne", pos: "n", n: "oğul", ex: "Unser Sohn geht in die Schule.", exn: "Oğlumuz okula gidiyor.", topic: "people" },
  { id: "de-a1.w031", t: "die Tochter", pl: "die Töchter", pos: "n", n: "kız evlat", ex: "Meine Tochter ist drei.", exn: "Kızım üç yaşında.", topic: "people", note: "„Kızım“ (evlat) = meine Tochter. Genel olarak „kız çocuk“ = das Mädchen." },
  { id: "de-a1.w032", t: "die Oma", pl: "die Omas", pos: "n", n: "nine; anneanne, babaanne", ex: "Am Sonntag besuchen wir Oma.", exn: "Pazar günü nineme gidiyoruz.", topic: "people", note: "Anneanne/babaanne ayrımı yoktur. Resmî kelime: die Großmutter." },
  { id: "de-a1.w033", t: "der Opa", pl: "die Opas", pos: "n", n: "dede", ex: "Mein Opa ist 80 Jahre alt.", exn: "Dedem 80 yaşında.", topic: "people", note: "Resmî kelime: der Großvater." },
  { id: "de-a1.w034", t: "der Onkel", pl: "die Onkel", pos: "n", n: "amca; dayı; enişte", ex: "Mein Onkel hat ein Restaurant.", exn: "Amcamın bir restoranı var.", topic: "people", note: "Amca, dayı ve enişte için tek kelime var: Onkel." },
  { id: "de-a1.w035", t: "die Tante", pl: "die Tanten", pos: "n", n: "teyze; hala; yenge", ex: "Meine Tante wohnt in Hamburg.", exn: "Teyzem Hamburg'da oturuyor.", topic: "people", note: "Teyze, hala ve yenge – hepsi „Tante“." },
  { id: "de-a1.w036", t: "die Familie", pl: "die Familien", pos: "n", n: "aile", ex: "Meine Familie ist groß.", exn: "Ailem kalabalık.", topic: "people", note: "Okunuşu yaklaşık „famiilye“; vurgu ikinci hecede." },
  { id: "de-a1.w037", t: "der Freund", pl: "die Freunde", pos: "n", n: "(erkek) arkadaş; erkek arkadaş, sevgili", ex: "Das ist Tim, ein Freund von mir.", exn: "Bu Tim, bir arkadaşım.", topic: "people", note: "„mein Freund“ çoğu zaman „sevgilim“ diye anlaşılır. Sadece arkadaşsa: „ein Freund von mir“." },
  { id: "de-a1.w038", t: "die Freundin", pl: "die Freundinnen", pos: "n", n: "kız arkadaş; sevgili", ex: "Meine Freundin heißt Aylin.", exn: "Kız arkadaşımın adı Aylin.", topic: "people", note: "„meine Freundin“ da sevgili anlamına gelebilir; sadece arkadaşsa „eine Freundin von mir“." },
  { id: "de-a1.w039", t: "das Mädchen", pl: "die Mädchen", pos: "n", n: "kız (çocuk)", ex: "Das Mädchen spielt im Garten.", exn: "Kız bahçede oynuyor.", topic: "people", note: "Dikkat: „das“! -chen ile biten kelimeler, anlamı dişi olsa bile hep „das“ alır." },
  { id: "de-a1.w040", t: "der Junge", pl: "die Jungen", pos: "n", n: "erkek çocuk, oğlan", ex: "Der Junge ist zehn Jahre alt.", exn: "Oğlan on yaşında.", topic: "people", note: "Günlük dilde çoğul olarak „die Jungs“ da çok kullanılır." },
  { id: "de-a1.w041", t: "das Baby", pl: "die Babys", pos: "n", n: "bebek", ex: "Das Baby schläft gerade.", exn: "Bebek şu an uyuyor.", topic: "people", note: "İngilizcedeki gibi „beybi“ okunur. Çoğulu: Babys (Babies değil)." },
  { id: "de-a1.w042", t: "der Mensch", pl: "die Menschen", pos: "n", n: "insan", ex: "Hier wohnen viele Menschen.", exn: "Burada çok insan yaşıyor.", topic: "people" },
  { id: "de-a1.w043", t: "die Leute", pos: "n", n: "insanlar", ex: "Viele Leute warten auf den Bus.", exn: "Birçok insan otobüs bekliyor.", topic: "people", note: "Sadece çoğul kullanılır. Günlük dilde „Menschen“den daha sık duyulur." },
  { id: "de-a1.w044", t: "verheiratet", pos: "adj", n: "evli", ex: "Bist du verheiratet?", exn: "Evli misin?", topic: "people" },
  { id: "de-a1.w045", t: "ledig", pos: "adj", n: "bekâr", ex: "Nein, ich bin ledig.", exn: "Hayır, bekârım.", topic: "people", note: "Formlarda geçer; günlük dilde „Ich bin Single“ da denir." },
  { id: "de-a1.w046", t: "der Nachbar", pl: "die Nachbarn", pos: "n", n: "komşu (erkek)", ex: "Unser Nachbar hat einen Hund.", exn: "Komşumuzun bir köpeği var.", topic: "people", note: "Kadın komşu: die Nachbarin. Çoğulu yalnızca -n alır: die Nachbarn." },

  /* ---------- numbers: Zahlen, Zeit & Kalender ---------- */
  { id: "de-a1.w047", t: "null", pos: "x", n: "sıfır", ex: "Meine Nummer beginnt mit null.", exn: "Numaram sıfırla başlıyor.", topic: "numbers" },
  { id: "de-a1.w048", t: "eins", pos: "x", n: "bir", ex: "Der Bus Nummer eins fährt zum Bahnhof.", exn: "Bir numaralı otobüs gara gidiyor.", topic: "numbers", note: "Sayarken „eins“ denir; bir isimden önce „ein/eine“: ein Apfel, eine Banane." },
  { id: "de-a1.w049", t: "zwei", pos: "x", n: "iki", ex: "Zwei Kaffee, bitte.", exn: "İki kahve lütfen.", topic: "numbers", note: "Telefonda „drei“ ile karışmasın diye bazen „zwo“ denir." },
  { id: "de-a1.w050", t: "drei", pos: "x", n: "üç", ex: "Wir sind drei Personen.", exn: "Üç kişiyiz.", topic: "numbers" },
  { id: "de-a1.w051", t: "vier", pos: "x", n: "dört", ex: "Das Zimmer hat vier Fenster.", exn: "Odanın dört penceresi var.", topic: "numbers", note: "„v“ = f: vier = fiir." },
  { id: "de-a1.w052", t: "fünf", pos: "x", n: "beş", ex: "Es ist fünf Uhr.", exn: "Saat beş.", topic: "numbers" },
  { id: "de-a1.w053", t: "sechs", pos: "x", n: "altı", ex: "Der Kurs hat sechs Teilnehmer.", exn: "Kursta altı katılımcı var.", topic: "numbers", note: "„chs“ burada „ks“ okunur, baştaki „s“ de „z“: sechs = zeks." },
  { id: "de-a1.w054", t: "sieben", pos: "x", n: "yedi", ex: "Die Woche hat sieben Tage.", exn: "Haftada yedi gün var.", topic: "numbers" },
  { id: "de-a1.w055", t: "acht", pos: "x", n: "sekiz", ex: "Ich arbeite acht Stunden am Tag.", exn: "Günde sekiz saat çalışıyorum.", topic: "numbers", note: "„ch“ burada boğazdan gelen hırıltılı bir „h“dir: aht." },
  { id: "de-a1.w056", t: "neun", pos: "x", n: "dokuz", ex: "Mein Bus fährt um neun.", exn: "Otobüsüm dokuzda kalkıyor.", topic: "numbers", note: "„eu“ = oy: neun = noyn." },
  { id: "de-a1.w057", t: "zehn", pos: "x", n: "on", ex: "Das kostet zehn Euro.", exn: "Bu on avro.", topic: "numbers", note: "„z“ = ts: zehn = tseen." },
  { id: "de-a1.w058", t: "elf", pos: "x", n: "on bir", ex: "Mein Sohn ist elf.", exn: "Oğlum on bir yaşında.", topic: "numbers" },
  { id: "de-a1.w059", t: "zwölf", pos: "x", n: "on iki", ex: "Um zwölf Uhr essen wir.", exn: "Saat on ikide yemek yiyoruz.", topic: "numbers" },
  { id: "de-a1.w060", t: "zwanzig", pos: "x", n: "yirmi", ex: "Ich brauche zwanzig Minuten.", exn: "Yirmi dakikaya ihtiyacım var.", topic: "numbers", note: "21'den itibaren önce birler söylenir: einundzwanzig = „bir ve yirmi“ (21)." },
  { id: "de-a1.w061", t: "hundert", pos: "x", n: "yüz", ex: "Das Fahrrad kostet hundert Euro.", exn: "Bisiklet yüz avro.", topic: "numbers" },
  { id: "de-a1.w062", t: "der Montag", pl: "die Montage", pos: "n", n: "pazartesi", ex: "Am Montag habe ich Deutschkurs.", exn: "Pazartesi Almanca kursum var.", topic: "numbers", note: "Günler „der“ alır ve „am“ ile kullanılır: am Montag (pazartesi günü)." },
  { id: "de-a1.w063", t: "der Dienstag", pl: "die Dienstage", pos: "n", n: "salı", ex: "Am Dienstag arbeite ich lange.", exn: "Salı günü geç saate kadar çalışıyorum.", topic: "numbers" },
  { id: "de-a1.w064", t: "der Mittwoch", pl: "die Mittwoche", pos: "n", n: "çarşamba", ex: "Am Mittwoch ist hier Markt.", exn: "Çarşamba günü burada pazar kuruluyor.", topic: "numbers", note: "Kelime anlamı „haftanın ortası“. Diğer günlerin çoğundan farklı olarak -tag ile bitmez." },
  { id: "de-a1.w065", t: "der Donnerstag", pl: "die Donnerstage", pos: "n", n: "perşembe", ex: "Wir sehen uns am Donnerstag.", exn: "Perşembe görüşürüz.", topic: "numbers" },
  { id: "de-a1.w066", t: "der Freitag", pl: "die Freitage", pos: "n", n: "cuma", ex: "Am Freitag kommt meine Schwester.", exn: "Cuma günü kız kardeşim geliyor.", topic: "numbers" },
  { id: "de-a1.w067", t: "der Samstag", pl: "die Samstage", pos: "n", n: "cumartesi", ex: "Am Samstag habe ich frei.", exn: "Cumartesi izinliyim.", topic: "numbers", note: "Kuzey Almanya'da „der Sonnabend“ da denir." },
  { id: "de-a1.w068", t: "der Sonntag", pl: "die Sonntage", pos: "n", n: "pazar", ex: "Am Sonntag sind die Geschäfte zu.", exn: "Pazar günü dükkânlar kapalı.", topic: "numbers", note: "Almanya'da pazar günleri dükkânların çoğu kapalıdır." },
  { id: "de-a1.w069", t: "der Januar", pos: "n", n: "ocak", ex: "Im Januar ist es oft kalt.", exn: "Ocakta hava genelde soğuk.", topic: "numbers", note: "Aylar „der“ alır ve „im“ ile kullanılır: im Januar (ocakta)." },
  { id: "de-a1.w070", t: "der Februar", pos: "n", n: "şubat", ex: "Mein Geburtstag ist im Februar.", exn: "Doğum günüm şubatta.", topic: "numbers" },
  { id: "de-a1.w071", t: "der März", pos: "n", n: "mart", ex: "Im März beginnt der Frühling.", exn: "Martta ilkbahar başlıyor.", topic: "numbers" },
  { id: "de-a1.w072", t: "der April", pos: "n", n: "nisan", ex: "Im April regnet es viel.", exn: "Nisanda çok yağmur yağar.", topic: "numbers" },
  { id: "de-a1.w073", t: "der Mai", pos: "n", n: "mayıs", ex: "Der Mai ist mein Lieblingsmonat.", exn: "Mayıs en sevdiğim ay.", topic: "numbers" },
  { id: "de-a1.w074", t: "der Juni", pos: "n", n: "haziran", ex: "Der Kurs endet im Juni.", exn: "Kurs haziranda bitiyor.", topic: "numbers" },
  { id: "de-a1.w075", t: "der Juli", pos: "n", n: "temmuz", ex: "Im Juli haben die Kinder Ferien.", exn: "Temmuzda çocukların okul tatili var.", topic: "numbers", note: "Telefonda „Juni“ ile karışmasın diye bazen „Julei“ diye söylenir." },
  { id: "de-a1.w076", t: "der August", pos: "n", n: "ağustos", ex: "Im August fahren wir in die Türkei.", exn: "Ağustosta Türkiye'ye gidiyoruz.", topic: "numbers", note: "Ay adı olarak vurgu ikinci hecededir: Au-GUST." },
  { id: "de-a1.w077", t: "der September", pos: "n", n: "eylül", ex: "Die Schule beginnt im September.", exn: "Okul eylülde başlıyor.", topic: "numbers" },
  { id: "de-a1.w078", t: "der Oktober", pos: "n", n: "ekim", ex: "Im Oktober ist es oft windig.", exn: "Ekimde hava genelde rüzgârlı.", topic: "numbers" },
  { id: "de-a1.w079", t: "der November", pos: "n", n: "kasım", ex: "Der November ist oft grau.", exn: "Kasım ayı çoğu zaman gri geçer.", topic: "numbers" },
  { id: "de-a1.w080", t: "der Dezember", pos: "n", n: "aralık", ex: "Im Dezember schneit es manchmal.", exn: "Aralıkta bazen kar yağar.", topic: "numbers" },
  { id: "de-a1.w081", t: "die Uhr", pl: "die Uhren", pos: "n", n: "saat (alet); saat (saati söylerken)", ex: "Wie viel Uhr ist es?", exn: "Saat kaç?", topic: "numbers", note: "„Uhr“ saati söylerken kullanılır (um 8 Uhr). Süre için „Stunde“: zwei Stunden = iki saat." },
  { id: "de-a1.w082", t: "die Stunde", pl: "die Stunden", pos: "n", n: "saat (süre)", ex: "Der Film dauert zwei Stunden.", exn: "Film iki saat sürüyor.", topic: "numbers", note: "Süre bildirir. „Saat kaç?“ için „Stunde“ değil, „Uhr“ kullanılır." },
  { id: "de-a1.w083", t: "die Minute", pl: "die Minuten", pos: "n", n: "dakika", ex: "Der Bus kommt in fünf Minuten.", exn: "Otobüs beş dakika sonra geliyor.", topic: "numbers" },
  { id: "de-a1.w084", t: "der Tag", pl: "die Tage", pos: "n", n: "gün", ex: "Ich lerne jeden Tag Deutsch.", exn: "Her gün Almanca çalışıyorum.", topic: "numbers" },
  { id: "de-a1.w085", t: "die Woche", pl: "die Wochen", pos: "n", n: "hafta", ex: "Nächste Woche habe ich Urlaub.", exn: "Gelecek hafta iznim var.", topic: "numbers" },
  { id: "de-a1.w086", t: "der Monat", pl: "die Monate", pos: "n", n: "ay (takvim)", ex: "Die Miete zahle ich jeden Monat.", exn: "Kirayı her ay ödüyorum.", topic: "numbers", note: "Gökyüzündeki ay ise „der Mond“." },
  { id: "de-a1.w087", t: "das Jahr", pl: "die Jahre", pos: "n", n: "yıl, sene", ex: "Ich bin 30 Jahre alt.", exn: "30 yaşındayım.", topic: "numbers", note: "Yaş söylerken: Ich bin … Jahre alt. „Ich habe 30 Jahre“ yanlış." },
  { id: "de-a1.w088", t: "heute", pos: "adv", n: "bugün", ex: "Heute ist Freitag.", exn: "Bugün cuma.", topic: "numbers", note: "„eu“ = oy: heute = hoyte." },
  { id: "de-a1.w089", t: "morgen", pos: "adv", n: "yarın", ex: "Morgen ist Samstag.", exn: "Yarın cumartesi.", topic: "numbers", note: "Küçük harfle „morgen“ = yarın; büyük harfle „der Morgen“ = sabah." },
  { id: "de-a1.w090", t: "gestern", pos: "adv", n: "dün", ex: "Gestern war ich müde.", exn: "Dün yorgundum.", topic: "numbers" },
  { id: "de-a1.w091", t: "das Wochenende", pl: "die Wochenenden", pos: "n", n: "hafta sonu", ex: "Am Wochenende schlafe ich lange.", exn: "Hafta sonu geç saate kadar uyurum.", topic: "numbers", note: "Artikel son kelimeden gelir: die Woche + das Ende → das Wochenende." },
  { id: "de-a1.w092", t: "der Abend", pl: "die Abende", pos: "n", n: "akşam", ex: "Am Abend sehe ich fern.", exn: "Akşamları televizyon izlerim.", topic: "numbers" },
  { id: "de-a1.w093", t: "die Zeit", pl: "die Zeiten", pos: "n", n: "zaman, vakit", ex: "Hast du heute Zeit?", exn: "Bugün vaktin var mı?", topic: "numbers", note: "„z“ = ts, „ei“ = ay: Zeit = tsayt." },
  { id: "de-a1.w094", t: "halb", pos: "x", n: "buçuk (bir sonraki saate yarım var)", ex: "Wir treffen uns um halb vier.", exn: "Üç buçukta buluşuyoruz.", topic: "numbers", note: "Dikkat! „halb vier“ = 3:30, 4:30 değil. Almanca bir sonraki saate bakar: dörde yarım saat var." },
  { id: "de-a1.w095", t: "das Viertel", pl: "die Viertel", pos: "n", n: "çeyrek", ex: "Es ist Viertel nach acht.", exn: "Saat sekizi çeyrek geçiyor.", topic: "numbers", note: "Viertel nach = çeyrek geçiyor, Viertel vor = çeyrek var. Okunuşu: firtıl – i kısa (oysa vier = fiir, i uzun)." },

  /* ---------- food: Essen & Trinken ---------- */
  { id: "de-a1.w096", t: "das Brot", pl: "die Brote", pos: "n", n: "ekmek", ex: "Das Brot ist noch warm.", exn: "Ekmek hâlâ sıcak.", topic: "food" },
  { id: "de-a1.w097", t: "das Brötchen", pl: "die Brötchen", pos: "n", n: "küçük ekmek (sandviç ekmeği)", ex: "Ich nehme zwei Brötchen.", exn: "İki tane küçük ekmek alayım.", topic: "food", note: "-chen ile biten kelimeler „das“ alır ve çoğulda değişmez: das Brötchen – die Brötchen." },
  { id: "de-a1.w098", t: "das Wasser", pos: "n", n: "su", ex: "Ein Glas Wasser, bitte.", exn: "Bir bardak su lütfen.", topic: "food", note: "„W“ = v: Wasser = vasser. Maden suyu: das Mineralwasser." },
  { id: "de-a1.w099", t: "der Kaffee", pos: "n", n: "kahve", ex: "Trinkst du Kaffee mit Milch?", exn: "Kahveyi sütlü mü içiyorsun?", topic: "food", note: "Siparişte genelde çoğul eki almaz: Zwei Kaffee, bitte." },
  { id: "de-a1.w100", t: "der Tee", pos: "n", n: "çay", ex: "Möchtest du einen Tee?", exn: "Çay ister misin?", topic: "food", note: "Almanya'da „Tee“ denince çoğu zaman bitki ya da meyve çayı anlaşılır. Bizim bildiğimiz çay için „schwarzer Tee“ de." },
  { id: "de-a1.w101", t: "die Milch", pos: "n", n: "süt", ex: "Die Milch ist im Kühlschrank.", exn: "Süt buzdolabında.", topic: "food", note: "„ch“ burada „ç“ değil; dil damağa yaklaşarak çıkan yumuşak bir „h“dir (ich-sesi): milh." },
  { id: "de-a1.w102", t: "der Saft", pl: "die Säfte", pos: "n", n: "meyve suyu", ex: "Einen Apfelsaft für mich, bitte.", exn: "Bana bir elma suyu lütfen.", topic: "food" },
  { id: "de-a1.w103", t: "der Apfel", pl: "die Äpfel", pos: "n", n: "elma", ex: "Der Apfel ist süß.", exn: "Elma tatlı.", topic: "food", note: "Çoğulda a → ä olur: die Äpfel." },
  { id: "de-a1.w104", t: "die Banane", pl: "die Bananen", pos: "n", n: "muz", ex: "Die Bananen sind noch grün.", exn: "Muzlar daha yeşil.", topic: "food" },
  { id: "de-a1.w105", t: "die Kartoffel", pl: "die Kartoffeln", pos: "n", n: "patates", ex: "Ich koche Kartoffeln.", exn: "Patates haşlıyorum.", topic: "food" },
  { id: "de-a1.w106", t: "die Tomate", pl: "die Tomaten", pos: "n", n: "domates", ex: "Die Tomaten sind sehr frisch.", exn: "Domatesler çok taze.", topic: "food" },
  { id: "de-a1.w107", t: "das Gemüse", pos: "n", n: "sebze", ex: "Ich esse viel Gemüse.", exn: "Çok sebze yerim.", topic: "food", note: "Tekil kullanılır ama anlamı çoğuldur: Gemüse = sebzeler." },
  { id: "de-a1.w108", t: "das Obst", pos: "n", n: "meyve", ex: "Obst ist gesund.", exn: "Meyve sağlıklıdır.", topic: "food", note: "Toplu isimdir, çoğulu yoktur. „Meyveler“ için de „Obst“ denir." },
  { id: "de-a1.w109", t: "das Fleisch", pos: "n", n: "et", ex: "Ich esse kein Fleisch.", exn: "Et yemem.", topic: "food", note: "„ei“ = ay, „sch“ = ş: Fleisch = flayş." },
  { id: "de-a1.w110", t: "das Hähnchen", pl: "die Hähnchen", pos: "n", n: "tavuk (yemek olarak)", ex: "Das Hähnchen ist sehr lecker.", exn: "Tavuk çok lezzetli.", topic: "food", note: "Canlı tavuk: das Huhn. Yemek olarak genelde „Hähnchen“ denir." },
  { id: "de-a1.w111", t: "der Fisch", pl: "die Fische", pos: "n", n: "balık", ex: "Am Freitag essen wir Fisch.", exn: "Cuma günü balık yeriz.", topic: "food", note: "„sch“ = ş: Fisch = fiş." },
  { id: "de-a1.w112", t: "der Reis", pos: "n", n: "pirinç; pilav", ex: "Der Reis ist fertig.", exn: "Pilav hazır.", topic: "food", note: "„ei“ = ay: Reis = rays. Seyahat ise başka bir kelime: die Reise." },
  { id: "de-a1.w113", t: "der Käse", pos: "n", n: "peynir", ex: "Ich esse Käse zum Frühstück.", exn: "Kahvaltıda peynir yerim.", topic: "food", note: "„ä“ açık bir e'dir: Käse = keeze. Beyaz peynir marketlerde genelde „Hirtenkäse“ ya da „Feta“ diye geçer." },
  { id: "de-a1.w114", t: "das Ei", pl: "die Eier", pos: "n", n: "yumurta", ex: "Ich esse jeden Morgen ein Ei.", exn: "Her sabah bir yumurta yerim.", topic: "food", note: "„Ei“ = ay okunur. Çoğulu -er alır: die Eier." },
  { id: "de-a1.w115", t: "der Zucker", pos: "n", n: "şeker (toz şeker)", ex: "Ohne Zucker, bitte.", exn: "Şekersiz lütfen.", topic: "food", note: "„z“ = ts: Zucker = tsukker. Yenen şeker/bonbon: das Bonbon." },
  { id: "de-a1.w116", t: "das Salz", pos: "n", n: "tuz", ex: "Die Suppe braucht noch Salz.", exn: "Çorbaya biraz daha tuz lazım.", topic: "food" },
  { id: "de-a1.w117", t: "die Suppe", pl: "die Suppen", pos: "n", n: "çorba", ex: "Die Suppe ist zu heiß.", exn: "Çorba çok sıcak.", topic: "food" },
  { id: "de-a1.w118", t: "der Kuchen", pl: "die Kuchen", pos: "n", n: "kek, pasta", ex: "Möchtest du ein Stück Kuchen?", exn: "Bir dilim kek ister misin?", topic: "food", note: "Kremalı, katlı pasta (örneğin doğum günü pastası): die Torte." },
  { id: "de-a1.w119", t: "das Frühstück", pos: "n", n: "kahvaltı", ex: "Das Frühstück ist um acht.", exn: "Kahvaltı saat sekizde.", topic: "food", note: "Kahvaltı yapmak: frühstücken." },
  { id: "de-a1.w120", t: "das Mittagessen", pos: "n", n: "öğle yemeği", ex: "Was gibt es zum Mittagessen?", exn: "Öğle yemeğinde ne var?", topic: "food" },
  { id: "de-a1.w121", t: "das Abendessen", pos: "n", n: "akşam yemeği", ex: "Das Abendessen ist fertig!", exn: "Akşam yemeği hazır!", topic: "food" },
  { id: "de-a1.w122", t: "essen", pos: "v", n: "yemek (yemek yemek)", ex: "Was isst du gern?", exn: "Ne yemeyi seversin?", topic: "food", note: "Kök ünlüsü değişir: ich esse, du isst, er isst." },
  { id: "de-a1.w123", t: "trinken", pos: "v", n: "içmek", ex: "Wir trinken zusammen Tee.", exn: "Birlikte çay içiyoruz.", topic: "food", note: "Sigara içmek için „trinken“ değil, „rauchen“ kullanılır." },
  { id: "de-a1.w124", t: "der Hunger", pos: "n", n: "açlık", ex: "Ich habe Hunger.", exn: "Acıktım.", topic: "food", note: "„Aç olmak“ = Hunger haben. „Ich bin Hunger“ yanlış." },
  { id: "de-a1.w125", t: "der Durst", pos: "n", n: "susuzluk", ex: "Hast du Durst?", exn: "Susadın mı?", topic: "food", note: "Susamak = Durst haben: Ich habe Durst." },

  /* ---------- home: Wohnen & Haushalt ---------- */
  { id: "de-a1.w126", t: "die Wohnung", pl: "die Wohnungen", pos: "n", n: "daire, ev", ex: "Unsere Wohnung hat drei Zimmer.", exn: "Evimiz üç odalı.", topic: "home", note: "Apartmandaki daire: die Wohnung. Müstakil ev ya da bina: das Haus." },
  { id: "de-a1.w127", t: "das Haus", pl: "die Häuser", pos: "n", n: "ev; bina", ex: "Ich bin heute zu Hause.", exn: "Bugün evdeyim.", topic: "home", note: "zu Hause = evde, nach Hause = eve: Ich gehe nach Hause." },
  { id: "de-a1.w128", t: "das Zimmer", pl: "die Zimmer", pos: "n", n: "oda", ex: "Mein Zimmer ist klein.", exn: "Odam küçük.", topic: "home" },
  { id: "de-a1.w129", t: "die Küche", pl: "die Küchen", pos: "n", n: "mutfak", ex: "Die Küche ist sehr hell.", exn: "Mutfak çok aydınlık.", topic: "home", note: "„ch“ burada yumuşak bir h'dir: Küche = kühe (küçe değil)." },
  { id: "de-a1.w130", t: "das Bad", pl: "die Bäder", pos: "n", n: "banyo", ex: "Das Bad ist rechts.", exn: "Banyo sağda.", topic: "home" },
  { id: "de-a1.w131", t: "das Schlafzimmer", pl: "die Schlafzimmer", pos: "n", n: "yatak odası", ex: "Das Schlafzimmer hat einen Balkon.", exn: "Yatak odasının balkonu var.", topic: "home", note: "Bileşik kelimelerde artikel son kelimeden gelir: schlafen + das Zimmer → das Schlafzimmer." },
  { id: "de-a1.w132", t: "das Wohnzimmer", pl: "die Wohnzimmer", pos: "n", n: "oturma odası, salon", ex: "Wir sitzen im Wohnzimmer.", exn: "Salonda oturuyoruz.", topic: "home" },
  { id: "de-a1.w133", t: "der Tisch", pl: "die Tische", pos: "n", n: "masa", ex: "Der Tisch ist neu.", exn: "Masa yeni.", topic: "home" },
  { id: "de-a1.w134", t: "der Stuhl", pl: "die Stühle", pos: "n", n: "sandalye", ex: "Ist der Stuhl frei?", exn: "Bu sandalye boş mu?", topic: "home" },
  { id: "de-a1.w135", t: "das Bett", pl: "die Betten", pos: "n", n: "yatak", ex: "Das Kind ist schon im Bett.", exn: "Çocuk çoktan yattı.", topic: "home", note: "Yatmaya gitmek: ins Bett gehen." },
  { id: "de-a1.w136", t: "das Sofa", pl: "die Sofas", pos: "n", n: "kanepe", ex: "Die Katze schläft auf dem Sofa.", exn: "Kedi kanepede uyuyor.", topic: "home" },
  { id: "de-a1.w137", t: "der Schrank", pl: "die Schränke", pos: "n", n: "dolap", ex: "Die Teller sind im Schrank.", exn: "Tabaklar dolapta.", topic: "home" },
  { id: "de-a1.w138", t: "die Lampe", pl: "die Lampen", pos: "n", n: "lamba", ex: "Mach bitte die Lampe an.", exn: "Lambayı açar mısın lütfen?", topic: "home" },
  { id: "de-a1.w139", t: "das Fenster", pl: "die Fenster", pos: "n", n: "pencere", ex: "Kannst du bitte das Fenster öffnen?", exn: "Pencereyi açar mısın lütfen?", topic: "home", note: "-er ile biten birçok kelime gibi çoğulda değişmez: das Fenster – die Fenster." },
  { id: "de-a1.w140", t: "die Tür", pl: "die Türen", pos: "n", n: "kapı", ex: "Mach bitte die Tür zu.", exn: "Kapıyı kapatır mısın lütfen?", topic: "home" },
  { id: "de-a1.w141", t: "der Schlüssel", pl: "die Schlüssel", pos: "n", n: "anahtar", ex: "Wo ist mein Schlüssel?", exn: "Anahtarım nerede?", topic: "home" },
  { id: "de-a1.w142", t: "der Kühlschrank", pl: "die Kühlschränke", pos: "n", n: "buzdolabı", ex: "Der Kühlschrank ist leer.", exn: "Buzdolabı boş.", topic: "home", note: "kühl (serin) + der Schrank (dolap) = buzdolabı." },
  { id: "de-a1.w143", t: "die Miete", pl: "die Mieten", pos: "n", n: "kira", ex: "Die Miete ist sehr hoch.", exn: "Kira çok yüksek.", topic: "home", note: "Kiralamak: mieten. Kiracı: der Mieter. Ev sahibi: der Vermieter." },
  { id: "de-a1.w144", t: "der Balkon", pl: "die Balkone", pos: "n", n: "balkon", ex: "Im Sommer frühstücken wir auf dem Balkon.", exn: "Yazın balkonda kahvaltı yaparız.", topic: "home" },
  { id: "de-a1.w145", t: "der Garten", pl: "die Gärten", pos: "n", n: "bahçe", ex: "Das Haus hat einen kleinen Garten.", exn: "Evin küçük bir bahçesi var.", topic: "home" },
  { id: "de-a1.w146", t: "die Toilette", pl: "die Toiletten", pos: "n", n: "tuvalet", ex: "Die Toilette ist neben dem Bad.", exn: "Tuvalet banyonun yanında.", topic: "home", note: "Günlük dilde „das Klo“ da denir; tabelalarda „WC“ yazar." },
  { id: "de-a1.w147", t: "wohnen", pos: "v", n: "oturmak, ikamet etmek", ex: "Ich wohne in Bonn.", exn: "Bonn'da oturuyorum.", topic: "home", note: "Bir yerde yaşamak/oturmak = wohnen. Sandalyede oturmak = sitzen. Karıştırma!" },
  { id: "de-a1.w148", t: "kochen", pos: "v", n: "yemek pişirmek; kaynatmak", ex: "Heute koche ich Linsensuppe.", exn: "Bugün mercimek çorbası pişiriyorum.", topic: "home" },
  { id: "de-a1.w149", t: "putzen", pos: "v", n: "temizlemek", ex: "Am Samstag putzen wir die Wohnung.", exn: "Cumartesi evi temizliyoruz.", topic: "home", note: "Diş fırçalamak da bu fiille söylenir: Zähne putzen." },
  { id: "de-a1.w150", t: "waschen", pos: "v", n: "yıkamak", ex: "Er wäscht das Auto.", exn: "Arabayı yıkıyor.", topic: "home", note: "Kök ünlüsü değişir: du wäschst, er wäscht. Çamaşır yıkamak: Wäsche waschen." },

  /* ---------- city: Stadt, Wege & Verkehr ---------- */
  { id: "de-a1.w151", t: "die Stadt", pl: "die Städte", pos: "n", n: "şehir", ex: "Köln ist eine große Stadt.", exn: "Köln büyük bir şehir.", topic: "city", note: "Şehir merkezi: die Innenstadt ya da das Zentrum." },
  { id: "de-a1.w152", t: "die Straße", pl: "die Straßen", pos: "n", n: "cadde, sokak", ex: "Ich wohne in der Bergstraße.", exn: "Bergstraße'de oturuyorum.", topic: "city", note: "Kelime başındaki „st“ = şt: Straße = ştrase. „ß“ = ss." },
  { id: "de-a1.w153", t: "der Bahnhof", pl: "die Bahnhöfe", pos: "n", n: "tren istasyonu, gar", ex: "Wie komme ich zum Bahnhof?", exn: "Gara nasıl giderim?", topic: "city", note: "Ana tren istasyonu: der Hauptbahnhof (kısaca Hbf)." },
  { id: "de-a1.w154", t: "die Haltestelle", pl: "die Haltestellen", pos: "n", n: "durak", ex: "Die Haltestelle ist gleich da vorne.", exn: "Durak hemen ileride.", topic: "city" },
  { id: "de-a1.w155", t: "der Bus", pl: "die Busse", pos: "n", n: "otobüs", ex: "Ich fahre mit dem Bus zur Arbeit.", exn: "İşe otobüsle gidiyorum.", topic: "city", note: "Araçla gitmek: mit dem Bus / mit dem Zug / mit dem Auto fahren." },
  { id: "de-a1.w156", t: "der Zug", pl: "die Züge", pos: "n", n: "tren", ex: "Der Zug hat Verspätung.", exn: "Tren gecikmeli.", topic: "city", note: "„Z“ = ts: Zug = tsuuk." },
  { id: "de-a1.w157", t: "die U-Bahn", pl: "die U-Bahnen", pos: "n", n: "metro", ex: "Die U-Bahn kommt alle fünf Minuten.", exn: "Metro beş dakikada bir geliyor.", topic: "city", note: "S-Bahn ise şehir içi ve banliyö trenidir." },
  { id: "de-a1.w158", t: "das Auto", pl: "die Autos", pos: "n", n: "araba", ex: "Mein Auto ist alt.", exn: "Arabam eski.", topic: "city" },
  { id: "de-a1.w159", t: "das Fahrrad", pl: "die Fahrräder", pos: "n", n: "bisiklet", ex: "Im Sommer fahre ich Fahrrad.", exn: "Yazın bisiklete binerim.", topic: "city", note: "Bisiklete binmek: Fahrrad fahren." },
  { id: "de-a1.w160", t: "das Taxi", pl: "die Taxis", pos: "n", n: "taksi", ex: "Wir nehmen ein Taxi.", exn: "Taksiyle gidiyoruz.", topic: "city" },
  { id: "de-a1.w161", t: "die Fahrkarte", pl: "die Fahrkarten", pos: "n", n: "bilet (otobüs, tren)", ex: "Eine Fahrkarte nach Bonn, bitte.", exn: "Bonn'a bir bilet lütfen.", topic: "city", note: "Günlük dilde „das Ticket“ de denir. Almanya'da bileti genelde binmeden önce alırsın." },
  { id: "de-a1.w162", t: "der Flughafen", pl: "die Flughäfen", pos: "n", n: "havalimanı", ex: "Der Flughafen ist weit weg.", exn: "Havalimanı çok uzak.", topic: "city" },
  { id: "de-a1.w163", t: "die Bank", pl: "die Banken", pos: "n", n: "banka", ex: "Ich muss heute zur Bank.", exn: "Bugün bankaya gitmem lazım.", topic: "city", note: "Oturulan bank da „die Bank“tır ama çoğulu farklıdır: die Bänke." },
  { id: "de-a1.w164", t: "die Post", pos: "n", n: "postane; posta", ex: "Die Post ist neben der Bank.", exn: "Postane bankanın yanında.", topic: "city", note: "Hem postane hem de gelen mektuplar: Ist Post für mich da?" },
  { id: "de-a1.w165", t: "die Apotheke", pl: "die Apotheken", pos: "n", n: "eczane", ex: "Ich hole Tabletten aus der Apotheke.", exn: "Eczaneden ilaç alıyorum.", topic: "city", note: "İlaç: das Medikament. Hafta sonu ve gece nöbetçi eczane: die Notdienst-Apotheke." },
  { id: "de-a1.w166", t: "der Platz", pl: "die Plätze", pos: "n", n: "meydan; yer", ex: "Ist hier noch ein Platz frei?", exn: "Burada boş yer var mı?", topic: "city", note: "İki anlamı var: şehirde meydan (der Marktplatz) ve oturacak yer." },
  { id: "de-a1.w167", t: "die Ampel", pl: "die Ampeln", pos: "n", n: "trafik ışığı", ex: "An der Ampel gehen Sie links.", exn: "Trafik ışığından sola dönün.", topic: "city" },
  { id: "de-a1.w168", t: "links", pos: "adv", n: "solda; sola", ex: "Das Café ist links.", exn: "Kafe solda.", topic: "city" },
  { id: "de-a1.w169", t: "rechts", pos: "adv", n: "sağda; sağa", ex: "Gehen Sie hier rechts.", exn: "Buradan sağa dönün.", topic: "city" },
  { id: "de-a1.w170", t: "geradeaus", pos: "adv", n: "dümdüz, düz ileri", ex: "Gehen Sie immer geradeaus.", exn: "Hep dümdüz gidin.", topic: "city" },
  { id: "de-a1.w171", t: "in der Nähe", pos: "phr", n: "yakında (yakın bir yerde), yakınlarda, civarda", ex: "Gibt es hier in der Nähe einen Supermarkt?", exn: "Yakınlarda bir süpermarket var mı?", topic: "city" },
  { id: "de-a1.w172", t: "weit", pos: "adj", n: "uzak", ex: "Ist es weit bis zum Bahnhof?", exn: "Gara kadar uzak mı?", topic: "city", note: "Zıttı: nah (yakın). „weit weg“ = çok uzakta." },
  { id: "de-a1.w173", t: "fahren", pos: "v", n: "(araçla) gitmek; (araç) sürmek", ex: "Wir fahren morgen nach Berlin.", exn: "Yarın Berlin'e gidiyoruz.", topic: "city", note: "Kök ünlüsü değişir: du fährst, er fährt. Yürüyerek gidiyorsan: gehen." },
  { id: "de-a1.w174", t: "der Weg", pl: "die Wege", pos: "n", n: "yol", ex: "Ich frage nach dem Weg.", exn: "Yolu soruyorum.", topic: "city", note: "„e“ uzun okunur: Weg = veek." },

  /* ---------- shop: Einkaufen & Kleidung ---------- */
  { id: "de-a1.w175", t: "kaufen", pos: "v", n: "satın almak", ex: "Ich kaufe ein neues Handy.", exn: "Yeni bir cep telefonu alıyorum.", topic: "shop", note: "Satmak: verkaufen. Satıcı: der Verkäufer." },
  { id: "de-a1.w176", t: "bezahlen", pos: "v", n: "ödemek", ex: "Kann ich mit Karte bezahlen?", exn: "Kartla ödeyebilir miyim?", topic: "shop", note: "Günlük dilde kısaca „zahlen“ de denir." },
  { id: "de-a1.w177", t: "kosten", pos: "v", n: "fiyatı … olmak, tutmak", ex: "Was kostet die Jacke?", exn: "Ceket ne kadar?", topic: "shop", note: "Fiyat sorarken: Was kostet …? ya da Wie viel kostet …?" },
  { id: "de-a1.w178", t: "das Geld", pos: "n", n: "para", ex: "Ich habe kein Geld dabei.", exn: "Yanımda para yok.", topic: "shop", note: "Bozuk para: das Kleingeld." },
  { id: "de-a1.w179", t: "der Euro", pl: "die Euros", pos: "n", n: "avro", ex: "Das macht zwölf Euro, bitte.", exn: "Hepsi on iki avro.", topic: "shop", note: "Sayıdan sonra çoğul eki almaz: zwei Euro, zehn Euro." },
  { id: "de-a1.w180", t: "der Preis", pl: "die Preise", pos: "n", n: "fiyat", ex: "Der Preis ist gut.", exn: "Fiyat iyi.", topic: "shop" },
  { id: "de-a1.w181", t: "billig", pos: "adj", n: "ucuz", ex: "Das Obst ist hier billig.", exn: "Burada meyve ucuz.", topic: "shop", note: "Bazen „kalitesiz“ çağrışımı yapar. Daha nötr: günstig (uygun fiyatlı)." },
  { id: "de-a1.w182", t: "teuer", pos: "adj", n: "pahalı", ex: "Die Schuhe sind zu teuer.", exn: "Ayakkabılar çok pahalı.", topic: "shop", note: "„eu“ = oy: teuer = toyer. „zu teuer“ = fazla pahalı." },
  { id: "de-a1.w183", t: "der Supermarkt", pl: "die Supermärkte", pos: "n", n: "süpermarket", ex: "Der Supermarkt ist bis 22 Uhr offen.", exn: "Süpermarket saat 22'ye kadar açık.", topic: "shop" },
  { id: "de-a1.w184", t: "der Laden", pl: "die Läden", pos: "n", n: "dükkân, mağaza", ex: "Der Laden hat heute zu.", exn: "Dükkân bugün kapalı.", topic: "shop", note: "Daha resmî: das Geschäft." },
  { id: "de-a1.w185", t: "die Kasse", pl: "die Kassen", pos: "n", n: "kasa", ex: "Bitte zahlen Sie an der Kasse.", exn: "Lütfen kasada ödeyin.", topic: "shop" },
  { id: "de-a1.w186", t: "die Tasche", pl: "die Taschen", pos: "n", n: "çanta; cep", ex: "Das Handy ist in meiner Tasche.", exn: "Telefon çantamda.", topic: "shop", note: "Hem çanta hem cep anlamına gelir; pantolon cebi: die Hosentasche." },
  { id: "de-a1.w187", t: "die Kleidung", pos: "n", n: "giysi, kıyafet", ex: "Ich brauche neue Kleidung.", exn: "Yeni kıyafetlere ihtiyacım var.", topic: "shop", note: "Tekil kullanılır ama „kıyafetler“ anlamı taşır." },
  { id: "de-a1.w188", t: "die Hose", pl: "die Hosen", pos: "n", n: "pantolon", ex: "Die Hose ist zu lang.", exn: "Pantolon çok uzun.", topic: "shop", note: "Kot pantolon: die Jeans. Şort: die kurze Hose." },
  { id: "de-a1.w189", t: "das Hemd", pl: "die Hemden", pos: "n", n: "gömlek", ex: "Das Hemd ist zu klein.", exn: "Gömlek çok küçük.", topic: "shop" },
  { id: "de-a1.w190", t: "das T-Shirt", pl: "die T-Shirts", pos: "n", n: "tişört", ex: "Das T-Shirt kostet nur fünf Euro.", exn: "Tişört sadece beş avro.", topic: "shop" },
  { id: "de-a1.w191", t: "die Jacke", pl: "die Jacken", pos: "n", n: "ceket, mont", ex: "Nimm eine Jacke mit, es ist kalt.", exn: "Yanına bir mont al, hava soğuk.", topic: "shop" },
  { id: "de-a1.w192", t: "der Schuh", pl: "die Schuhe", pos: "n", n: "ayakkabı", ex: "Zieh bitte die Schuhe aus.", exn: "Ayakkabılarını çıkar lütfen.", topic: "shop" },
  { id: "de-a1.w193", t: "das Kleid", pl: "die Kleider", pos: "n", n: "elbise", ex: "Das Kleid steht dir gut.", exn: "Elbise sana çok yakışmış.", topic: "shop", note: "Çoğulu „die Kleider“ bazen genel olarak „giysiler“ anlamında da kullanılır." },
  { id: "de-a1.w194", t: "die Größe", pl: "die Größen", pos: "n", n: "beden; boy", ex: "Haben Sie die Hose auch in Größe 40?", exn: "Bu pantolonun 40 bedeni de var mı?", topic: "shop" },
  { id: "de-a1.w195", t: "die Flasche", pl: "die Flaschen", pos: "n", n: "şişe", ex: "Eine Flasche Wasser kostet einen Euro.", exn: "Bir şişe su bir avro.", topic: "shop", note: "Almanya'da birçok şişede depozito (das Pfand) vardır; boş şişeyi markete geri götürürsün." },
  { id: "de-a1.w196", t: "das Kilo", pl: "die Kilos", pos: "n", n: "kilo", ex: "Zwei Kilo Kartoffeln, bitte.", exn: "İki kilo patates lütfen.", topic: "shop", note: "Sayıdan sonra değişmez: zwei Kilo („zwei Kilos“ değil). Yarım kilo: ein Pfund." },

  /* ---------- work: Arbeit, Schule & Ämter ---------- */
  { id: "de-a1.w197", t: "die Arbeit", pl: "die Arbeiten", pos: "n", n: "iş", ex: "Ich gehe jetzt zur Arbeit.", exn: "Şimdi işe gidiyorum.", topic: "work", note: "İşe gitmek: zur Arbeit gehen. Çoğulu daha çok „yapılan işler, ödevler“ anlamındadır." },
  { id: "de-a1.w198", t: "arbeiten", pos: "v", n: "çalışmak (işte)", ex: "Ich arbeite in einem Restaurant.", exn: "Bir restoranda çalışıyorum.", topic: "work", note: "Ders çalışmak „arbeiten“ değil, „lernen“dir." },
  { id: "de-a1.w199", t: "der Beruf", pl: "die Berufe", pos: "n", n: "meslek", ex: "Was sind Sie von Beruf?", exn: "Mesleğiniz ne?", topic: "work", note: "Meslek söylerken artikel kullanılmaz: Ich bin Lehrer („ein Lehrer“ değil)." },
  { id: "de-a1.w200", t: "die Firma", pl: "die Firmen", pos: "n", n: "firma, şirket", ex: "Die Firma hat 50 Mitarbeiter.", exn: "Firmanın 50 çalışanı var.", topic: "work", note: "Çoğulu düzensizdir: die Firmen." },
  { id: "de-a1.w201", t: "der Kollege", pl: "die Kollegen", pos: "n", n: "iş arkadaşı (erkek)", ex: "Mein Kollege kommt aus Polen.", exn: "İş arkadaşım Polonyalı.", topic: "work", note: "Kadın: die Kollegin. İşteki kişilere „Freund“ değil, „Kollege“ denir." },
  { id: "de-a1.w202", t: "der Chef", pl: "die Chefs", pos: "n", n: "patron, amir", ex: "Der Chef ist heute im Urlaub.", exn: "Patron bugün izinde.", topic: "work", note: "Kadın: die Chefin. „Ch“ burada „ş“ okunur: şef." },
  { id: "de-a1.w203", t: "das Büro", pl: "die Büros", pos: "n", n: "ofis, büro", ex: "Ich bin bis fünf im Büro.", exn: "Saat beşe kadar ofisteyim.", topic: "work" },
  { id: "de-a1.w204", t: "der Lehrer", pl: "die Lehrer", pos: "n", n: "öğretmen (erkek)", ex: "Unser Lehrer erklärt sehr gut.", exn: "Öğretmenimiz çok iyi anlatıyor.", topic: "work", note: "Kadın öğretmen: die Lehrerin, çoğulu die Lehrerinnen." },
  { id: "de-a1.w205", t: "die Schule", pl: "die Schulen", pos: "n", n: "okul", ex: "Die Kinder sind in der Schule.", exn: "Çocuklar okulda.", topic: "work", note: "„sch“ = ş: Schule = şule." },
  { id: "de-a1.w206", t: "der Kurs", pl: "die Kurse", pos: "n", n: "kurs", ex: "Der Deutschkurs beginnt im März.", exn: "Almanca kursu martta başlıyor.", topic: "work" },
  { id: "de-a1.w207", t: "lernen", pos: "v", n: "öğrenmek; ders çalışmak", ex: "Ich lerne seit drei Monaten Deutsch.", exn: "Üç aydır Almanca öğreniyorum.", topic: "work", note: "Üniversitede okumak: studieren. „Ich studiere“ = üniversitede okuyorum." },
  { id: "de-a1.w208", t: "das Formular", pl: "die Formulare", pos: "n", n: "form", ex: "Bitte füllen Sie das Formular aus.", exn: "Lütfen formu doldurun.", topic: "work", note: "Form doldurmak: ein Formular ausfüllen (ayrılabilen fiil)." },
  { id: "de-a1.w209", t: "der Termin", pl: "die Termine", pos: "n", n: "randevu", ex: "Ich habe am Montag einen Termin beim Arzt.", exn: "Pazartesi doktordan randevum var.", topic: "work", note: "Dikkat: Türkçedeki „termin“ (teslim tarihi) ile karıştırma. Almancada „Termin“ = randevu." },
  { id: "de-a1.w210", t: "der Pass", pl: "die Pässe", pos: "n", n: "pasaport", ex: "Ihren Pass, bitte.", exn: "Pasaportunuz lütfen.", topic: "work", note: "Tam adı: der Reisepass. Kimlik kartı: der Ausweis (Personalausweis)." },
  { id: "de-a1.w211", t: "die Adresse", pl: "die Adressen", pos: "n", n: "adres", ex: "Wie ist Ihre Adresse?", exn: "Adresiniz nedir?", topic: "work" },
  { id: "de-a1.w212", t: "die Telefonnummer", pl: "die Telefonnummern", pos: "n", n: "telefon numarası", ex: "Hast du meine Telefonnummer?", exn: "Telefon numaram sende var mı?", topic: "work" },
  { id: "de-a1.w213", t: "die E-Mail", pl: "die E-Mails", pos: "n", n: "e-posta", ex: "Ich schreibe Ihnen eine E-Mail.", exn: "Size bir e-posta yazacağım.", topic: "work", note: "Okunuşu: iimeyl. Güney Almanya, Avusturya ve İsviçre'de „das E-Mail“ da denir." },
  { id: "de-a1.w214", t: "der Computer", pl: "die Computer", pos: "n", n: "bilgisayar", ex: "Der Computer ist zu langsam.", exn: "Bilgisayar çok yavaş.", topic: "work" },
  { id: "de-a1.w215", t: "das Amt", pl: "die Ämter", pos: "n", n: "resmî daire", ex: "Ich muss morgen zum Amt.", exn: "Yarın resmî daireye gitmem lazım.", topic: "work", note: "Örnekler: das Bürgeramt (belediyenin vatandaş hizmetleri bürosu), das Finanzamt (vergi dairesi)." },
  { id: "de-a1.w216", t: "unterschreiben", pos: "v", n: "imzalamak", ex: "Bitte unterschreiben Sie hier.", exn: "Lütfen burayı imzalayın.", topic: "work", note: "Bu fiil ayrılmaz: Ich unterschreibe. İmza: die Unterschrift." },

  /* ---------- body: Körper & Gesundheit ---------- */
  { id: "de-a1.w217", t: "der Kopf", pl: "die Köpfe", pos: "n", n: "baş, kafa", ex: "Mein Kopf tut weh.", exn: "Başım ağrıyor.", topic: "body", note: "Ağrıyı söylemenin kolay yolu: … tut weh (tekil), … tun weh (çoğul)." },
  { id: "de-a1.w218", t: "das Auge", pl: "die Augen", pos: "n", n: "göz", ex: "Sie hat braune Augen.", exn: "Gözleri kahverengi.", topic: "body" },
  { id: "de-a1.w219", t: "das Ohr", pl: "die Ohren", pos: "n", n: "kulak", ex: "Hast du Ohrenschmerzen?", exn: "Kulağın ağrıyor mu?", topic: "body" },
  { id: "de-a1.w220", t: "die Nase", pl: "die Nasen", pos: "n", n: "burun", ex: "Meine Nase läuft.", exn: "Burnum akıyor.", topic: "body" },
  { id: "de-a1.w221", t: "der Mund", pl: "die Münder", pos: "n", n: "ağız", ex: "Machen Sie bitte den Mund auf.", exn: "Ağzınızı açın lütfen.", topic: "body" },
  { id: "de-a1.w222", t: "der Zahn", pl: "die Zähne", pos: "n", n: "diş", ex: "Ich putze zweimal am Tag die Zähne.", exn: "Günde iki kez dişlerimi fırçalarım.", topic: "body", note: "Diş hekimi: der Zahnarzt / die Zahnärztin." },
  { id: "de-a1.w223", t: "die Hand", pl: "die Hände", pos: "n", n: "el", ex: "Wasch dir bitte die Hände.", exn: "Ellerini yıka lütfen.", topic: "body" },
  { id: "de-a1.w224", t: "der Arm", pl: "die Arme", pos: "n", n: "kol", ex: "Mein Arm ist gebrochen.", exn: "Kolum kırık.", topic: "body", note: "Dikkat: „arm“ küçük harfle sıfat olarak „fakir“ demektir." },
  { id: "de-a1.w225", t: "das Bein", pl: "die Beine", pos: "n", n: "bacak", ex: "Nach dem Sport tun mir die Beine weh.", exn: "Spordan sonra bacaklarım ağrıyor.", topic: "body" },
  { id: "de-a1.w226", t: "der Fuß", pl: "die Füße", pos: "n", n: "ayak", ex: "Wir gehen zu Fuß.", exn: "Yürüyerek gidiyoruz.", topic: "body", note: "zu Fuß gehen = yürüyerek gitmek." },
  { id: "de-a1.w227", t: "der Bauch", pl: "die Bäuche", pos: "n", n: "karın", ex: "Das Kind hat Bauchschmerzen.", exn: "Çocuğun karnı ağrıyor.", topic: "body" },
  { id: "de-a1.w228", t: "der Rücken", pl: "die Rücken", pos: "n", n: "sırt", ex: "Ich habe Probleme mit dem Rücken.", exn: "Sırtımdan rahatsızım.", topic: "body" },
  { id: "de-a1.w229", t: "der Arzt", pl: "die Ärzte", pos: "n", n: "doktor, hekim", ex: "Ich gehe heute zum Arzt.", exn: "Bugün doktora gidiyorum.", topic: "body", note: "Kadın doktor: die Ärztin. Doktora gitmek: zum Arzt gehen." },
  { id: "de-a1.w230", t: "das Krankenhaus", pl: "die Krankenhäuser", pos: "n", n: "hastane", ex: "Mein Opa liegt im Krankenhaus.", exn: "Dedem hastanede yatıyor.", topic: "body", note: "krank (hasta) + das Haus (ev) = hastane." },
  { id: "de-a1.w231", t: "krank", pos: "adj", n: "hasta", ex: "Ich bin krank und bleibe zu Hause.", exn: "Hastayım, evde kalıyorum.", topic: "body", note: "Hasta olan kişi (isim olarak): der Patient / die Patientin." },
  { id: "de-a1.w232", t: "gesund", pos: "adj", n: "sağlıklı", ex: "Bleib gesund!", exn: "Sağlıcakla kal!", topic: "body" },
  { id: "de-a1.w233", t: "der Schmerz", pl: "die Schmerzen", pos: "n", n: "ağrı, acı", ex: "Ich habe starke Schmerzen.", exn: "Çok ağrım var.", topic: "body", note: "Genelde çoğul kullanılır: Kopfschmerzen (baş ağrısı), Bauchschmerzen (karın ağrısı)." },

  /* ---------- free: Freizeit, Wetter & Natur ---------- */
  { id: "de-a1.w234", t: "das Wetter", pos: "n", n: "hava (durumu)", ex: "Wie ist das Wetter heute?", exn: "Bugün hava nasıl?", topic: "free", note: "Soluduğumuz hava ise „die Luft“." },
  { id: "de-a1.w235", t: "die Sonne", pos: "n", n: "güneş", ex: "Heute scheint die Sonne.", exn: "Bugün hava güneşli.", topic: "free", note: "Kelime başında sesli harften önceki „s“ = z: Sonne = zonne." },
  { id: "de-a1.w236", t: "der Regen", pos: "n", n: "yağmur", ex: "Bei Regen bleibe ich zu Hause.", exn: "Yağmurda evde kalırım.", topic: "free" },
  { id: "de-a1.w237", t: "regnen", pos: "v", n: "yağmur yağmak", ex: "Es regnet schon wieder.", exn: "Yine yağmur yağıyor.", topic: "free", note: "Özne hep „es“tir: Es regnet. Kar için: Es schneit." },
  { id: "de-a1.w238", t: "der Schnee", pos: "n", n: "kar", ex: "Die Kinder spielen im Schnee.", exn: "Çocuklar karda oynuyor.", topic: "free" },
  { id: "de-a1.w239", t: "kalt", pos: "adj", n: "soğuk", ex: "Heute ist es sehr kalt.", exn: "Bugün hava çok soğuk.", topic: "free", note: "„Üşüyorum“ = Mir ist kalt. „Ich bin kalt“ yanlış!" },
  { id: "de-a1.w240", t: "warm", pos: "adj", n: "sıcak, ılık", ex: "Das Wasser ist schön warm.", exn: "Su güzel ılık.", topic: "free", note: "Çok sıcak (yakıcı): heiß. Hava için: Es ist warm / Es ist heiß." },
  { id: "de-a1.w241", t: "der Sommer", pl: "die Sommer", pos: "n", n: "yaz", ex: "Im Sommer fahren wir ans Meer.", exn: "Yazın denize gidiyoruz.", topic: "free", note: "Mevsimler „der“ alır ve „im“ ile kullanılır: im Sommer, im Winter." },
  { id: "de-a1.w242", t: "der Winter", pl: "die Winter", pos: "n", n: "kış", ex: "Der Winter in Deutschland ist lang.", exn: "Almanya'da kış uzun sürer.", topic: "free" },
  { id: "de-a1.w243", t: "der Urlaub", pl: "die Urlaube", pos: "n", n: "tatil, izin", ex: "Wir machen Urlaub in Antalya.", exn: "Antalya'da tatil yapıyoruz.", topic: "free", note: "Çalışanların izni/tatili: Urlaub. Okul tatili: die Ferien." },
  { id: "de-a1.w244", t: "der Sport", pos: "n", n: "spor", ex: "Ich mache dreimal pro Woche Sport.", exn: "Haftada üç kez spor yapıyorum.", topic: "free", note: "Kelime başındaki „sp“ = şp: Sport = şport. Spor yapmak: Sport machen." },
  { id: "de-a1.w245", t: "spielen", pos: "v", n: "oynamak; (çalgı) çalmak", ex: "Mein Sohn spielt Gitarre.", exn: "Oğlum gitar çalıyor.", topic: "free", note: "Çalgı çalmak da „spielen“dir: Klavier spielen = piyano çalmak." },
  { id: "de-a1.w246", t: "der Fußball", pl: "die Fußbälle", pos: "n", n: "futbol; futbol topu", ex: "Am Samstag spielen wir Fußball.", exn: "Cumartesi futbol oynuyoruz.", topic: "free" },
  { id: "de-a1.w247", t: "das Kino", pl: "die Kinos", pos: "n", n: "sinema", ex: "Gehen wir heute ins Kino?", exn: "Bugün sinemaya gidelim mi?", topic: "free", note: "Sinemaya gitmek: ins Kino gehen (ins = in das)." },
  { id: "de-a1.w248", t: "die Musik", pos: "n", n: "müzik", ex: "Ich höre gern türkische Musik.", exn: "Türk müziği dinlemeyi severim.", topic: "free", note: "Vurgu son hecededir ve i uzundur: mu-ziik." },
  { id: "de-a1.w249", t: "das Buch", pl: "die Bücher", pos: "n", n: "kitap", ex: "Das Buch ist sehr spannend.", exn: "Kitap çok sürükleyici.", topic: "free", note: "a/o/u'dan sonra „ch“ boğazdan, sert okunur: Buch = buhh." },
  { id: "de-a1.w250", t: "lesen", pos: "v", n: "okumak", ex: "Abends lese ich gern.", exn: "Akşamları kitap okumayı severim.", topic: "free", note: "Kök ünlüsü değişir: du liest, er liest. „Okula gitmek“ anlamında okumak: in die Schule gehen." },
  { id: "de-a1.w251", t: "schwimmen", pos: "v", n: "yüzmek", ex: "Kannst du schwimmen?", exn: "Yüzme biliyor musun?", topic: "free", note: "Yüzme havuzu: das Schwimmbad." },
  { id: "de-a1.w252", t: "der Geburtstag", pl: "die Geburtstage", pos: "n", n: "doğum günü", ex: "Alles Gute zum Geburtstag!", exn: "Doğum günün kutlu olsun!", topic: "free" },
  { id: "de-a1.w253", t: "das Hobby", pl: "die Hobbys", pos: "n", n: "hobi", ex: "Mein Hobby ist Kochen.", exn: "Hobim yemek yapmak.", topic: "free", note: "Çoğulu -s ile: Hobbys (Hobbies değil)." },
  { id: "de-a1.w254", t: "der Park", pl: "die Parks", pos: "n", n: "park", ex: "Wir gehen mit dem Hund in den Park.", exn: "Köpekle parka gidiyoruz.", topic: "free" },

  /* ---------- verbs: Wichtige Verben ---------- */
  { id: "de-a1.w255", t: "sein", pos: "v", n: "olmak; -dir", ex: "Ich bin müde.", exn: "Yorgunum.", topic: "verbs", note: "Düzensiz: ich bin, du bist, er ist, wir sind, ihr seid, sie sind." },
  { id: "de-a1.w256", t: "haben", pos: "v", n: "sahip olmak; -si var", ex: "Hast du ein Auto?", exn: "Araban var mı?", topic: "verbs", note: "Türkçedeki „var“ çoğu zaman haben ile söylenir: Ich habe Zeit = Vaktim var. du hast, er hat." },
  { id: "de-a1.w257", t: "gehen", pos: "v", n: "gitmek (yürüyerek)", ex: "Ich gehe heute einkaufen.", exn: "Bugün alışverişe gidiyorum.", topic: "verbs", note: "Araçla gidiyorsan: fahren." },
  { id: "de-a1.w258", t: "kommen", pos: "v", n: "gelmek", ex: "Wann kommst du nach Hause?", exn: "Eve ne zaman geliyorsun?", topic: "verbs", note: "Memleket sorarken de kullanılır: Woher kommst du? = Nerelisin?" },
  { id: "de-a1.w259", t: "machen", pos: "v", n: "yapmak", ex: "Was machst du am Wochenende?", exn: "Hafta sonu ne yapıyorsun?", topic: "verbs" },
  { id: "de-a1.w260", t: "sprechen", pos: "v", n: "konuşmak", ex: "Sprechen Sie Türkisch?", exn: "Türkçe biliyor musunuz?", topic: "verbs", note: "Kök ünlüsü e → i olur: du sprichst, er spricht." },
  { id: "de-a1.w261", t: "sagen", pos: "v", n: "söylemek, demek", ex: "Was sagst du dazu?", exn: "Sen buna ne diyorsun?", topic: "verbs" },
  { id: "de-a1.w262", t: "fragen", pos: "v", n: "sormak", ex: "Darf ich etwas fragen?", exn: "Bir şey sorabilir miyim?", topic: "verbs", note: "Soru: die Frage." },
  { id: "de-a1.w263", t: "antworten", pos: "v", n: "cevap vermek", ex: "Er antwortet nicht.", exn: "Cevap vermiyor.", topic: "verbs", note: "Cevap: die Antwort. Kökü -t ile bittiği için araya -e- girer: du antwortest, er antwortet." },
  { id: "de-a1.w264", t: "verstehen", pos: "v", n: "anlamak", ex: "Das verstehe ich nicht.", exn: "Bunu anlamıyorum.", topic: "verbs" },
  { id: "de-a1.w265", t: "wissen", pos: "v", n: "bilmek (bir bilgiyi)", ex: "Ich weiß es nicht.", exn: "Bilmiyorum.", topic: "verbs", note: "Bir bilgiyi bilmek: wissen (ich weiß, du weißt). Bir kişiyi ya da yeri tanımak: kennen." },
  { id: "de-a1.w266", t: "kennen", pos: "v", n: "tanımak; bilmek (kişi, yer)", ex: "Kennst du meine Schwester?", exn: "Kız kardeşimi tanıyor musun?", topic: "verbs", note: "Bir yeri bilmek de „kennen“dir: Ich kenne Berlin. Bilgi için: wissen." },
  { id: "de-a1.w267", t: "sehen", pos: "v", n: "görmek", ex: "Siehst du das Schild?", exn: "Tabelayı görüyor musun?", topic: "verbs", note: "Kök ünlüsü e → ie olur: du siehst, er sieht. Televizyon izlemek: fernsehen." },
  { id: "de-a1.w268", t: "hören", pos: "v", n: "duymak; dinlemek", ex: "Hörst du mich?", exn: "Beni duyuyor musun?", topic: "verbs", note: "Müzik dinlemek de „hören“dir: Musik hören." },
  { id: "de-a1.w269", t: "schreiben", pos: "v", n: "yazmak", ex: "Schreib mir eine Nachricht!", exn: "Bana mesaj at!", topic: "verbs" },
  { id: "de-a1.w270", t: "nehmen", pos: "v", n: "almak", ex: "Ich nehme die Suppe.", exn: "Ben çorbayı alayım.", topic: "verbs", note: "Düzensiz: du nimmst, er nimmt. Restoranda sipariş verirken çok kullanılır." },
  { id: "de-a1.w271", t: "geben", pos: "v", n: "vermek", ex: "Gibst du mir das Salz?", exn: "Tuzu verir misin?", topic: "verbs", note: "Kök ünlüsü e → i olur: du gibst, er gibt. „Es gibt …“ = … var: Es gibt hier ein Café." },
  { id: "de-a1.w272", t: "brauchen", pos: "v", n: "ihtiyacı olmak, … lazım olmak", ex: "Ich brauche Hilfe.", exn: "Yardıma ihtiyacım var.", topic: "verbs" },
  { id: "de-a1.w273", t: "möchten", pos: "v", n: "istemek (kibarca)", ex: "Ich möchte einen Kaffee.", exn: "Bir kahve alabilir miyim?", topic: "verbs", note: "Kibar istek için en çok kullanılan fiil. „Ich will …“ kaba kaçabilir." },
  { id: "de-a1.w274", t: "wollen", pos: "v", n: "istemek", ex: "Wir wollen nach Hause.", exn: "Eve gitmek istiyoruz.", topic: "verbs", note: "Güçlü bir istek ya da niyet bildirir: ich will, du willst. Kibar rica için „möchten“ kullan." },
  { id: "de-a1.w275", t: "können", pos: "v", n: "-ebilmek", ex: "Kannst du mir helfen?", exn: "Bana yardım edebilir misin?", topic: "verbs", note: "Modal fiildir: ikinci fiil cümlenin sonuna, mastar hâlinde gider." },
  { id: "de-a1.w276", t: "müssen", pos: "v", n: "zorunda olmak, -meli", ex: "Ich muss jetzt gehen.", exn: "Şimdi gitmem lazım.", topic: "verbs", note: "Tekilde ü → u olur: ich muss, du musst, er muss." },
  { id: "de-a1.w277", t: "mögen", pos: "v", n: "sevmek, hoşlanmak", ex: "Ich mag Katzen.", exn: "Kedileri severim.", topic: "verbs", note: "ich mag, du magst. Bir şeyi yapmayı sevmek için fiil + gern: Ich koche gern." },
  { id: "de-a1.w278", t: "finden", pos: "v", n: "bulmak; (… olarak) bulmak, düşünmek", ex: "Ich finde den Film gut.", exn: "Bence film güzel.", topic: "verbs", note: "Fikir bildirmek için de kullanılır: Ich finde das gut = Bence bu iyi." },
  { id: "de-a1.w279", t: "suchen", pos: "v", n: "aramak (bir şeyi)", ex: "Ich suche meinen Schlüssel.", exn: "Anahtarımı arıyorum.", topic: "verbs", note: "Telefonla aramak ise „anrufen“." },
  { id: "de-a1.w280", t: "warten", pos: "v", n: "beklemek", ex: "Ich warte auf den Bus.", exn: "Otobüsü bekliyorum.", topic: "verbs", note: "Neyi beklediğini „auf + Akkusativ“ ile söylersin: auf dich warten. du wartest." },
  { id: "de-a1.w281", t: "schlafen", pos: "v", n: "uyumak", ex: "Hast du gut geschlafen?", exn: "İyi uyudun mu?", topic: "verbs", note: "Kök ünlüsü a → ä olur: du schläfst, er schläft." },
  { id: "de-a1.w282", t: "aufstehen", pos: "v", n: "kalkmak (yataktan)", ex: "Wann stehst du auf?", exn: "Kaçta kalkıyorsun?", topic: "verbs", note: "Ayrılabilen fiil: ön ek cümlenin sonuna gider: Ich stehe früh auf." },
  { id: "de-a1.w283", t: "anrufen", pos: "v", n: "telefonla aramak", ex: "Ich rufe dich später an.", exn: "Seni sonra ararım.", topic: "verbs", note: "Ayrılabilen fiil: ich rufe … an. Aranan kişi Akkusativ'dir: Ich rufe dich an." },
  { id: "de-a1.w284", t: "einkaufen", pos: "v", n: "alışveriş yapmak", ex: "Wir kaufen im Supermarkt ein.", exn: "Süpermarketten alışveriş yapıyoruz.", topic: "verbs", note: "Ayrılabilen fiil. Tek bir şey satın almak: kaufen." },
  { id: "de-a1.w285", t: "öffnen", pos: "v", n: "açmak", ex: "Die Bank öffnet um neun.", exn: "Banka dokuzda açılıyor.", topic: "verbs", note: "Günlük dilde çoğu zaman „aufmachen“ denir." },
  { id: "de-a1.w286", t: "schließen", pos: "v", n: "kapatmak", ex: "Bitte schließen Sie das Fenster.", exn: "Lütfen pencereyi kapatın.", topic: "verbs", note: "Günlük dilde: zumachen. Dükkânlar için: Der Laden schließt um acht." },
  { id: "de-a1.w287", t: "helfen", pos: "v", n: "yardım etmek", ex: "Ich helfe dir gern.", exn: "Sana seve seve yardım ederim.", topic: "verbs", note: "Dativ ister: Ich helfe dir („dich“ değil!). Kök ünlüsü e → i: du hilfst, er hilft." },
  { id: "de-a1.w288", t: "bleiben", pos: "v", n: "kalmak", ex: "Wie lange bleibst du in Deutschland?", exn: "Almanya'da ne kadar kalacaksın?", topic: "verbs" },
  { id: "de-a1.w289", t: "leben", pos: "v", n: "yaşamak", ex: "Meine Familie lebt in Ankara.", exn: "Ailem Ankara'da yaşıyor.", topic: "verbs", note: "Bir yerde yaşamak için hem „leben“ hem „wohnen“ kullanılır; „wohnen“ daha çok adres/ev için." },
  { id: "de-a1.w290", t: "lieben", pos: "v", n: "sevmek (çok güçlü)", ex: "Ich liebe dich.", exn: "Seni seviyorum.", topic: "verbs", note: "Güçlü bir sevgi bildirir. Yiyecek, hobi vb. için daha çok „mögen“ ya da „gern“ kullanılır." },
  { id: "de-a1.w291", t: "zeigen", pos: "v", n: "göstermek", ex: "Können Sie mir das auf der Karte zeigen?", exn: "Bunu bana haritada gösterebilir misiniz?", topic: "verbs" },
  { id: "de-a1.w292", t: "bringen", pos: "v", n: "getirmek", ex: "Der Kellner bringt die Suppe.", exn: "Garson çorbayı getiriyor.", topic: "verbs" },
  { id: "de-a1.w293", t: "holen", pos: "v", n: "gidip almak, getirmek", ex: "Ich hole schnell Brot.", exn: "Hemen ekmek alıp geliyorum.", topic: "verbs", note: "Birini bir yerden almak: abholen. Ich hole dich am Bahnhof ab." },
  { id: "de-a1.w294", t: "beginnen", pos: "v", n: "başlamak", ex: "Der Film beginnt um acht.", exn: "Film sekizde başlıyor.", topic: "verbs", note: "Günlük dilde „anfangen“ da denir (ayrılabilen fiil)." },
  { id: "de-a1.w295", t: "sitzen", pos: "v", n: "oturmak (bir yerde)", ex: "Hier sitzt schon jemand.", exn: "Burada oturan biri var.", topic: "verbs", note: "Sandalyede vb. oturmak = sitzen. Bir şehirde ya da evde oturmak = wohnen." },
  { id: "de-a1.w296", t: "laufen", pos: "v", n: "yürümek; koşmak", ex: "Ich laufe jeden Morgen im Park.", exn: "Her sabah parkta koşuyorum.", topic: "verbs", note: "Kök ünlüsü au → äu olur: du läufst, er läuft." },
  { id: "de-a1.w297", t: "bekommen", pos: "v", n: "almak, eline geçmek", ex: "Was bekommen Sie?", exn: "Ne alırsınız?", topic: "verbs", note: "İngilizcedeki „become“ (olmak) ile karıştırma: bekommen = almak. Satıcılar ve garsonlar bu soruyu çok sorar." },
  { id: "de-a1.w298", t: "vergessen", pos: "v", n: "unutmak", ex: "Ich habe meinen Schlüssel vergessen.", exn: "Anahtarımı unuttum.", topic: "verbs", note: "Kök ünlüsü e → i olur: du vergisst, er vergisst." },
  { id: "de-a1.w299", t: "fliegen", pos: "v", n: "uçmak; uçakla gitmek", ex: "Wir fliegen im Juli nach Istanbul.", exn: "Temmuzda İstanbul'a uçuyoruz.", topic: "verbs", note: "Uçak: das Flugzeug. Uçuş: der Flug." },
  { id: "de-a1.w300", t: "ankommen", pos: "v", n: "varmak, gelmek", ex: "Wann kommt der Zug an?", exn: "Tren ne zaman varıyor?", topic: "verbs", note: "Ayrılabilen fiil: Der Zug kommt um zehn Uhr an." },
  { id: "de-a1.w301", t: "besuchen", pos: "v", n: "ziyaret etmek", ex: "Am Wochenende besuche ich meine Eltern.", exn: "Hafta sonu annemle babamı ziyaret ediyorum.", topic: "verbs", note: "Akkusativ ister ve ön eki ayrılmaz: Ich besuche dich." },
  { id: "de-a1.w302", t: "erklären", pos: "v", n: "açıklamak, anlatmak", ex: "Kannst du mir das erklären?", exn: "Bunu bana açıklayabilir misin?", topic: "verbs" },
  { id: "de-a1.w303", t: "wiederholen", pos: "v", n: "tekrar etmek", ex: "Können Sie das bitte wiederholen?", exn: "Bunu tekrar edebilir misiniz lütfen?", topic: "verbs", note: "Bu anlamda ön eki ayrılmaz: Ich wiederhole." },
  { id: "de-a1.w304", t: "buchstabieren", pos: "v", n: "harf harf söylemek, kodlamak", ex: "Können Sie Ihren Namen buchstabieren?", exn: "Adınızı harf harf söyler misiniz?", topic: "verbs", note: "Telefonda ve resmî dairelerde çok istenir – özellikle Almanca olmayan isimler için." },

  /* ---------- adj: Eigenschaften ---------- */
  { id: "de-a1.w305", t: "gut", pos: "adj", n: "iyi", ex: "Das Essen ist sehr gut.", exn: "Yemek çok güzel.", topic: "adj", note: "„Nasılsın?“ sorusuna cevap: Gut, danke!" },
  { id: "de-a1.w306", t: "schlecht", pos: "adj", n: "kötü", ex: "Mir geht es heute schlecht.", exn: "Bugün kendimi kötü hissediyorum.", topic: "adj" },
  { id: "de-a1.w307", t: "groß", pos: "adj", n: "büyük; uzun boylu", ex: "Mein Bruder ist sehr groß.", exn: "Ağabeyim çok uzun boylu.", topic: "adj", note: "İnsanlar için „uzun boylu“ demektir; insan boyu için „lang“ kullanılmaz." },
  { id: "de-a1.w308", t: "klein", pos: "adj", n: "küçük; kısa boylu", ex: "Mein Kind ist noch klein.", exn: "Çocuğum daha küçük.", topic: "adj" },
  { id: "de-a1.w309", t: "neu", pos: "adj", n: "yeni", ex: "Ist das Handy neu?", exn: "Telefon yeni mi?", topic: "adj" },
  { id: "de-a1.w310", t: "alt", pos: "adj", n: "eski; yaşlı", ex: "Wie alt bist du?", exn: "Kaç yaşındasın?", topic: "adj", note: "Eşyalar için „eski“, insanlar için „yaşlı“ demektir. Yaş sorarken de kullanılır." },
  { id: "de-a1.w311", t: "jung", pos: "adj", n: "genç", ex: "Unsere Lehrerin ist sehr jung.", exn: "Öğretmenimiz çok genç.", topic: "adj", note: "„j“ = y: jung = yung." },
  { id: "de-a1.w312", t: "schön", pos: "adj", n: "güzel", ex: "Das Wetter ist heute schön.", exn: "Bugün hava güzel.", topic: "adj" },
  { id: "de-a1.w313", t: "lang", pos: "adj", n: "uzun", ex: "Der Tag war sehr lang.", exn: "Gün çok uzun geçti.", topic: "adj", note: "Eşya ve süre için kullanılır. İnsan boyu için: groß." },
  { id: "de-a1.w314", t: "kurz", pos: "adj", n: "kısa", ex: "Die Pause ist kurz.", exn: "Mola kısa.", topic: "adj" },
  { id: "de-a1.w315", t: "schnell", pos: "adj", n: "hızlı; çabuk", ex: "Du sprichst zu schnell.", exn: "Çok hızlı konuşuyorsun.", topic: "adj" },
  { id: "de-a1.w316", t: "langsam", pos: "adj", n: "yavaş", ex: "Bitte sprechen Sie langsam.", exn: "Lütfen yavaş konuşun.", topic: "adj" },
  { id: "de-a1.w317", t: "richtig", pos: "adj", n: "doğru", ex: "Die Antwort ist richtig.", exn: "Cevap doğru.", topic: "adj" },
  { id: "de-a1.w318", t: "falsch", pos: "adj", n: "yanlış", ex: "Die Nummer ist falsch.", exn: "Numara yanlış.", topic: "adj" },
  { id: "de-a1.w319", t: "leicht", pos: "adj", n: "kolay; hafif", ex: "Die Übung ist leicht.", exn: "Alıştırma kolay.", topic: "adj", note: "İki anlamı var: kolay ve hafif. Zıttı: schwer." },
  { id: "de-a1.w320", t: "schwer", pos: "adj", n: "zor; ağır", ex: "Der Koffer ist schwer.", exn: "Bavul ağır.", topic: "adj", note: "İki anlamı var: zor ve ağır. Zıttı: leicht." },
  { id: "de-a1.w321", t: "müde", pos: "adj", n: "yorgun; uykulu", ex: "Nach der Arbeit bin ich müde.", exn: "İşten sonra yorgun oluyorum.", topic: "adj" },
  { id: "de-a1.w322", t: "nett", pos: "adj", n: "nazik, cana yakın", ex: "Die Nachbarin ist sehr nett.", exn: "Komşu kadın çok cana yakın.", topic: "adj", note: "Türkçedeki „net“ (açık, belirgin) ile karıştırma!" },
  { id: "de-a1.w323", t: "kaputt", pos: "adj", n: "bozuk; kırık", ex: "Mein Handy ist kaputt.", exn: "Telefonum bozuk.", topic: "adj", note: "Günlük dilde „Ich bin kaputt“ = Çok yorgunum, bittim." },
  { id: "de-a1.w324", t: "rot", pos: "adj", n: "kırmızı", ex: "Die Ampel ist rot.", exn: "Işık kırmızı.", topic: "adj" },
  { id: "de-a1.w325", t: "blau", pos: "adj", n: "mavi", ex: "Der Himmel ist blau.", exn: "Gökyüzü mavi.", topic: "adj", note: "Günlük dilde „blau sein“ ayrıca „sarhoş olmak“ demektir." },
  { id: "de-a1.w326", t: "grün", pos: "adj", n: "yeşil", ex: "Im Frühling ist alles grün.", exn: "İlkbaharda her yer yemyeşil.", topic: "adj" },
  { id: "de-a1.w327", t: "weiß", pos: "adj", n: "beyaz", ex: "Die Wände sind weiß.", exn: "Duvarlar beyaz.", topic: "adj", note: "Dikkat: „ich weiß“ (biliyorum) aynı yazılır ama başka bir kelimedir." },
  { id: "de-a1.w328", t: "schwarz", pos: "adj", n: "siyah", ex: "Ich trinke den Kaffee schwarz.", exn: "Kahveyi sütsüz içiyorum.", topic: "adj", note: "Kahve için „schwarz“ = sütsüz (genelde şekersiz de). Şekerli istersen: schwarz mit Zucker." },

  /* ---------- small: Kleine Wörter ---------- */
  { id: "de-a1.w329", t: "wer", pos: "x", n: "kim", ex: "Wer ist das?", exn: "Bu kim?", topic: "small", note: "Dikkat: „wer“ = kim, „wo“ = nerede. İngilizcedeki „where“ ile karıştırma." },
  { id: "de-a1.w330", t: "was", pos: "x", n: "ne", ex: "Was ist das?", exn: "Bu ne?", topic: "small" },
  { id: "de-a1.w331", t: "wo", pos: "x", n: "nerede", ex: "Wo wohnst du?", exn: "Nerede oturuyorsun?", topic: "small", note: "Yer sorar. Nereye: wohin. Nereden: woher." },
  { id: "de-a1.w332", t: "woher", pos: "x", n: "nereden", ex: "Woher kommen Sie?", exn: "Nerelisiniz?", topic: "small", note: "„Woher kommen Sie?“ kelime kelime „Nereden geliyorsunuz?“ ama „Nerelisiniz?“ anlamında kullanılır." },
  { id: "de-a1.w333", t: "wohin", pos: "x", n: "nereye", ex: "Wohin fährt dieser Bus?", exn: "Bu otobüs nereye gidiyor?", topic: "small" },
  { id: "de-a1.w334", t: "wie", pos: "x", n: "nasıl", ex: "Wie heißt du?", exn: "Adın ne?", topic: "small", note: "Ad sorarken Türkçede „ne“ deriz, Almancada „wie“: Wie heißt du?" },
  { id: "de-a1.w335", t: "wann", pos: "x", n: "ne zaman", ex: "Wann beginnt der Kurs?", exn: "Kurs ne zaman başlıyor?", topic: "small" },
  { id: "de-a1.w336", t: "warum", pos: "x", n: "neden, niçin", ex: "Warum lernst du Deutsch?", exn: "Neden Almanca öğreniyorsun?", topic: "small", note: "Cevap genelde „weil“ (çünkü) ile başlar." },
  { id: "de-a1.w337", t: "wie viel", pos: "x", n: "ne kadar; kaç", ex: "Wie viel kostet das?", exn: "Bu ne kadar?", topic: "small", note: "Ayrı yazılır. Sayılabilen şeyler için çoğu zaman „wie viele“: Wie viele Kinder hast du?" },
  { id: "de-a1.w338", t: "nicht", pos: "x", n: "değil; olumsuzluk (-me/-ma)", ex: "Ich komme heute nicht.", exn: "Bugün gelmiyorum.", topic: "small", note: "Fiilleri ve sıfatları olumsuz yapar. İsimleri olumsuz yapmak için: kein." },
  { id: "de-a1.w339", t: "kein", pos: "x", n: "hiç … yok / değil (isimle)", ex: "Ich habe kein Auto.", exn: "Arabam yok.", topic: "small", note: "İsimleri olumsuz yapar ve „ein“ gibi çekilir: kein Auto, keine Zeit, keinen Hund." },
  { id: "de-a1.w340", t: "auch", pos: "adv", n: "de, da; ayrıca", ex: "Ich komme auch mit.", exn: "Ben de geliyorum.", topic: "small" },
  { id: "de-a1.w341", t: "sehr", pos: "adv", n: "çok (derece)", ex: "Das ist sehr schön.", exn: "Bu çok güzel.", topic: "small", note: "Derece bildirir (çok güzel). Miktar için „viel“: viel Geld." },
  { id: "de-a1.w342", t: "gern", pos: "adv", n: "seve seve; severek", ex: "Ich koche gern.", exn: "Yemek yapmayı severim.", topic: "small", note: "Fiil + gern = bir şeyi yapmayı sevmek. „gerne“ de denir." },
  { id: "de-a1.w343", t: "hier", pos: "adv", n: "burada; buraya", ex: "Ich wohne hier.", exn: "Burada oturuyorum.", topic: "small" },
  { id: "de-a1.w344", t: "jetzt", pos: "adv", n: "şimdi", ex: "Ich habe jetzt keine Zeit.", exn: "Şimdi vaktim yok.", topic: "small" },
  { id: "de-a1.w345", t: "und", pos: "x", n: "ve", ex: "Ich spreche Türkisch und Deutsch.", exn: "Türkçe ve Almanca konuşuyorum.", topic: "small" },
  { id: "de-a1.w346", t: "aber", pos: "x", n: "ama, fakat", ex: "Das Zimmer ist klein, aber hell.", exn: "Oda küçük ama aydınlık.", topic: "small" },
  { id: "de-a1.w347", t: "oder", pos: "x", n: "veya, ya da", ex: "Tee oder Kaffee?", exn: "Çay mı, kahve mi?", topic: "small" },
  { id: "de-a1.w348", t: "mit", pos: "x", n: "ile", ex: "Kommst du mit mir?", exn: "Benimle geliyor musun?", topic: "small", note: "Hep Dativ ister: mit dem Bus, mit der Bahn, mit mir." },
  { id: "de-a1.w349", t: "viel", pos: "adv", n: "çok (miktar)", ex: "Ich habe viel Arbeit.", exn: "Çok işim var.", topic: "small", note: "Miktar bildirir. Derece için „sehr“: sehr gut." },
  { id: "de-a1.w350", t: "immer", pos: "adv", n: "her zaman, hep", ex: "Der Bus ist immer pünktlich.", exn: "Otobüs hep zamanında gelir.", topic: "small" }
]);
/* ---------- Erweiterung A1 (Paket P1a): w351–w650 ---------- */
K.addVocab('de-a1', [
  /* ---------- greet: Begrüßung & Höflichkeit (neu) ---------- */
  { id: "de-a1.w351", ext: 1, t: "Willkommen!", pos: "phr", n: "hoş geldin / hoş geldiniz", ex: "Willkommen in Köln!", exn: "Köln’e hoş geldin!", topic: "greet", note: "Karşılayan kişi söyler. „Hoş bulduk“ karşılığı sabit bir kalıp yoktur; genelde „Danke!“ denir." },
  { id: "de-a1.w352", ext: 1, t: "Schönen Tag noch!", pos: "phr", n: "günün geri kalanı güzel geçsin", ex: "Tschüss und schönen Tag noch!", exn: "Hoşça kal, günün güzel geçsin!", topic: "greet", note: "Daha çok dükkânda, ofiste ayrılırken söylenir." },
  { id: "de-a1.w353", ext: 1, t: "Schönes Wochenende!", pos: "phr", n: "iyi hafta sonları", ex: "Tschüss, schönes Wochenende!", exn: "Hoşça kal, iyi hafta sonları!", topic: "greet", note: "Cuma günü ayrılırken söylenir. Kısa bir kalıptır, fiil yok." },
  { id: "de-a1.w354", ext: 1, t: "Viel Glück!", pos: "phr", n: "bol şans!", ex: "Du hast morgen einen Termin? Viel Glück!", exn: "Yarın randevun mu var? Bol şans!", topic: "greet", note: "Kısa ve çok kullanılır." },
  { id: "de-a1.w355", ext: 1, t: "Alles Gute!", pos: "phr", n: "her şey gönlünce olsun; en iyi dileklerimle", ex: "Alles Gute zum Geburtstag!", exn: "Doğum günün kutlu olsun!", topic: "greet", note: "Doğum günü, yılbaşı ve ayrılırken iyi dilek için kullanılır. „zum Geburtstag“ kalıbı hep böyle: Alles Gute zum Geburtstag!" },
  { id: "de-a1.w356", ext: 1, t: "Gleichfalls!", pos: "phr", n: "sana da / size de", ex: "Schönes Wochenende! – Danke, gleichfalls!", exn: "İyi hafta sonları! – Teşekkürler, size de!", topic: "greet", note: "Dileğe karşılık verirken kullanılır. Daha günlük: „Dir auch!“." },
  { id: "de-a1.w357", ext: 1, t: "Prost!", pos: "x", n: "şerefe!", ex: "Prost! Auf deine Gesundheit!", exn: "Şerefe! Sağlığına!", topic: "greet", note: "Kadeh kaldırırken söylenir; meyve suyu ya da çayla da denebilir. Alman sofrasında kadehleri tokuştururken göz göze bakmak adettendir." },
  { id: "de-a1.w358", ext: 1, t: "Bitte schön!", pos: "phr", n: "buyurun; rica ederim", ex: "Hier ist Ihr Kaffee, bitte schön! – Danke!", exn: "İşte kahveniz, buyurun! – Teşekkürler!", topic: "greet", note: "„Bitte“ üç iş görür: lütfen, buyurun, rica ederim. „Bitte schön“ biraz daha nazik ve tam bir cümle gibi." },
  { id: "de-a1.w359", ext: 1, t: "Danke schön!", pos: "phr", n: "çok teşekkürler", ex: "Danke schön für den Kaffee!", exn: "Kahve için çok teşekkürler!", topic: "greet", note: "„Danke“den biraz daha sıcak. Cevap olarak: „Bitte schön!“" },
  { id: "de-a1.w360", ext: 1, t: "Vielen Dank!", pos: "phr", n: "çok teşekkür ederim", ex: "Vielen Dank für Ihre Hilfe!", exn: "Yardımınız için çok teşekkür ederim!", topic: "greet", note: "„für“ + teşekkür sebebi gelir: Danke für das Essen." },
  { id: "de-a1.w361", ext: 1, t: "Gern geschehen!", pos: "phr", n: "rica ederim; ne demek", ex: "Danke für die Hilfe! – Gern geschehen!", exn: "Yardım için teşekkürler! – Rica ederim!", topic: "greet", note: "Daha kısa ve samimi: „Gern!“ ya da „Kein Problem!“" },
  { id: "de-a1.w362", ext: 1, t: "Kein Problem!", pos: "phr", n: "sorun değil; problem yok", ex: "Kannst du mir helfen? – Kein Problem!", exn: "Bana yardım edebilir misin? – Sorun değil!", topic: "greet", note: "„kein“ burada „Problem“in önüne gelir, „nicht“ değil: Das ist kein Problem." },
  { id: "de-a1.w363", ext: 1, t: "Wie heißen Sie?", pos: "phr", n: "adınız nedir?", ex: "Guten Tag, wie heißen Sie?", exn: "İyi günler, adınız nedir?", topic: "greet", note: "Resmî hâl „Sie“, arkadaşça: „Wie heißt du?“. du → -st; kök ß/s ile bitince sadece -t: du heißt." },
  { id: "de-a1.w364", ext: 1, t: "Ich heiße …", pos: "phr", n: "adım …", ex: "Ich heiße Elif Kaya.", exn: "Adım Elif Kaya.", topic: "greet", note: "Fiil ikinci sırada: „Ich heiße“ – „Heiße ich“ değil. „Mein Name ist …“ ile aynı anlama gelir." },
  { id: "de-a1.w365", ext: 1, t: "Woher kommen Sie?", pos: "phr", n: "nerelisiniz?; nereden geliyorsunuz?", ex: "Woher kommen Sie? – Aus Ankara.", exn: "Nerelisiniz? – Ankara’dan.", topic: "greet", note: "Almancada „nerelisin“ diye ayrı bir kalıp yok; „woher kommen“ (nereden geliyor) denir." },
  { id: "de-a1.w366", ext: 1, t: "Ich komme aus der Türkei.", pos: "phr", n: "Türkiye’denim", ex: "Ich komme aus der Türkei, aber ich wohne in Köln.", exn: "Türkiye’denim ama Köln’de oturuyorum.", topic: "greet", note: "Ülke adlarının çoğu artikelsizdir (aus Deutschland), ama „Türkei“ dişildir: aus der Türkei. Kalıp olarak ezberle." },
  { id: "de-a1.w367", ext: 1, t: "Sehr erfreut!", pos: "phr", n: "memnun oldum (resmî)", ex: "Guten Tag, Herr Aydin. – Sehr erfreut!", exn: "İyi günler Bay Aydın. – Memnun oldum!", topic: "greet", note: "„Freut mich!“ ifadesinden daha resmî. İş görüşmelerinde ve ilk tanışmada kullanılır." },
  { id: "de-a1.w368", ext: 1, t: "Bis später!", pos: "phr", n: "sonra görüşürüz", ex: "Ich muss jetzt arbeiten. Bis später!", exn: "Şimdi çalışmam lazım. Sonra görüşürüz!", topic: "greet", note: "Aynı gün içinde tekrar görüşecekseniz söylenir." },
  { id: "de-a1.w369", ext: 1, t: "Bis bald!", pos: "phr", n: "yakında görüşürüz", ex: "Es war schön! Bis bald!", exn: "Çok güzeldi! Yakında görüşürüz!", topic: "greet", note: "Tam bir gün belirtmeden, „yakında görüşürüz“ anlamında." },
  { id: "de-a1.w370", ext: 1, t: "Gesundheit!", pos: "x", n: "çok yaşa!", ex: "Hatschi! – Gesundheit! – Danke.", exn: "Hapşu! – Çok yaşa! – Teşekkürler.", topic: "greet", note: "Biri hapşırınca söylenir. „Gesundheit“ gerçek anlamıyla „sağlık“ demektir." },
  { id: "de-a1.w371", ext: 1, t: "Verzeihung!", pos: "x", n: "pardon; affedersiniz", ex: "Verzeihung, wie bitte?", exn: "Pardon, ne dediniz?", topic: "greet", note: "„Entschuldigung“ ile aynı; yoldan geçerken, dikkat çekerken kullanılır." },
  { id: "de-a1.w372", ext: 1, t: "Entschuldigen Sie!", pos: "phr", n: "affedersiniz; özür dilerim (resmî)", ex: "Entschuldigen Sie, sind Sie Herr Kaya?", exn: "Affedersiniz, Kaya Bey siz misiniz?", topic: "greet", note: "Birine seslenirken kullanılır. Arkadaşa: „Entschuldige!“ Son ek „-n Sie“ (emir, resmî)." },
  /* ---------- people: Personen & Familie (neu) ---------- */
  { id: "de-a1.w373", ext: 1, t: "der Vorname", pl: "die Vornamen", pos: "n", n: "ad (soyadın karşıtı)", ex: "Mein Vorname ist Murat.", exn: "Benim adım Murat.", topic: "people", note: "Formda „Vorname“ = adın, „Nachname“ = soyadın. Dikkat: „Name“ tek başına çoğu zaman soyadıdır." },
  { id: "de-a1.w374", ext: 1, t: "der Nachname", pl: "die Nachnamen", pos: "n", n: "soyadı", ex: "Mein Nachname ist Yilmaz.", exn: "Soyadım Yılmaz.", topic: "people", note: "Formda sorulur: Vorname, Nachname. Sıra Türkçedekiyle aynı: önce ad, sonra soyad." },
  { id: "de-a1.w375", ext: 1, t: "die Dame", pl: "die Damen", pos: "n", n: "hanım; bayan", ex: "Die Dame dort ist meine Lehrerin.", exn: "Oradaki hanım benim öğretmenim.", topic: "people", note: "Nazik hitapta: „Meine Damen und Herren!“ (Bayanlar ve baylar!). „Frau“ gündelik dilde daha yaygındır." },
  { id: "de-a1.w376", ext: 1, t: "der Partner", pl: "die Partner", pos: "n", n: "eş; birlikte yaşadığı kişi", ex: "Mein Partner arbeitet in Bonn.", exn: "Eşim Bonn’da çalışıyor.", topic: "people", note: "Evlilik şart değil: „Partner/Partnerin“ evli ya da değil, birlikte yaşayan kişi demek." },
  { id: "de-a1.w377", ext: 1, t: "die Partnerin", pl: "die Partnerinnen", pos: "n", n: "kadın eş; partner", ex: "Meine Partnerin kommt aus Spanien.", exn: "Eşim İspanya’dan geliyor.", topic: "people", note: "Kadın hâl: -in eki, çoğul -innen." },
  { id: "de-a1.w378", ext: 1, t: "der Verwandte", pl: "die Verwandten", pos: "n", n: "akraba", ex: "Heute besuchen wir Verwandte.", exn: "Bugün akrabaları ziyaret ediyoruz.", topic: "people", note: "Kadın: die Verwandte. Sıfat gibi çekilir: ein Verwandter / eine Verwandte. Çoğul: die Verwandten." },
  { id: "de-a1.w379", ext: 1, t: "der Student", pl: "die Studenten", pos: "n", n: "üniversite öğrencisi", ex: "Mein Bruder ist Student.", exn: "Kardeşim üniversite öğrencisi.", topic: "people", note: "Meslek bildirirken artikel yok: „Er ist Student.“ („ein Student“ değil). Çoğul -en." },
  { id: "de-a1.w380", ext: 1, t: "die Studentin", pl: "die Studentinnen", pos: "n", n: "kız üniversite öğrencisi", ex: "Meine Schwester ist Studentin.", exn: "Kız kardeşim üniversite öğrencisi.", topic: "people", note: "„Studentin“ kadın biçimi; meslek bildirirken artikel yok: Sie ist Studentin." },
  { id: "de-a1.w381", ext: 1, t: "der Schüler", pl: "die Schüler", pos: "n", n: "(okul) öğrencisi", ex: "Der Schüler lernt Deutsch.", exn: "Öğrenci Almanca öğreniyor.", topic: "people", note: "„Student“ üniversitede, „Schüler“ okulda okuyan içindir. Türkçede ikisi de „öğrenci“ olduğu için karıştırılır." },
  { id: "de-a1.w382", ext: 1, t: "die Schülerin", pl: "die Schülerinnen", pos: "n", n: "kız öğrenci (okul)", ex: "Die Schülerin lernt Englisch.", exn: "Öğrenci kız İngilizce öğreniyor.", topic: "people", note: "Okul için „Schülerin“, üniversite için „Studentin“." },
  { id: "de-a1.w383", ext: 1, t: "die Schwiegermutter", pl: "die Schwiegermütter", pos: "n", n: "kayınvalide; kaynana", ex: "Meine Schwiegermutter kocht sehr gut.", exn: "Kayınvalidem çok güzel yemek yapıyor.", topic: "people", note: "Almancada tek kelime: Schwieger- + Mutter. Hem kadının hem erkeğin eşinin annesi için aynı kelime kullanılır." },
  { id: "de-a1.w384", ext: 1, t: "der Schwiegervater", pl: "die Schwiegerväter", pos: "n", n: "kayınpeder", ex: "Mein Schwiegervater ist Lehrer.", exn: "Kayınpederim öğretmen.", topic: "people", note: "„Schwieger-“ ön eki eşin ana-babası için kullanılır. Çoğulda a → ä: Schwiegerväter." },
  { id: "de-a1.w385", ext: 1, t: "der Enkel", pl: "die Enkel", pos: "n", n: "erkek torun", ex: "Unser Enkel ist drei Jahre alt.", exn: "Torunumuz üç yaşında.", topic: "people", note: "Oğlundan da kızından da olsa „Enkel“; ayrım yok." },
  { id: "de-a1.w386", ext: 1, t: "die Enkelin", pl: "die Enkelinnen", pos: "n", n: "kız torun", ex: "Meine Enkelin spielt gern Fußball.", exn: "Kız torunum futbol oynamayı seviyor.", topic: "people", note: "„Enkel“ + -in. Çoğul -innen." },
  { id: "de-a1.w387", ext: 1, t: "die Person", pl: "die Personen", pos: "n", n: "kişi", ex: "Wir sind vier Personen.", exn: "Biz dört kişiyiz.", topic: "people", note: "Almancada sayıdan sonra çoğul: vier Personen (Türkçede tekil: dört kişi)." },
  { id: "de-a1.w388", ext: 1, t: "der Erwachsene", pl: "die Erwachsenen", pos: "n", n: "yetişkin", ex: "Zwei Erwachsene und ein Kind, bitte.", exn: "İki yetişkin ve bir çocuk, lütfen.", topic: "people", note: "Kadın: die Erwachsene. Sıfattan türer: ein Erwachsener / eine Erwachsene. Bilet alırken çok işe yarar." },
  { id: "de-a1.w389", ext: 1, t: "der Türke", pl: "die Türken", pos: "n", n: "Türk (erkek)", ex: "Mein Nachbar ist Türke.", exn: "Komşum Türk.", topic: "people", note: "Milliyet bildirirken artikel yok: „Er ist Türke.“ Çoğul -n. Dil ise „Türkisch“ (büyük harfle)." },
  { id: "de-a1.w390", ext: 1, t: "die Türkin", pl: "die Türkinnen", pos: "n", n: "Türk kadını", ex: "Sie ist Türkin und wohnt in Berlin.", exn: "O Türk ve Berlin’de oturuyor.", topic: "people", note: "Kadınlar için -in: Türkin. Milliyet: „Ich bin Türkin.“, ülke: „die Türkei“." },
  { id: "de-a1.w391", ext: 1, t: "die Nachbarin", pl: "die Nachbarinnen", pos: "n", n: "kadın komşu", ex: "Meine Nachbarin ist sehr nett.", exn: "Komşum çok iyi biri.", topic: "people", note: "„Nachbar“ erkek, „Nachbarin“ kadın komşu. Çoğul -innen." },
  { id: "de-a1.w392", ext: 1, t: "das Alter", pos: "n", n: "yaş", ex: "Im Formular steht: Name, Alter, Adresse.", exn: "Formda ad, yaş, adres yazıyor.", topic: "people", note: "Formda „Alter“ yaş bilgisidir. Konuşurken: „Wie alt bist du?“ (kaç yaşındasın)." },
  { id: "de-a1.w393", ext: 1, t: "Ich habe zwei Geschwister.", pos: "phr", n: "iki kardeşim var", ex: "Ich habe zwei Geschwister, einen Bruder und eine Schwester.", exn: "İki kardeşim var, bir erkek ve bir kız.", topic: "people", note: "„Geschwister“ kız/erkek ayırmadan kardeşlerin hepsidir. „kardeşim var“ = „ich habe“ (bende var değil)." },
  { id: "de-a1.w394", ext: 1, t: "Ich bin verheiratet.", pos: "phr", n: "evliyim", ex: "Ich bin verheiratet und habe ein Kind.", exn: "Evliyim ve bir çocuğum var.", topic: "people", note: "Formda: ledig / verheiratet / geschieden. „Bekârım“ = „Ich bin ledig.“" },
  /* ---------- numbers: Zahlen, Zeit & Kalender (neu) ---------- */
  { id: "de-a1.w395", ext: 1, t: "dreizehn", pos: "x", n: "on üç", ex: "Meine Tochter ist dreizehn.", exn: "Kızım on üç yaşında.", topic: "numbers", note: "13–19 arası birler basamağı önce, sonra -zehn gelir: drei + zehn. Türkçede ise „on“ önce gelir." },
  { id: "de-a1.w396", ext: 1, t: "vierzehn", pos: "x", n: "on dört", ex: "Ich habe vierzehn Euro.", exn: "On dört avrom var.", topic: "numbers", note: "vier + zehn." },
  { id: "de-a1.w397", ext: 1, t: "fünfzehn", pos: "x", n: "on beş", ex: "Der Bus kommt in fünfzehn Minuten.", exn: "Otobüs on beş dakika sonra geliyor.", topic: "numbers", note: "fünf + zehn." },
  { id: "de-a1.w398", ext: 1, t: "sechzehn", pos: "x", n: "on altı", ex: "Sechzehn Personen kommen.", exn: "On altı kişi geliyor.", topic: "numbers", note: "sechs + zehn → sechzehn (s yazıda da düşer)." },
  { id: "de-a1.w399", ext: 1, t: "siebzehn", pos: "x", n: "on yedi", ex: "Er ist siebzehn Jahre alt.", exn: "O on yedi yaşında.", topic: "numbers", note: "„sieben“in -en kısmı düşer: siebzehn." },
  { id: "de-a1.w400", ext: 1, t: "achtzehn", pos: "x", n: "on sekiz", ex: "Meine Schwester ist achtzehn.", exn: "Kız kardeşim on sekiz yaşında.", topic: "numbers", note: "acht + zehn." },
  { id: "de-a1.w401", ext: 1, t: "neunzehn", pos: "x", n: "on dokuz", ex: "Meine Hausnummer ist neunzehn.", exn: "Kapı numaram on dokuz.", topic: "numbers", note: "neun + zehn." },
  { id: "de-a1.w402", ext: 1, t: "dreißig", pos: "x", n: "otuz", ex: "Ich bin dreißig Jahre alt.", exn: "Otuz yaşındayım.", topic: "numbers", note: "Onlar -zig ile biter (zwanzig, vierzig …); istisna: dreißig (-ßig). ch/-ig: Türkçe „hiç“teki h’ye yakın yumuşak ses, ç değil." },
  { id: "de-a1.w403", ext: 1, t: "vierzig", pos: "x", n: "kırk", ex: "Der Kurs kostet vierzig Euro.", exn: "Kursun ücreti kırk avro.", topic: "numbers", note: "vier + zig." },
  { id: "de-a1.w404", ext: 1, t: "fünfzig", pos: "x", n: "elli", ex: "Das Hemd kostet fünfzig Euro.", exn: "Gömlek elli avro.", topic: "numbers", note: "fünf + zig." },
  { id: "de-a1.w405", ext: 1, t: "sechzig", pos: "x", n: "altmış", ex: "Eine Stunde hat sechzig Minuten.", exn: "Bir saatte altmış dakika var.", topic: "numbers", note: "sechs → sech-: sechzig (s düşer)." },
  { id: "de-a1.w406", ext: 1, t: "siebzig", pos: "x", n: "yetmiş", ex: "Mein Opa ist siebzig.", exn: "Dedem yetmiş yaşında.", topic: "numbers", note: "sieben → sieb-: siebzig. Beş: fünfzig, altı: sechzig." },
  { id: "de-a1.w407", ext: 1, t: "achtzig", pos: "x", n: "seksen", ex: "Die Jacke kostet achtzig Euro.", exn: "Ceket seksen avro.", topic: "numbers", note: "acht + zig." },
  { id: "de-a1.w408", ext: 1, t: "neunzig", pos: "x", n: "doksan", ex: "Meine Oma ist neunzig Jahre alt.", exn: "Babaannem doksan yaşında.", topic: "numbers", note: "neun + zig." },
  { id: "de-a1.w409", ext: 1, t: "die Zahl", pl: "die Zahlen", pos: "n", n: "sayı; rakam", ex: "Die Zahl zehn kommt nach neun.", exn: "On sayısı dokuzdan sonra gelir.", topic: "numbers", note: "„Zahl“ sayı (10), „Nummer“ ise sıra/numara (telefon numarası) demektir." },
  { id: "de-a1.w410", ext: 1, t: "die Nummer", pl: "die Nummern", pos: "n", n: "numara", ex: "Ich habe die Nummer zwölf.", exn: "Benim numaram on iki.", topic: "numbers", note: "Telefon, ev, otobüs numarası için „Nummer“." },
  { id: "de-a1.w411", ext: 1, t: "die Sekunde", pl: "die Sekunden", pos: "n", n: "saniye", ex: "Warte eine Sekunde, bitte.", exn: "Bir saniye bekle lütfen.", topic: "numbers", note: "„Eine Sekunde“ günlük dilde „bir saniye (bekle)“ demektir." },
  { id: "de-a1.w412", ext: 1, t: "der Morgen", pl: "die Morgen", pos: "n", n: "sabah", ex: "Am Morgen trinke ich Tee.", exn: "Sabahları çay içerim.", topic: "numbers", note: "„Am Morgen“, „morgens“ ve „heute Morgen“ kalıplarını öğren. „morgen“ (küçük harf) ise „yarın“ demektir!" },
  { id: "de-a1.w413", ext: 1, t: "der Mittag", pl: "die Mittage", pos: "n", n: "öğle", ex: "Am Mittag essen wir zusammen.", exn: "Öğlen birlikte yemek yiyoruz.", topic: "numbers", note: "„Mittag“ öğle vakti (12–14 arası). Sondaki „g“ kuvvetli „k“ gibi okunur: Mittag [mittak]." },
  { id: "de-a1.w414", ext: 1, t: "die Mitternacht", pos: "n", n: "gece yarısı", ex: "Um Mitternacht schlafe ich.", exn: "Gece yarısı uyurum.", topic: "numbers", note: "Yalnızca tekil. „Um Mitternacht“ = gece yarısı. Nacht → Mitter-nacht." },
  { id: "de-a1.w415", ext: 1, t: "der Kalender", pl: "die Kalender", pos: "n", n: "takvim", ex: "Der Kalender hängt in der Küche.", exn: "Takvim mutfakta asılı.", topic: "numbers", note: "Çoğul tekille aynı: die Kalender." },
  { id: "de-a1.w416", ext: 1, t: "die Jahreszeit", pl: "die Jahreszeiten", pos: "n", n: "mevsim", ex: "Der Sommer ist eine schöne Jahreszeit.", exn: "Yaz güzel bir mevsim.", topic: "numbers", note: "Jahr + Zeit. Dört mevsim: Frühling, Sommer, Herbst, Winter." },
  { id: "de-a1.w417", ext: 1, t: "der Feiertag", pl: "die Feiertage", pos: "n", n: "resmî tatil günü", ex: "Am Feiertag ist der Supermarkt zu.", exn: "Resmî tatil günü market kapalı.", topic: "numbers", note: "Almanya’da pazar ve resmî tatillerde marketler genelde kapalıdır. „zu“ = kapalı." },
  { id: "de-a1.w418", ext: 1, t: "die Million", pl: "die Millionen", pos: "n", n: "milyon", ex: "Eine Million Euro ist viel Geld.", exn: "Bir milyon avro çok para.", topic: "numbers", note: "Dişil: die Million. „Eine Million Euro“ (Euro çoğulda -s almaz)." },
  { id: "de-a1.w419", ext: 1, t: "einmal", pos: "adv", n: "bir kez; bir defa", ex: "Ich war einmal in Berlin.", exn: "Bir kez Berlin’de bulundum.", topic: "numbers", note: "Sayı + -mal = „… kez“: einmal, zweimal, dreimal." },
  { id: "de-a1.w420", ext: 1, t: "zweimal", pos: "adv", n: "iki kez", ex: "Ich gehe zweimal pro Woche schwimmen.", exn: "Haftada iki kez yüzmeye gidiyorum.", topic: "numbers", note: "zwei + mal." },
  { id: "de-a1.w421", ext: 1, t: "dreimal", pos: "adv", n: "üç kez", ex: "Er ruft dreimal am Tag an.", exn: "Günde üç kez arıyor.", topic: "numbers", note: "drei + mal. „pro Tag“ = günde." },
  { id: "de-a1.w422", ext: 1, t: "das Ende", pl: "die Enden", pos: "n", n: "son; bitiş", ex: "Am Ende vom Monat bezahle ich die Miete.", exn: "Ay sonunda kirayı ödüyorum.", topic: "numbers", note: "„Am Ende“ = sonunda. Çoğul pek kullanılmaz." },
  { id: "de-a1.w423", ext: 1, t: "Wie viel Uhr ist es?", pos: "phr", n: "saat kaç?", ex: "Entschuldigung, wie viel Uhr ist es?", exn: "Affedersiniz, saat kaç?", topic: "numbers", note: "„Wie spät ist es?“ ile aynı. „Uhr“ hem saat (alet) hem „saat …“ demektir." },
  { id: "de-a1.w424", ext: 1, t: "Um wie viel Uhr?", pos: "phr", n: "saat kaçta?", ex: "Um wie viel Uhr beginnt der Kurs?", exn: "Kurs saat kaçta başlıyor?", topic: "numbers", note: "Zaman noktası için „um“ kullanılır: um drei Uhr. Türkçede ek (-de/-da) var, Almancada edat „um“." },
  { id: "de-a1.w425", ext: 1, t: "Viertel nach drei", pos: "phr", n: "üçü çeyrek geçiyor; 3:15", ex: "Es ist Viertel nach drei.", exn: "Saat üçü çeyrek geçiyor.", topic: "numbers", note: "Çeyrek geçe = „Viertel nach“. Dikkat: „halb vier“ 3:30’dur, 4:30 değil!" },
  { id: "de-a1.w426", ext: 1, t: "Viertel vor vier", pos: "phr", n: "dörde çeyrek var; 3:45", ex: "Der Zug fährt um Viertel vor vier.", exn: "Tren dörde çeyrek kala kalkıyor.", topic: "numbers", note: "Çeyrek kala = „Viertel vor“. Türkçede „dörde çeyrek var“ dediğin saati söyler." },
  { id: "de-a1.w427", ext: 1, t: "Wie alt bist du?", pos: "phr", n: "kaç yaşındasın?", ex: "Wie alt bist du? – Ich bin 25.", exn: "Kaç yaşındasın? – Yirmi beşim.", topic: "numbers", note: "Almancada „Ich bin 25 Jahre alt“ denir (haben değil, sein!). Türkçe „yaşındayım“ gibi düşün." },
  { id: "de-a1.w428", ext: 1, t: "Wann hast du Geburtstag?", pos: "phr", n: "doğum günün ne zaman?", ex: "Wann hast du Geburtstag? – Im Mai.", exn: "Doğum günün ne zaman? – Mayıs’ta.", topic: "numbers", note: "Almancada „Geburtstag haben“ diyoruz. Ay için „im“: im Mai." },
  { id: "de-a1.w429", ext: 1, t: "heute Abend", pos: "phr", n: "bu akşam", ex: "Heute Abend gehen wir ins Kino.", exn: "Bu akşam sinemaya gidiyoruz.", topic: "numbers", note: "„Abend“ burada büyük harf: heute Abend. Aynı kalıpla: heute Morgen, heute Mittag." },
  { id: "de-a1.w430", ext: 1, t: "am Wochenende", pos: "phr", n: "hafta sonu", ex: "Am Wochenende schlafe ich lange.", exn: "Hafta sonu uzun uyurum.", topic: "numbers", note: "Gün ve hafta sonu için „am“: am Montag, am Wochenende. Ay için „im“: im Mai." },
  /* ---------- food: Essen & Trinken (neu) ---------- */
  { id: "de-a1.w431", ext: 1, t: "die Butter", pos: "n", n: "tereyağı", ex: "Ich esse Brot mit Butter.", exn: "Ekmeği tereyağıyla yerim.", topic: "food", note: "Tekil. Dişil: die Butter." },
  { id: "de-a1.w432", ext: 1, t: "die Marmelade", pl: "die Marmeladen", pos: "n", n: "reçel", ex: "Ich mag Marmelade auf dem Brötchen.", exn: "Küçük ekmeğe reçel sürmeyi severim.", topic: "food", note: "Çoğul nadir. Kahvaltıda Brötchen + Butter + Marmelade klasiktir." },
  { id: "de-a1.w433", ext: 1, t: "der Honig", pos: "n", n: "bal", ex: "Der Honig ist süß.", exn: "Bal tatlıdır.", topic: "food", note: "Tekil, eril: der Honig." },
  { id: "de-a1.w434", ext: 1, t: "das Mehl", pos: "n", n: "un", ex: "Für den Kuchen brauche ich Mehl.", exn: "Kek için una ihtiyacım var.", topic: "food", note: "Tekil, nötr: das Mehl." },
  { id: "de-a1.w435", ext: 1, t: "das Öl", pl: "die Öle", pos: "n", n: "yağ (sıvı yağ)", ex: "Ich brauche Öl für den Salat.", exn: "Salata için yağa ihtiyacım var.", topic: "food", note: "Türkçede „yağ“ hem tereyağı hem sıvı yağdır; Almancada ayrı: Butter (tereyağı), Öl (sıvı yağ)." },
  { id: "de-a1.w436", ext: 1, t: "der Joghurt", pl: "die Joghurts", pos: "n", n: "yoğurt", ex: "Ich esse Joghurt mit Obst.", exn: "Meyveyle yoğurt yerim.", topic: "food", note: "Almancada „der Joghurt“ erildir (bazen „das Joghurt“ da denir). Çoğul -s." },
  { id: "de-a1.w437", ext: 1, t: "der Salat", pl: "die Salate", pos: "n", n: "salata; marul", ex: "Zum Essen gibt es Salat.", exn: "Yemekte salata var.", topic: "food", note: "„Der Salat“ hem salata hem marul demektir." },
  { id: "de-a1.w438", ext: 1, t: "die Gurke", pl: "die Gurken", pos: "n", n: "salatalık", ex: "Die Gurke ist frisch.", exn: "Salatalık taze.", topic: "food", note: "„Salzgurke“ ise turşudur. „Gurke“nin u sesi kısa." },
  { id: "de-a1.w439", ext: 1, t: "die Karotte", pl: "die Karotten", pos: "n", n: "havuç", ex: "Die Suppe hat Kartoffeln und Karotten.", exn: "Çorbada patates ve havuç var.", topic: "food", note: "Aynı anlamda „die Möhre“ de denir (kuzeyde daha yaygın)." },
  { id: "de-a1.w440", ext: 1, t: "die Paprika", pl: "die Paprikas", pos: "n", n: "biber; dolmalık biber", ex: "Ich kaufe zwei Paprika.", exn: "İki biber alıyorum.", topic: "food", note: "Dişil: die Paprika. Acı biber için: die Peperoni (scharf = acı)." },
  { id: "de-a1.w441", ext: 1, t: "die Birne", pl: "die Birnen", pos: "n", n: "armut", ex: "Die Birne ist sehr süß.", exn: "Armut çok tatlı.", topic: "food", note: "„Birne“ hem armut hem ampul (Glühbirne) anlamına gelebilir." },
  { id: "de-a1.w442", ext: 1, t: "die Orange", pl: "die Orangen", pos: "n", n: "portakal", ex: "Ich trinke gern Orangensaft.", exn: "Portakal suyu içmeyi severim.", topic: "food", note: "Dişil: die Orange. Meyve suyu: der Orangensaft." },
  { id: "de-a1.w443", ext: 1, t: "die Zitrone", pl: "die Zitronen", pos: "n", n: "limon", ex: "Ich nehme Tee mit Zitrone.", exn: "Çayı limonla alıyorum.", topic: "food", note: "Dişil: die Zitrone. Z burada „ts“ okunur: Tsitrone." },
  { id: "de-a1.w444", ext: 1, t: "die Erdbeere", pl: "die Erdbeeren", pos: "n", n: "çilek", ex: "Im Sommer esse ich Erdbeeren.", exn: "Yazın çilek yerim.", topic: "food", note: "Erd + Beere (yer + meyve)." },
  { id: "de-a1.w445", ext: 1, t: "die Traube", pl: "die Trauben", pos: "n", n: "üzüm", ex: "Die Trauben sind süß.", exn: "Üzümler tatlı.", topic: "food", note: "Çoğulu daha çok kullanılır: Trauben." },
  { id: "de-a1.w446", ext: 1, t: "die Wurst", pl: "die Würste", pos: "n", n: "sosis; salam", ex: "Ich esse keine Wurst.", exn: "Sosis/salam yemiyorum.", topic: "food", note: "Domuz ürünü olabilir. Alışverişte „aus Rind“ (sığır etinden) ya da „Geflügelwurst“ (tavuk/hindi) diye sorabilirsin." },
  { id: "de-a1.w447", ext: 1, t: "der Schinken", pl: "die Schinken", pos: "n", n: "jambon", ex: "Ein Brötchen mit Schinken, bitte.", exn: "Jambonlu bir sandviç lütfen.", topic: "food", note: "Genelde domuz etidir; „Putenschinken“ hindi jambonudur." },
  { id: "de-a1.w448", ext: 1, t: "die Pommes", pos: "n", n: "patates kızartması", ex: "Ich esse gern Pommes.", exn: "Patates kızartmasını severim.", topic: "food", note: "Çoğul kelime: die Pommes (frites). Tekil kullanılmaz." },
  { id: "de-a1.w449", ext: 1, t: "die Pizza", pl: "die Pizzas", pos: "n", n: "pizza", ex: "Ich möchte eine Pizza.", exn: "Bir pizza istiyorum.", topic: "food", note: "Dişil: die Pizza. Çoğul: Pizzas (ya da Pizzen)." },
  { id: "de-a1.w450", ext: 1, t: "die Schokolade", pl: "die Schokoladen", pos: "n", n: "çikolata", ex: "Die Kinder essen Schokolade.", exn: "Çocuklar çikolata yiyor.", topic: "food", note: "„Sch“ = Türkçe „ş“: Schokolade [şokolade]." },
  { id: "de-a1.w451", ext: 1, t: "das Eis", pos: "n", n: "dondurma; buz", ex: "Im Sommer essen wir viel Eis.", exn: "Yazın çok dondurma yeriz.", topic: "food", note: "Aynı kelime buz anlamına da gelir. Tekil." },
  { id: "de-a1.w452", ext: 1, t: "das Bier", pl: "die Biere", pos: "n", n: "bira", ex: "Das Bier kostet drei Euro.", exn: "Bira üç avro.", topic: "food", note: "Nötr: das Bier. Çoğul -e." },
  { id: "de-a1.w453", ext: 1, t: "der Wein", pl: "die Weine", pos: "n", n: "şarap", ex: "Der Wein ist rot.", exn: "Şarap kırmızı.", topic: "food", note: "Eril: der Wein. „Wein“ [vayn] okunur, W = v." },
  { id: "de-a1.w454", ext: 1, t: "die Limonade", pl: "die Limonaden", pos: "n", n: "gazoz; limonata", ex: "Die Kinder trinken Limonade.", exn: "Çocuklar gazoz içiyor.", topic: "food", note: "Almancada „Limonade“ gazlı, şekerli meşrubattır, taze limonata değil." },
  { id: "de-a1.w455", ext: 1, t: "das Mineralwasser", pos: "n", n: "maden suyu; (şişe) su", ex: "Ein Mineralwasser, bitte.", exn: "Bir maden suyu lütfen.", topic: "food", note: "Restoranda su sorarken: „mit Kohlensäure“ (gazlı) ya da „ohne“ (gazsız). Çoğul nadir." },
  { id: "de-a1.w456", ext: 1, t: "die Tasse", pl: "die Tassen", pos: "n", n: "fincan; bardak (çay/kahve)", ex: "Ich trinke eine Tasse Tee.", exn: "Bir fincan çay içiyorum.", topic: "food", note: "Miktar sözcüğünden sonra çoğul yok: eine Tasse Tee (Tees değil)." },
  { id: "de-a1.w457", ext: 1, t: "das Glas", pl: "die Gläser", pos: "n", n: "bardak; kavanoz", ex: "Ein Glas Wasser, bitte.", exn: "Bir bardak su lütfen.", topic: "food", note: "Çoğulda a → ä: Gläser. Miktarda çoğul yok: zwei Glas Wasser (ya da zwei Gläser Wasser)." },
  { id: "de-a1.w458", ext: 1, t: "die Mahlzeit", pl: "die Mahlzeiten", pos: "n", n: "öğün", ex: "Ich esse drei Mahlzeiten am Tag.", exn: "Günde üç öğün yerim.", topic: "food", note: "Mahl + Zeit. Öğle arasında iş yerlerinde „Mahlzeit!“ diye selamlaşılır." },
  { id: "de-a1.w459", ext: 1, t: "vegetarisch", pos: "adj", n: "vejetaryen; etsiz", ex: "Ich esse vegetarisch.", exn: "Vejetaryen besleniyorum.", topic: "food", note: "Sıfat ve zarf aynı: Das Essen ist vegetarisch / Ich esse vegetarisch." },
  { id: "de-a1.w460", ext: 1, t: "Ich habe Hunger.", pos: "phr", n: "acıktım; karnım aç", ex: "Ich habe Hunger, ich möchte etwas essen.", exn: "Acıktım, bir şey yemek istiyorum.", topic: "food", note: "Almancada „Hunger haben“ (açlığı olmak) denir, „Ich bin hungrig“ pek kullanılmaz. Aynı: Durst haben." },
  { id: "de-a1.w461", ext: 1, t: "Ich habe Durst.", pos: "phr", n: "susadım", ex: "Ich habe Durst. Hast du Wasser?", exn: "Susadım. Suyun var mı?", topic: "food", note: "„Durst haben“ – „Ich bin durstig“ daha az kullanılır." },
  { id: "de-a1.w462", ext: 1, t: "Das schmeckt gut.", pos: "phr", n: "bu lezzetli; tadı güzel", ex: "Das schmeckt gut, danke!", exn: "Çok lezzetli, teşekkürler!", topic: "food", note: "Özne „das“ (yemek) – kişi değil. Güzel yemek için: „Das schmeckt sehr gut!“." },
  { id: "de-a1.w463", ext: 1, t: "Was möchten Sie trinken?", pos: "phr", n: "ne içmek istersiniz?", ex: "Was möchten Sie trinken? – Einen Tee, bitte.", exn: "Ne içmek istersiniz? – Bir çay lütfen.", topic: "food", note: "Garson böyle sorar. Cevap: „Einen Tee, bitte.“ (eril → einen)." },
  { id: "de-a1.w464", ext: 1, t: "Ich möchte einen Kaffee, bitte.", pos: "phr", n: "bir kahve istiyorum lütfen", ex: "Ich möchte einen Kaffee, bitte.", exn: "Bir kahve istiyorum lütfen.", topic: "food", note: "Sipariş verirken nazik kalıp. „Ich will“ kaba sayılır, „möchte“ kullan." },
  { id: "de-a1.w465", ext: 1, t: "Mit Milch und Zucker, bitte.", pos: "phr", n: "sütlü ve şekerli lütfen", ex: "Einen Kaffee mit Milch und Zucker, bitte.", exn: "Sütlü ve şekerli bir kahve lütfen.", topic: "food", note: "„mit“ ile ürünler artikelsiz söylenebilir: mit Milch, mit Zucker. „Ohne Zucker“ = şekersiz." },
  { id: "de-a1.w466", ext: 1, t: "Ich esse kein Fleisch.", pos: "phr", n: "et yemiyorum", ex: "Ich esse kein Fleisch, aber ich esse Fisch.", exn: "Et yemiyorum ama balık yiyorum.", topic: "food", note: "Artikelsiz isimde olumsuzluk „kein“ ile: kein Fleisch (nicht Fleisch değil)." },
  /* ---------- home: Wohnen & Haushalt (neu) ---------- */
  { id: "de-a1.w467", ext: 1, t: "der Herd", pl: "die Herde", pos: "n", n: "ocak; fırınlı ocak", ex: "Der Herd in der Küche ist neu.", exn: "Mutfaktaki ocak yeni.", topic: "home", note: "„Herd“ ocak, „Backofen“ fırın demektir." },
  { id: "de-a1.w468", ext: 1, t: "der Ofen", pl: "die Öfen", pos: "n", n: "fırın; soba", ex: "Der Kuchen ist im Ofen.", exn: "Kek fırında.", topic: "home", note: "Çoğulda o → ö: Öfen. Fırın = Backofen." },
  { id: "de-a1.w469", ext: 1, t: "der Topf", pl: "die Töpfe", pos: "n", n: "tencere; saksı", ex: "Die Suppe ist im Topf.", exn: "Çorba tencerede.", topic: "home", note: "Çoğul: o → ö, Töpfe. Aynı kelime saksı (Blumentopf) için de kullanılır." },
  { id: "de-a1.w470", ext: 1, t: "die Pfanne", pl: "die Pfannen", pos: "n", n: "tava", ex: "Das Ei ist in der Pfanne.", exn: "Yumurta tavada.", topic: "home", note: "Dişil. „pf“ sesi iki harf birden okunur: p+f." },
  { id: "de-a1.w471", ext: 1, t: "die Wand", pl: "die Wände", pos: "n", n: "duvar", ex: "Das Bild hängt an der Wand.", exn: "Resim duvarda asılı.", topic: "home", note: "Çoğulda a → ä: Wände." },
  { id: "de-a1.w472", ext: 1, t: "der Boden", pl: "die Böden", pos: "n", n: "zemin; yer", ex: "Das Buch liegt auf dem Boden.", exn: "Kitap yerde duruyor.", topic: "home", note: "Çoğul: o → ö. Evin zemini için de „Fußboden“ denir." },
  { id: "de-a1.w473", ext: 1, t: "die Decke", pl: "die Decken", pos: "n", n: "tavan; battaniye", ex: "Die Lampe hängt an der Decke.", exn: "Lamba tavanda asılı.", topic: "home", note: "Aynı kelime hem tavan hem örtü/battaniye anlamındadır. Anlam cümleden çıkar." },
  { id: "de-a1.w474", ext: 1, t: "das Licht", pl: "die Lichter", pos: "n", n: "ışık", ex: "Ich brauche Licht.", exn: "Işığa ihtiyacım var.", topic: "home", note: "ch/-ig: Türkçe „hiç“teki h’ye yakın yumuşak ses, ç değil. „Licht anmachen“ = ışığı açmak." },
  { id: "de-a1.w475", ext: 1, t: "der Spiegel", pl: "die Spiegel", pos: "n", n: "ayna", ex: "Der Spiegel hängt im Bad.", exn: "Ayna banyoda asılı.", topic: "home", note: "„Sp“ başta „şp“ okunur: Spiegel [şpigıl]." },
  { id: "de-a1.w476", ext: 1, t: "die Seife", pl: "die Seifen", pos: "n", n: "sabun", ex: "Wo ist die Seife?", exn: "Sabun nerede?", topic: "home", note: "„ei“ = „ay“: Seife [zayfe]." },
  { id: "de-a1.w477", ext: 1, t: "das Handtuch", pl: "die Handtücher", pos: "n", n: "el havlusu; havlu", ex: "Ich brauche ein Handtuch.", exn: "Bir havluya ihtiyacım var.", topic: "home", note: "Hand + Tuch. Çoğul: Handtücher (u → ü)." },
  { id: "de-a1.w478", ext: 1, t: "die Zahnbürste", pl: "die Zahnbürsten", pos: "n", n: "diş fırçası", ex: "Meine Zahnbürste ist blau.", exn: "Diş fırçam mavi.", topic: "home", note: "Zahn + Bürste. Dişil." },
  { id: "de-a1.w479", ext: 1, t: "das Bild", pl: "die Bilder", pos: "n", n: "resim; tablo", ex: "Das Bild ist sehr schön.", exn: "Resim çok güzel.", topic: "home", note: "Çoğul -er: Bilder. Fotoğraf için de kullanılır." },
  { id: "de-a1.w480", ext: 1, t: "das Radio", pl: "die Radios", pos: "n", n: "radyo", ex: "Das Radio ist in der Küche.", exn: "Radyo mutfakta.", topic: "home", note: "Nötr: das Radio. Çoğul -s." },
  { id: "de-a1.w481", ext: 1, t: "der Staubsauger", pl: "die Staubsauger", pos: "n", n: "elektrik süpürgesi", ex: "Der Staubsauger ist kaputt.", exn: "Elektrik süpürgesi bozuk.", topic: "home", note: "Staub + Sauger. „staubsaugen“ = süpürmek (fiil)." },
  { id: "de-a1.w482", ext: 1, t: "der Sessel", pl: "die Sessel", pos: "n", n: "koltuk", ex: "Opa sitzt im Sessel.", exn: "Dede koltukta oturuyor.", topic: "home", note: "Tek kişilik koltuk. Sofa = kanepe." },
  { id: "de-a1.w483", ext: 1, t: "das Kissen", pl: "die Kissen", pos: "n", n: "yastık", ex: "Ich brauche ein Kissen.", exn: "Bir yastığa ihtiyacım var.", topic: "home", note: "Çoğul tekille aynı: die Kissen." },
  { id: "de-a1.w484", ext: 1, t: "das Dach", pl: "die Dächer", pos: "n", n: "çatı", ex: "Das Haus hat ein rotes Dach.", exn: "Evin kırmızı bir çatısı var.", topic: "home", note: "Çoğul: a → ä, Dächer. „ch“ burada [x] (arka damak)." },
  { id: "de-a1.w485", ext: 1, t: "die Garage", pl: "die Garagen", pos: "n", n: "garaj", ex: "Das Auto steht in der Garage.", exn: "Araba garajda duruyor.", topic: "home", note: "„ge“ burada „j“ gibi: Garage [garaje]." },
  { id: "de-a1.w486", ext: 1, t: "die Badewanne", pl: "die Badewannen", pos: "n", n: "küvet", ex: "Wir haben eine Badewanne im Bad.", exn: "Banyoda küvetimiz var.", topic: "home", note: "Bade + Wanne. Duş: die Dusche (A2)." },
  { id: "de-a1.w487", ext: 1, t: "zu Hause", pos: "phr", n: "evde", ex: "Ich bin heute zu Hause.", exn: "Bugün evdeyim.", topic: "home", note: "„Zu Hause“ = evde (nerede?). Küçük „zu“, büyük „Hause“. „nach Hause“ = eve (nereye?)." },
  { id: "de-a1.w488", ext: 1, t: "nach Hause", pos: "phr", n: "eve (doğru)", ex: "Ich gehe jetzt nach Hause.", exn: "Şimdi eve gidiyorum.", topic: "home", note: "Yön için „nach Hause“, durum için „zu Hause“. Türkçede eve/evde ek farkı, Almancada edat farkı." },
  { id: "de-a1.w489", ext: 1, t: "Wo wohnst du?", pos: "phr", n: "nerede oturuyorsun?", ex: "Wo wohnst du? – In Köln.", exn: "Nerede oturuyorsun? – Köln’de.", topic: "home", note: "Şehir adı „in“ ile: in Köln, in Berlin. Soru: „Wo wohnen Sie?“ (resmî)." },
  { id: "de-a1.w490", ext: 1, t: "Ich wohne allein.", pos: "phr", n: "tek başıma oturuyorum", ex: "Ich wohne allein in einer kleinen Wohnung.", exn: "Küçük bir dairede tek başıma oturuyorum.", topic: "home", note: "„allein“ = yalnız/tek başına. „einsam“ (A2) ise yalnızlık hissidir." },
  /* ---------- city: Stadt, Wege & Verkehr (neu) ---------- */
  { id: "de-a1.w491", ext: 1, t: "das Zentrum", pl: "die Zentren", pos: "n", n: "merkez; şehir merkezi", ex: "Die Bank ist im Zentrum.", exn: "Banka şehir merkezinde.", topic: "city", note: "„Im Zentrum“ ya da „in der Stadtmitte“. Çoğul: Zentren." },
  { id: "de-a1.w492", ext: 1, t: "das Dorf", pl: "die Dörfer", pos: "n", n: "köy", ex: "Meine Oma wohnt im Dorf.", exn: "Babaannem köyde oturuyor.", topic: "city", note: "Çoğul: o → ö, Dörfer. Nötr: das Dorf." },
  { id: "de-a1.w493", ext: 1, t: "das Land", pl: "die Länder", pos: "n", n: "ülke; kırsal; (bölge)", ex: "Deutschland ist ein großes Land.", exn: "Almanya büyük bir ülke.", topic: "city", note: "Hem ülke hem kırsal kesim: „auf dem Land“ = kırda/köyde. Çoğul: Länder." },
  { id: "de-a1.w494", ext: 1, t: "der Stadtplan", pl: "die Stadtpläne", pos: "n", n: "şehir planı; harita", ex: "Ich habe einen Stadtplan.", exn: "Bir şehir planım var.", topic: "city", note: "Stadt + Plan. Yol tarifi için kullanılır; telefon haritası = die Karte/die App." },
  { id: "de-a1.w495", ext: 1, t: "das Schild", pl: "die Schilder", pos: "n", n: "tabela; levha", ex: "Auf dem Schild steht „Ausgang“.", exn: "Tabelada „Çıkış“ yazıyor.", topic: "city", note: "Nötr, çoğul -er: Schilder. Yol levhası da Schild’dir." },
  { id: "de-a1.w496", ext: 1, t: "das Café", pl: "die Cafés", pos: "n", n: "kafe", ex: "Das Café ist in der Nähe.", exn: "Kafe yakında.", topic: "city", note: "Fransızca: Café [kafe:] sonu uzun e. Çoğul -s." },
  { id: "de-a1.w497", ext: 1, t: "die Straßenbahn", pl: "die Straßenbahnen", pos: "n", n: "tramvay", ex: "Die Straßenbahn fährt bis zum Bahnhof.", exn: "Tramvay gara kadar gidiyor.", topic: "city", note: "Straße + Bahn. Kısaca „die Bahn“ da denir." },
  { id: "de-a1.w498", ext: 1, t: "das Motorrad", pl: "die Motorräder", pos: "n", n: "motosiklet", ex: "Mein Onkel hat ein Motorrad.", exn: "Amcamın bir motosikleti var.", topic: "city", note: "Motor + Rad. Çoğul: Motorräder (a → ä)." },
  { id: "de-a1.w499", ext: 1, t: "die Fahrt", pl: "die Fahrten", pos: "n", n: "yolculuk; sürüş", ex: "Die Fahrt ist lang.", exn: "Yolculuk uzun.", topic: "city", note: "„fahren“ fiilinden. Kısa yolculuk, sürüş. Uzun seyahat: die Reise (A2)." },
  { id: "de-a1.w500", ext: 1, t: "der Fußgänger", pl: "die Fußgänger", pos: "n", n: "yaya", ex: "Die Ampel ist für Fußgänger.", exn: "Işık yayalar için.", topic: "city", note: "Fuß + Gänger (yürüyen). „Fußgängerzone“ (A2) yaya bölgesidir." },
  { id: "de-a1.w501", ext: 1, t: "der Ort", pl: "die Orte", pos: "n", n: "yer; yerleşim yeri", ex: "Der Ort ist klein, aber schön.", exn: "Yer küçük ama güzel.", topic: "city", note: "Küçük şehir ya da yer. Formda: „Wohnort“ = ikamet yeri." },
  { id: "de-a1.w502", ext: 1, t: "der Norden", pos: "n", n: "kuzey", ex: "Hamburg liegt im Norden.", exn: "Hamburg kuzeyde.", topic: "city", note: "Yön sözcükleri hep eril, artikelli: im Norden, im Süden, im Osten, im Westen." },
  { id: "de-a1.w503", ext: 1, t: "der Süden", pos: "n", n: "güney", ex: "Im Süden ist es warm.", exn: "Güneyde hava sıcak.", topic: "city", note: "Çoğul yok. „im Süden“ = güneyde." },
  { id: "de-a1.w504", ext: 1, t: "der Osten", pos: "n", n: "doğu", ex: "Berlin liegt im Osten.", exn: "Berlin doğuda.", topic: "city", note: "„im Osten“ = doğuda. Çoğul yok." },
  { id: "de-a1.w505", ext: 1, t: "der Westen", pos: "n", n: "batı", ex: "Köln liegt im Westen von Deutschland.", exn: "Köln Almanya’nın batısında.", topic: "city", note: "„im Westen“ = batıda. Çoğul yok." },
  { id: "de-a1.w506", ext: 1, t: "die Postleitzahl", pl: "die Postleitzahlen", pos: "n", n: "posta kodu", ex: "Wie ist Ihre Postleitzahl?", exn: "Posta kodunuz nedir?", topic: "city", note: "Formlarda kısaltma: PLZ. Adreste şehirden önce yazılır: 53111 Bonn." },
  { id: "de-a1.w507", ext: 1, t: "die Hausnummer", pl: "die Hausnummern", pos: "n", n: "kapı numarası", ex: "Die Hausnummer ist zwölf.", exn: "Kapı numarası on iki.", topic: "city", note: "Almanya’da adreste önce sokak adı, sonra numara yazılır: Lindenstraße 12." },
  { id: "de-a1.w508", ext: 1, t: "die Linie", pl: "die Linien", pos: "n", n: "hat; (otobüs) numarası", ex: "Die Linie fünf fährt zum Bahnhof.", exn: "Beş numaralı hat gara gidiyor.", topic: "city", note: "„Linie 5“ = 5 numaralı hat. „Linie“ i-e yazılır: [li:nie]." },
  { id: "de-a1.w509", ext: 1, t: "das Ticket", pl: "die Tickets", pos: "n", n: "bilet", ex: "Ich habe ein Ticket für den Bus.", exn: "Otobüs için biletim var.", topic: "city", note: "„Fahrkarte“ ile aynı; „Ticket“ günlük dilde daha yaygın. Çoğul -s." },
  { id: "de-a1.w510", ext: 1, t: "der Automat", pl: "die Automaten", pos: "n", n: "otomat; (bilet) makinesi", ex: "Die Fahrkarte kaufe ich am Automaten.", exn: "Bileti otomattan alıyorum.", topic: "city", note: "Eril, n-Deklination: den Automaten. Çoğul -en." },
  { id: "de-a1.w511", ext: 1, t: "zu Fuß", pos: "phr", n: "yaya olarak; yürüyerek", ex: "Ich gehe zu Fuß zur Schule.", exn: "Okula yürüyerek gidiyorum.", topic: "city", note: "Aynı kalıp: „mit dem Bus“ (otobüsle), „zu Fuß“ (yürüyerek). Edat „zu“ + Fuß (Fuß ayak!)." },
  { id: "de-a1.w512", ext: 1, t: "Wo ist der Bahnhof?", pos: "phr", n: "gar/istasyon nerede?", ex: "Entschuldigung, wo ist der Bahnhof?", exn: "Affedersiniz, istasyon nerede?", topic: "city", note: "Yer sorusu: „Wo ist …?“ + artikel. Dişil için: „Wo ist die Post?“, nötr: „Wo ist das Kino?“" },
  { id: "de-a1.w513", ext: 1, t: "Gehen Sie geradeaus.", pos: "phr", n: "düz gidin", ex: "Gehen Sie geradeaus und dann links.", exn: "Düz gidin, sonra sola dönün.", topic: "city", note: "Resmî emir: fiil + Sie. „Sie“ fiilin arkasında: Gehen Sie! – „Sie gehen“ değil." },
  { id: "de-a1.w514", ext: 1, t: "Ich fahre mit dem Bus.", pos: "phr", n: "otobüsle gidiyorum", ex: "Ich fahre mit dem Bus zur Arbeit.", exn: "İşe otobüsle gidiyorum.", topic: "city", note: "„mit“ ile her zaman Dativ: mit dem Bus, mit der Bahn. Türkçe „-le/-la“ karşılığı." },
  { id: "de-a1.w515", ext: 1, t: "Wo ist die Toilette?", pos: "phr", n: "tuvalet nerede?", ex: "Entschuldigung, wo ist die Toilette?", exn: "Affedersiniz, tuvalet nerede?", topic: "city", note: "Çok işe yarar kalıp. Kapılarda: „Damen“ (bayan), „Herren“ (erkek)." },
  { id: "de-a1.w516", ext: 1, t: "Ich bin neu hier.", pos: "phr", n: "buralarda yeniyim", ex: "Ich bin neu hier. Wo ist die Post?", exn: "Buralarda yeniyim. Postane nerede?", topic: "city", note: "Yol sormadan önce söylenen sempatik kalıp. „neu“ burada „yeni gelmiş“ demek." },
  /* ---------- shop: Einkaufen & Kleidung (neu) ---------- */
  { id: "de-a1.w517", ext: 1, t: "der Gürtel", pl: "die Gürtel", pos: "n", n: "kemer", ex: "Der Gürtel ist zu lang.", exn: "Kemer çok uzun.", topic: "shop", note: "Eril, çoğul aynı: die Gürtel." },
  { id: "de-a1.w518", ext: 1, t: "die Brille", pl: "die Brillen", pos: "n", n: "gözlük", ex: "Ich brauche eine neue Brille.", exn: "Yeni bir gözlüğe ihtiyacım var.", topic: "shop", note: "Tekil kullanılır: eine Brille, die Brille (Türkçe „gözlük“ gibi). Çoğul: Brillen = birkaç gözlük." },
  { id: "de-a1.w519", ext: 1, t: "der Hut", pl: "die Hüte", pos: "n", n: "şapka", ex: "Der Hut ist schön.", exn: "Şapka güzel.", topic: "shop", note: "Çoğul: u → ü. „Mütze“ ise bere/kasket (A2)." },
  { id: "de-a1.w520", ext: 1, t: "der Handschuh", pl: "die Handschuhe", pos: "n", n: "eldiven", ex: "Meine Handschuhe sind warm.", exn: "Eldivenlerim sıcak.", topic: "shop", note: "Hand + Schuh (el ayakkabısı!). Çoğul -e." },
  { id: "de-a1.w521", ext: 1, t: "der Anzug", pl: "die Anzüge", pos: "n", n: "takım elbise", ex: "Der Anzug ist neu.", exn: "Takım elbise yeni.", topic: "shop", note: "Çoğul: u → ü: Anzüge. Eril akuzatif: einen Anzug." },
  { id: "de-a1.w522", ext: 1, t: "die Bluse", pl: "die Blusen", pos: "n", n: "bluz; gömlek (kadın)", ex: "Die Bluse ist weiß.", exn: "Bluz beyaz.", topic: "shop", note: "Kadın gömleği = Bluse, erkek gömleği = Hemd." },
  { id: "de-a1.w523", ext: 1, t: "die Jeans", pl: "die Jeans", pos: "n", n: "kot pantolon", ex: "Ich kaufe eine Jeans.", exn: "Bir kot pantolon alıyorum.", topic: "shop", note: "Almancada „die Jeans“ tek kelime; çoğul biçimi aynı. Türkçedeki gibi „bir kot“ diyebilirsin." },
  { id: "de-a1.w524", ext: 1, t: "das Geschenk", pl: "die Geschenke", pos: "n", n: "hediye", ex: "Das Geschenk ist für meine Mutter.", exn: "Hediye annem için.", topic: "shop", note: "Nötr. „Ein Geschenk machen“ = hediye vermek." },
  { id: "de-a1.w525", ext: 1, t: "das Stück", pl: "die Stücke", pos: "n", n: "parça; adet", ex: "Ein Stück Kuchen, bitte.", exn: "Bir dilim kek lütfen.", topic: "shop", note: "Dilim/parça/adet anlamı var. Fiyatta: „drei Euro das Stück“ = tanesi üç avro." },
  { id: "de-a1.w526", ext: 1, t: "das Gramm", pl: "die Gramm", pos: "n", n: "gram", ex: "Zweihundert Gramm Käse, bitte.", exn: "İki yüz gram peynir lütfen.", topic: "shop", note: "Miktarda çoğul eki yok: zweihundert Gramm (Gramme değil)." },
  { id: "de-a1.w527", ext: 1, t: "der Liter", pl: "die Liter", pos: "n", n: "litre", ex: "Ein Liter Milch kostet einen Euro.", exn: "Bir litre süt bir avro.", topic: "shop", note: "Sayıdan sonra çoğul eki yok: zwei Liter Milch." },
  { id: "de-a1.w528", ext: 1, t: "die Dose", pl: "die Dosen", pos: "n", n: "kutu; konserve", ex: "Eine Dose Tomaten, bitte.", exn: "Bir kutu domates lütfen.", topic: "shop", note: "Dişil. Konserve kutusu için de kullanılır." },
  { id: "de-a1.w529", ext: 1, t: "der Cent", pl: "die Cent", pos: "n", n: "kuruş; sent", ex: "Das kostet fünfzig Cent.", exn: "Bu elli sent.", topic: "shop", note: "Sayıdan sonra çoğul yok: fünfzig Cent. 1 Euro = 100 Cent. Türkçede kuruş." },
  { id: "de-a1.w530", ext: 1, t: "das Wechselgeld", pos: "n", n: "para üstü", ex: "Hier ist Ihr Wechselgeld.", exn: "İşte para üstünüz.", topic: "shop", note: "Tekil. „Kleingeld“ da küçük bozuk para demektir." },
  { id: "de-a1.w531", ext: 1, t: "der Stiefel", pl: "die Stiefel", pos: "n", n: "bot; çizme", ex: "Meine Stiefel sind neu.", exn: "Botlarım yeni.", topic: "shop", note: "Çoğul aynı: die Stiefel. Ayakkabılar da „die Schuhe“ (çoğul)." },
  { id: "de-a1.w532", ext: 1, t: "die Sandale", pl: "die Sandalen", pos: "n", n: "sandalet", ex: "Ich mag die Sandalen.", exn: "Sandaletleri seviyorum.", topic: "shop", note: "Genelde çoğulda kullanılır: Sandalen." },
  { id: "de-a1.w533", ext: 1, t: "Was kostet das?", pos: "phr", n: "bu kaç para?", ex: "Was kostet das Brot?", exn: "Bu ekmek kaç para?", topic: "shop", note: "„Wie viel kostet das?“ ile aynı. Fiil „kostet“ (3. tekil): was kostet – was kosten (çoğul)." },
  { id: "de-a1.w534", ext: 1, t: "Ich suche eine Jacke.", pos: "phr", n: "bir ceket arıyorum", ex: "Ich suche eine Jacke, Größe M.", exn: "Bir ceket arıyorum, M beden.", topic: "shop", note: "„suchen“ hep akuzatif ister: eine Jacke (dişil aynı), einen Mantel (eril)." },
  { id: "de-a1.w535", ext: 1, t: "Ich möchte bezahlen.", pos: "phr", n: "ödemek istiyorum; hesap lütfen", ex: "Ich möchte bezahlen, bitte.", exn: "Ödemek istiyorum lütfen.", topic: "shop", note: "Restoranda kullanılır. „Zusammen oder getrennt?“ = birlikte mi ayrı mı?" },
  { id: "de-a1.w536", ext: 1, t: "Bar oder mit Karte?", pos: "phr", n: "nakit mi, kartla mı?", ex: "Bar oder mit Karte? – Mit Karte, bitte.", exn: "Nakit mi kartla mı? – Kartla lütfen.", topic: "shop", note: "„bar“ = nakit. Kasada sık duyulan soru." },
  { id: "de-a1.w537", ext: 1, t: "Haben Sie das in Blau?", pos: "phr", n: "bunun mavisi var mı?", ex: "Haben Sie das in Blau?", exn: "Bunun mavisi var mı?", topic: "shop", note: "„Haben Sie …?“ ile stoğu sorarsın. Renk için „in“: in Blau, in Schwarz." },
  { id: "de-a1.w538", ext: 1, t: "Das ist zu groß.", pos: "phr", n: "bu çok büyük", ex: "Die Hose ist zu groß.", exn: "Pantolon çok büyük.", topic: "shop", note: "„zu“ + sıfat = „fazla/çok (olumsuz)“. „sehr groß“ ise sadece „çok büyük“, sorun belirtmez." },
  /* ---------- work: Arbeit, Schule & Ämter (neu) ---------- */
  { id: "de-a1.w539", ext: 1, t: "der Koch", pl: "die Köche", pos: "n", n: "aşçı (erkek)", ex: "Mein Vater ist Koch.", exn: "Babam aşçı.", topic: "work", note: "Çoğul o → ö: Köche. Meslek bildirirken artikel yok: „Er ist Koch.“" },
  { id: "de-a1.w540", ext: 1, t: "die Köchin", pl: "die Köchinnen", pos: "n", n: "aşçı (kadın)", ex: "Meine Tante ist Köchin.", exn: "Teyzem aşçı.", topic: "work", note: "Kadın: -in, çoğul -innen. „Er ist Koch“ gibi artikelsiz." },
  { id: "de-a1.w541", ext: 1, t: "der Bäcker", pl: "die Bäcker", pos: "n", n: "fırıncı; ekmekçi", ex: "Der Bäcker öffnet um sechs Uhr.", exn: "Fırıncı saat altıda açıyor.", topic: "work", note: "Çoğul aynı. Fırın dükkânı: die Bäckerei." },
  { id: "de-a1.w542", ext: 1, t: "der Polizist", pl: "die Polizisten", pos: "n", n: "polis (erkek)", ex: "Der Polizist hilft uns.", exn: "Polis bize yardım ediyor.", topic: "work", note: "n-Deklination: den Polizisten. Kadın: die Polizistin." },
  { id: "de-a1.w543", ext: 1, t: "der Ingenieur", pl: "die Ingenieure", pos: "n", n: "mühendis", ex: "Mein Bruder ist Ingenieur.", exn: "Kardeşim mühendis.", topic: "work", note: "„Ingenieur“ [injenyör] gibi okunur. Meslekte artikel yok." },
  { id: "de-a1.w544", ext: 1, t: "der Friseur", pl: "die Friseure", pos: "n", n: "berber; kuaför", ex: "Ich gehe zum Friseur.", exn: "Berbere gidiyorum.", topic: "work", note: "„Friseur“ (Fransızca kökenli) „frizör“ diye okunur. Kadın: die Friseurin ya da die Friseuse." },
  { id: "de-a1.w545", ext: 1, t: "der Fahrer", pl: "die Fahrer", pos: "n", n: "şoför; sürücü", ex: "Der Fahrer ist sehr nett.", exn: "Şoför çok iyi biri.", topic: "work", note: "Fahren + -er. Kadın: Fahrerin. Taksi şoförü: Taxifahrer." },
  { id: "de-a1.w546", ext: 1, t: "die Ärztin", pl: "die Ärztinnen", pos: "n", n: "kadın doktor", ex: "Meine Ärztin ist sehr nett.", exn: "Doktorum çok iyi biri.", topic: "work", note: "Erkek: der Arzt (Çoğul: die Ärzte). Dikkat: a → ä." },
  { id: "de-a1.w547", ext: 1, t: "die Lehrerin", pl: "die Lehrerinnen", pos: "n", n: "kadın öğretmen", ex: "Die Lehrerin erklärt das Wort.", exn: "Öğretmen kelimeyi açıklıyor.", topic: "work", note: "Erkek: Lehrer. Hitap: „Frau Weber“ – „Lehrerin Weber“ denmez." },
  { id: "de-a1.w548", ext: 1, t: "die Krankenschwester", pl: "die Krankenschwestern", pos: "n", n: "hemşire", ex: "Die Krankenschwester ist nett.", exn: "Hemşire çok iyi biri.", topic: "work", note: "Krank + en + Schwester. Erkek hemşire: Krankenpfleger." },
  { id: "de-a1.w549", ext: 1, t: "der Programmierer", pl: "die Programmierer", pos: "n", n: "yazılımcı; programcı", ex: "Ich bin Programmierer von Beruf.", exn: "Mesleğim yazılımcı.", topic: "work", note: "„von Beruf“ = mesleği. Artikel yok: „Ich bin Programmierer“. Kadın: die Programmiererin." },
  { id: "de-a1.w550", ext: 1, t: "die Universität", pl: "die Universitäten", pos: "n", n: "üniversite", ex: "Die Universität ist groß.", exn: "Üniversite büyük.", topic: "work", note: "„an der Universität“ = üniversitede. Kısaca: die Uni (günlük dilde)." },
  { id: "de-a1.w551", ext: 1, t: "der Unterricht", pos: "n", n: "ders; eğitim", ex: "Der Unterricht beginnt um acht Uhr.", exn: "Ders saat sekizde başlıyor.", topic: "work", note: "Tekil, eril. „Im Unterricht“ = derste. Tek ders için: die Stunde." },
  { id: "de-a1.w552", ext: 1, t: "der Stift", pl: "die Stifte", pos: "n", n: "kalem", ex: "Hast du einen Stift?", exn: "Kalemin var mı?", topic: "work", note: "Her tür kalem (kurşun, tükenmez). Kurşun kalem: der Bleistift." },
  { id: "de-a1.w553", ext: 1, t: "die Frage", pl: "die Fragen", pos: "n", n: "soru", ex: "Ich habe eine Frage.", exn: "Bir sorum var.", topic: "work", note: "„eine Frage haben“ = soru sormak istemek. „Fragen“ fiili ile karıştırma: fragen (fiil), die Frage (isim)." },
  { id: "de-a1.w554", ext: 1, t: "die Antwort", pl: "die Antworten", pos: "n", n: "cevap", ex: "Die Antwort ist richtig.", exn: "Cevap doğru.", topic: "work", note: "Fiil: antworten. Dişil." },
  { id: "de-a1.w555", ext: 1, t: "das Wort", pl: "die Wörter", pos: "n", n: "kelime; söz", ex: "Das Wort ist neu für mich.", exn: "Kelime benim için yeni.", topic: "work", note: "Çoğul iki türlü: „Wörter“ (tek tek kelimeler), „Worte“ (konuşma, sözler). Okulda genelde Wörter." },
  { id: "de-a1.w556", ext: 1, t: "die Sprache", pl: "die Sprachen", pos: "n", n: "dil", ex: "Ich lerne die deutsche Sprache.", exn: "Alman dilini öğreniyorum.", topic: "work", note: "„Sprache“ = dil (konuşma). Organ olan dil ise „die Zunge“." },
  { id: "de-a1.w557", ext: 1, t: "Was sind Sie von Beruf?", pos: "phr", n: "mesleğiniz nedir?", ex: "Was sind Sie von Beruf? – Ich bin Lehrer.", exn: "Mesleğiniz nedir? – Öğretmenim.", topic: "work", note: "„von Beruf“ meslek sorusunda sabit. Cevap artikelsiz: Ich bin Lehrer." },
  { id: "de-a1.w558", ext: 1, t: "Ich bin Student.", pos: "phr", n: "üniversite öğrencisiyim", ex: "Ich bin Student und wohne in Köln.", exn: "Üniversite öğrencisiyim ve Köln’de oturuyorum.", topic: "work", note: "Meslek/durum bildirirken „ein“ kullanılmaz: Ich bin Student (nicht: ein Student)." },
  { id: "de-a1.w559", ext: 1, t: "Ich arbeite bei einer Firma.", pos: "phr", n: "bir firmada çalışıyorum", ex: "Ich arbeite bei einer Firma in Bonn.", exn: "Bonn’da bir firmada çalışıyorum.", topic: "work", note: "„bei“ + firma (çalıştığın yer). Türkçede „-de çalışmak“ = „bei … arbeiten“." },
  { id: "de-a1.w560", ext: 1, t: "Wie schreibt man das?", pos: "phr", n: "bu nasıl yazılır?", ex: "Wie schreibt man das? Kannst du es buchstabieren?", exn: "Bu nasıl yazılır? Harf harf söyler misin?", topic: "work", note: "„man“ = insan, genel özne (Türkçede kişi eki yok). Fiil tekil: schreibt." },
  { id: "de-a1.w561", ext: 1, t: "Was heißt … auf Deutsch?", pos: "phr", n: "… Almancada ne demek?", ex: "Was heißt „elma“ auf Deutsch?", exn: "„Elma“ Almancada ne demek?", topic: "work", note: "Kelime öğrenmek için çok değerli kalıp. „auf Deutsch“ = Almanca olarak (dil adı için auf)." },
  { id: "de-a1.w562", ext: 1, t: "Ich verstehe das nicht.", pos: "phr", n: "bunu anlamıyorum", ex: "Entschuldigung, ich verstehe das nicht.", exn: "Affedersiniz, bunu anlamıyorum.", topic: "work", note: "Olumsuzluk „nicht“ cümle sonunda: Ich verstehe das nicht. Nesne olmasa: „Ich verstehe nicht“." },
  /* ---------- body: Körper & Gesundheit (neu) ---------- */
  { id: "de-a1.w563", ext: 1, t: "das Gesicht", pl: "die Gesichter", pos: "n", n: "yüz", ex: "Dein Gesicht ist rot.", exn: "Yüzün kızarmış.", topic: "body", note: "ch/-ig: Türkçe „hiç“teki h’ye yakın yumuşak ses, ç değil. Çoğul -er: Gesichter." },
  { id: "de-a1.w564", ext: 1, t: "das Haar", pl: "die Haare", pos: "n", n: "saç; kıl", ex: "Sie hat lange Haare.", exn: "Uzun saçları var.", topic: "body", note: "Saç için çoğul kullanılır: die Haare (Türkçe tekil „saç“). „Ich wasche meine Haare.“" },
  { id: "de-a1.w565", ext: 1, t: "die Zunge", pl: "die Zungen", pos: "n", n: "dil (organ)", ex: "Zeigen Sie bitte Ihre Zunge.", exn: "Lütfen dilinizi gösterin.", topic: "body", note: "Organ olan dil = Zunge; konuşulan dil = Sprache. Türkçede ikisi de „dil“." },
  { id: "de-a1.w566", ext: 1, t: "die Lippe", pl: "die Lippen", pos: "n", n: "dudak", ex: "Meine Lippen sind kalt.", exn: "Dudaklarım soğuk.", topic: "body", note: "Genelde çoğul: Lippen." },
  { id: "de-a1.w567", ext: 1, t: "die Brust", pl: "die Brüste", pos: "n", n: "göğüs", ex: "Ich habe Schmerzen in der Brust.", exn: "Göğsümde ağrı var.", topic: "body", note: "Hem göğüs kafesi hem göğüs. Doktorda: „Brustschmerzen“." },
  { id: "de-a1.w568", ext: 1, t: "die Stirn", pl: "die Stirnen", pos: "n", n: "alın", ex: "Meine Stirn ist warm.", exn: "Alnım sıcak.", topic: "body", note: "Dişil. „Stirn“ i-r: [ştirn], st başta „şt“." },
  { id: "de-a1.w569", ext: 1, t: "der Körper", pl: "die Körper", pos: "n", n: "vücut; beden", ex: "Der Körper braucht Wasser.", exn: "Vücut suya ihtiyaç duyar.", topic: "body", note: "Çoğul aynı." },
  { id: "de-a1.w570", ext: 1, t: "die Gesundheit", pos: "n", n: "sağlık", ex: "Sport ist gut für die Gesundheit.", exn: "Spor sağlık için iyidir.", topic: "body", note: "Tekil. „Gesundheit!“ aynı zamanda hapşırana söylenir." },
  { id: "de-a1.w571", ext: 1, t: "die Krankheit", pl: "die Krankheiten", pos: "n", n: "hastalık", ex: "Die Krankheit ist nicht schlimm.", exn: "Hastalık ciddi değil.", topic: "body", note: "-heit son eki dişil isim yapar: krank → die Krankheit." },
  { id: "de-a1.w572", ext: 1, t: "die Bauchschmerzen", pos: "n", n: "karın ağrısı", ex: "Ich habe heute Bauchschmerzen.", exn: "Bugün karnım ağrıyor.", topic: "body", note: "Hep çoğul kullanılır: Bauchschmerzen. „Ich habe Bauchschmerzen“ (bende var)." },
  { id: "de-a1.w573", ext: 1, t: "die Zahnschmerzen", pos: "n", n: "diş ağrısı", ex: "Ich habe Zahnschmerzen.", exn: "Dişim ağrıyor.", topic: "body", note: "Hep çoğul: Zahnschmerzen. Doktora randevu için: „Ich brauche einen Termin.“" },
  { id: "de-a1.w574", ext: 1, t: "die Grippe", pos: "n", n: "grip", ex: "Mein Sohn hat die Grippe.", exn: "Oğlum grip.", topic: "body", note: "Tekil; artikel kullanılır: „Ich habe die Grippe.“ Soğuk algınlığı = Erkältung (A2)." },
  { id: "de-a1.w575", ext: 1, t: "die Medizin", pos: "n", n: "ilaç; tıp", ex: "Er nimmt jeden Tag Medizin.", exn: "Her gün ilaç alıyor.", topic: "body", note: "Günlük dilde „Medikament“ ya da „Tablette“. „Medizin“ aynı zamanda tıp (bilim) demektir." },
  { id: "de-a1.w576", ext: 1, t: "der Doktor", pl: "die Doktoren", pos: "n", n: "doktor", ex: "Der Doktor ist heute nicht da.", exn: "Doktor bugün yok.", topic: "body", note: "Çoğul: Doktoren (vurgu değişir). Hitap: „Herr Doktor“. Günlük dilde „der Arzt“." },
  { id: "de-a1.w577", ext: 1, t: "Ich bin krank.", pos: "phr", n: "hastayım", ex: "Ich bin krank und bleibe zu Hause.", exn: "Hastayım ve evde kalıyorum.", topic: "body", note: "„krank“ sıfat, „sein“ ile: ich bin krank. Aksine „Ich habe Grippe“ gibi hastalık için haben." },
  { id: "de-a1.w578", ext: 1, t: "Mir ist kalt.", pos: "phr", n: "üşüyorum", ex: "Mir ist kalt. Ich brauche eine Jacke.", exn: "Üşüyorum. Bir ceket lazım.", topic: "body", note: "„Mir ist kalt“ – „Ich bin kalt“ yanlış! Almancada his için „mir“ (Dativ) kullanılır. Türkçe „üşüyorum“un karşılığı." },
  { id: "de-a1.w579", ext: 1, t: "Mir ist warm.", pos: "phr", n: "sıcak basıyor; sıcaklıyorum", ex: "Mir ist warm. Ich möchte Wasser.", exn: "Sıcaklıyorum. Su istiyorum.", topic: "body", note: "Aynı yapı: „Mir ist warm“. „Ich bin warm“ demek yanlış anlaşılır; his için hep „mir“ kullan." },
  { id: "de-a1.w580", ext: 1, t: "Ich brauche einen Arzt.", pos: "phr", n: "doktora ihtiyacım var", ex: "Ich bin krank. Ich brauche einen Arzt!", exn: "Hastayım. Doktora ihtiyacım var!", topic: "body", note: "Eril akuzatif: einen Arzt. „brauchen“ + akuzatif." },
  { id: "de-a1.w581", ext: 1, t: "Es geht mir gut.", pos: "phr", n: "iyiyim", ex: "Danke, es geht mir gut.", exn: "Teşekkürler, iyiyim.", topic: "body", note: "„Mir“ burada Dativ. Kısa: „Gut, danke!“ Sorması: „Wie geht es dir?“" },
  { id: "de-a1.w582", ext: 1, t: "Es geht mir schlecht.", pos: "phr", n: "kötüyüm", ex: "Es geht mir schlecht. Ich bin krank.", exn: "Kötüyüm. Hastayım.", topic: "body", note: "Aynı yapı: es geht mir + gut/schlecht/besser." },
  { id: "de-a1.w583", ext: 1, t: "Das ist nicht schlimm.", pos: "phr", n: "önemli değil; ciddi değil", ex: "Das ist nicht schlimm. Ich bin nur müde.", exn: "Önemli değil. Sadece yorgunum.", topic: "body", note: "„schlimm“ = kötü, ciddi. Birini rahatlatırken: „Nicht so schlimm!“" },
  { id: "de-a1.w584", ext: 1, t: "Ich muss zum Arzt.", pos: "phr", n: "doktora gitmem lazım", ex: "Ich muss heute zum Arzt.", exn: "Bugün doktora gitmem lazım.", topic: "body", note: "Modal fiil: „muss“ + sonda mastar. „zum Arzt“ = doktora (yön, kalıp). Fiil cümle sonuna gider!" },
  /* ---------- free: Freizeit, Wetter & Natur (neu) ---------- */
  { id: "de-a1.w585", ext: 1, t: "der Himmel", pl: "die Himmel", pos: "n", n: "gökyüzü; gök", ex: "Der Himmel ist heute blau.", exn: "Gökyüzü bugün mavi.", topic: "free", note: "Eril: der Himmel. Genelde tekil kullanılır." },
  { id: "de-a1.w586", ext: 1, t: "die Luft", pl: "die Lüfte", pos: "n", n: "hava (soluk alınan)", ex: "Die Luft ist hier frisch.", exn: "Buranın havası taze.", topic: "free", note: "Hava durumu = Wetter; soluduğumuz hava = Luft. İkisi de Türkçede „hava“." },
  { id: "de-a1.w587", ext: 1, t: "die Natur", pos: "n", n: "doğa", ex: "Ich gehe gern in die Natur.", exn: "Doğaya gitmeyi severim.", topic: "free", note: "Tekil. „in der Natur“ = doğada." },
  { id: "de-a1.w588", ext: 1, t: "der Baum", pl: "die Bäume", pos: "n", n: "ağaç", ex: "Vor dem Haus steht ein Baum.", exn: "Evin önünde bir ağaç var.", topic: "free", note: "Çoğul: au → äu: Bäume." },
  { id: "de-a1.w589", ext: 1, t: "die Katze", pl: "die Katzen", pos: "n", n: "kedi", ex: "Unsere Katze schläft gern.", exn: "Kedimiz uyumayı sever.", topic: "free", note: "Dişil. „Kater“ erkek kedi." },
  { id: "de-a1.w590", ext: 1, t: "der Hund", pl: "die Hunde", pos: "n", n: "köpek", ex: "Der Hund ist sehr lieb.", exn: "Köpek çok sevimli.", topic: "free", note: "Almanya’da çok yaygın bir evcil hayvandır; toplu taşımada ve bazı yerlerde köpek kuralları vardır." },
  { id: "de-a1.w591", ext: 1, t: "der Vogel", pl: "die Vögel", pos: "n", n: "kuş", ex: "Der Vogel sitzt im Baum.", exn: "Kuş ağaçta duruyor.", topic: "free", note: "Çoğul: o → ö: Vögel." },
  { id: "de-a1.w592", ext: 1, t: "das Pferd", pl: "die Pferde", pos: "n", n: "at", ex: "Das Pferd ist groß.", exn: "At büyük.", topic: "free", note: "Nötr: das Pferd. „pf“ iki ses birden." },
  { id: "de-a1.w593", ext: 1, t: "der Ball", pl: "die Bälle", pos: "n", n: "top", ex: "Die Kinder spielen mit dem Ball.", exn: "Çocuklar topla oynuyor.", topic: "free", note: "Çoğul: a → ä: Bälle." },
  { id: "de-a1.w594", ext: 1, t: "das Spiel", pl: "die Spiele", pos: "n", n: "oyun; maç", ex: "Das Spiel beginnt um acht.", exn: "Maç saat sekizde başlıyor.", topic: "free", note: "Hem oyun hem maç: „das Fußballspiel“." },
  { id: "de-a1.w595", ext: 1, t: "das Lied", pl: "die Lieder", pos: "n", n: "şarkı", ex: "Das Lied ist schön.", exn: "Şarkı güzel.", topic: "free", note: "Çoğul -er: Lieder. „ie“ uzun i: [li:t]." },
  { id: "de-a1.w596", ext: 1, t: "die Gitarre", pl: "die Gitarren", pos: "n", n: "gitar", ex: "Mein Freund spielt Gitarre.", exn: "Arkadaşım gitar çalıyor.", topic: "free", note: "Enstrüman için „spielen“ + artikelsiz: Gitarre spielen. „Gi“ sert g: [gi-]." },
  { id: "de-a1.w597", ext: 1, t: "das Puzzle", pl: "die Puzzles", pos: "n", n: "yapboz", ex: "Wir machen zusammen ein Puzzle.", exn: "Birlikte yapboz yapıyoruz.", topic: "free", note: "„ein Puzzle machen“ = yapboz yapmak. Çoğul -s alır: die Puzzles." },
  { id: "de-a1.w598", ext: 1, t: "der Spaß", pos: "n", n: "eğlence; keyif", ex: "Das Spiel macht Spaß.", exn: "Oyun eğlenceli.", topic: "free", note: "Tekil. „Spaß machen“ = eğlendirmek. „sp“ başta „şp“." },
  { id: "de-a1.w599", ext: 1, t: "die Ferien", pos: "n", n: "tatil (okul tatili)", ex: "Im Sommer haben die Kinder Ferien.", exn: "Yazın çocukların tatili var.", topic: "free", note: "Hep çoğul. Okul/üniversite tatili: Ferien; çalışanın izni: Urlaub." },
  { id: "de-a1.w600", ext: 1, t: "der Grad", pl: "die Grade", pos: "n", n: "derece", ex: "Heute sind es zwanzig Grad.", exn: "Bugün hava yirmi derece.", topic: "free", note: "Sayıdan sonra çoğul eki yok: zwanzig Grad." },
  { id: "de-a1.w601", ext: 1, t: "der Mond", pl: "die Monde", pos: "n", n: "ay (gökcismi)", ex: "Der Mond ist heute sehr hell.", exn: "Ay bugün çok parlak.", topic: "free", note: "Takvim ayı: der Monat (A1). „Mond“ gökteki ay!" },
  { id: "de-a1.w602", ext: 1, t: "der Stern", pl: "die Sterne", pos: "n", n: "yıldız", ex: "Nachts sehe ich viele Sterne.", exn: "Geceleri çok yıldız görüyorum.", topic: "free", note: "Eril; çoğul -e. „St“ başta „şt“ okunur: Stern [ştern]." },
  { id: "de-a1.w603", ext: 1, t: "Die Sonne scheint.", pos: "phr", n: "güneş açıyor", ex: "Heute scheint die Sonne.", exn: "Bugün güneş açıyor.", topic: "free", note: "Fiil: scheinen. Sondaki yapı: özne (die Sonne) + scheint. „Es ist sonnig“ da denir." },
  { id: "de-a1.w604", ext: 1, t: "Viel Spaß!", pos: "phr", n: "iyi eğlenceler!", ex: "Ihr geht ins Kino? Viel Spaß!", exn: "Sinemaya mı gidiyorsunuz? İyi eğlenceler!", topic: "free", note: "Birine bir etkinlik öncesi söylenir. „Viel“ + isim = „çok …“." },
  { id: "de-a1.w605", ext: 1, t: "Das macht Spaß.", pos: "phr", n: "eğlenceli; keyif veriyor", ex: "Fußball spielen macht Spaß.", exn: "Futbol oynamak eğlenceli.", topic: "free", note: "„Spaß machen“ sabit. Özne eğlendiren şey: „Das macht mir Spaß“ (bana)." },
  { id: "de-a1.w606", ext: 1, t: "Ich spiele gern Fußball.", pos: "phr", n: "futbol oynamayı severim", ex: "Ich spiele gern Fußball mit Freunden.", exn: "Arkadaşlarla futbol oynamayı severim.", topic: "free", note: "„gern“ fiilin yanına gelir ve „-meyi severim“ anlamı katar: spiele gern = oynamayı severim. „lieben“ yerine „gern“ kullan." },
  { id: "de-a1.w607", ext: 1, t: "Hast du morgen Zeit?", pos: "phr", n: "yarın vaktin var mı?", ex: "Hast du morgen Zeit? Wir gehen ins Kino.", exn: "Yarın vaktin var mı? Sinemaya gidiyoruz.", topic: "free", note: "„Zeit haben“ = vakti olmak. Soruda fiil başta: Hast du …?" },
  { id: "de-a1.w608", ext: 1, t: "Ich gehe ins Kino.", pos: "phr", n: "sinemaya gidiyorum", ex: "Am Samstag gehe ich ins Kino.", exn: "Cumartesi sinemaya gidiyorum.", topic: "free", note: "„ins“ = in das. Yön için akuzatif. Kalıp olarak öğren: ins Kino, ins Café, ins Büro." },
  /* ---------- verbs: Wichtige Verben (neu) ---------- */
  { id: "de-a1.w609", ext: 1, t: "dürfen", pos: "v", n: "izinli olmak; -ebilmek (izin)", ex: "Darf ich hier sitzen?", exn: "Burada oturabilir miyim?", topic: "verbs", note: "Modal fiil. İzin için: „Darf ich …?“. İmkân için „können“ kullanılır. Ana fiil mastar olarak sona gider." },
  { id: "de-a1.w610", ext: 1, t: "sollen", pos: "v", n: "-meli; gerekmek (başkası söyledi)", ex: "Ich soll morgen früh kommen.", exn: "Yarın erken gelmem söylendi.", topic: "verbs", note: "Modal fiil. Başkasının isteğini bildirir; „müssen“ ise kendi zorunluluğundur." },
  { id: "de-a1.w611", ext: 1, t: "stehen", pos: "v", n: "ayakta durmak; (bir yerde) durmak", ex: "Das Auto steht vor dem Haus.", exn: "Araba evin önünde duruyor.", topic: "verbs", note: "„stehen“ dik/ayakta duran şeyler için, „liegen“ yatay duranlar. Türkçede „durmak“ ikisi." },
  { id: "de-a1.w612", ext: 1, t: "liegen", pos: "v", n: "yatmak; yatay durmak", ex: "Das Buch liegt auf dem Tisch.", exn: "Kitap masada duruyor.", topic: "verbs", note: "Kitap, telefon yatay olarak „liegen“. Türkçede „kitap masada duruyor“ dersin ama Almancada „liegt“." },
  { id: "de-a1.w613", ext: 1, t: "tun", pos: "v", n: "yapmak; etmek", ex: "Was tust du da?", exn: "Orada ne yapıyorsun?", topic: "verbs", note: "Düzensiz: ich tue, du tust, er tut. Günlük dilde çoğu zaman „machen“; „tun“ bazı kalıplarda: Es tut mir leid." },
  { id: "de-a1.w614", ext: 1, t: "werden", pos: "v", n: "olmak; (…) olmaya başlamak", ex: "Es wird kalt.", exn: "Hava soğuyor.", topic: "verbs", note: "Düzensiz: ich werde, du wirst, er wird. „sein“ = olmak (durum), „werden“ = olmak (değişim). Türkçede „-leşmek“." },
  { id: "de-a1.w615", ext: 1, t: "rufen", pos: "v", n: "seslenmek; çağırmak", ex: "Ich rufe meinen Sohn.", exn: "Oğlumu çağırıyorum.", topic: "verbs", note: "„anrufen“ = telefonla aramak; „rufen“ = yüksek sesle seslenmek, çağırmak." },
  { id: "de-a1.w616", ext: 1, t: "lachen", pos: "v", n: "gülmek", ex: "Wir lachen viel.", exn: "Çok gülüyoruz.", topic: "verbs", note: "Düzenli fiil. „ch“ burada [x] (arka damak). „lächeln“ = gülümsemek." },
  { id: "de-a1.w617", ext: 1, t: "malen", pos: "v", n: "resim yapmak; boyamak", ex: "Meine Tochter malt gern.", exn: "Kızım resim yapmayı sever.", topic: "verbs", note: "Duvar boyamak: streichen; malen = resim yapmak." },
  { id: "de-a1.w618", ext: 1, t: "duschen", pos: "v", n: "duş almak", ex: "Ich dusche jeden Morgen.", exn: "Her sabah duş alıyorum.", topic: "verbs", note: "Fiil: duschen. Türkçe „duş almak“ = Almancada tek fiil. „baden“ = banyo yapmak (küvet)." },
  { id: "de-a1.w619", ext: 1, t: "parken", pos: "v", n: "park etmek", ex: "Hier darf man nicht parken.", exn: "Burada park etmek yasak.", topic: "verbs", note: "Düzenli fiil. Park yasağı: „Parken verboten“." },
  { id: "de-a1.w620", ext: 1, t: "schenken", pos: "v", n: "hediye etmek", ex: "Ich schenke ihr Blumen.", exn: "Ona çiçek hediye ediyorum.", topic: "verbs", note: "Kime = Dativ (ihr), neyi = Akkusativ (Blumen). Önce kişi, sonra hediye gelir." },
  { id: "de-a1.w621", ext: 1, t: "fernsehen", pos: "v", n: "televizyon izlemek", ex: "Am Abend sehe ich gern fern.", exn: "Akşamları televizyon izlemeyi severim.", topic: "verbs", note: "Ayrılabilen fiil: ich sehe fern (ön ek sona gider). „Fernsehen“ aynı zamanda isim (TV)." },
  { id: "de-a1.w622", ext: 1, t: "zählen", pos: "v", n: "saymak", ex: "Ich zähle bis zehn.", exn: "Ona kadar sayıyorum.", topic: "verbs", note: "Düzenli fiil. Hesaplamak: „rechnen“." },
  { id: "de-a1.w623", ext: 1, t: "backen", pos: "v", n: "(fırında) pişirmek", ex: "Ich backe am Samstag einen Kuchen.", exn: "Cumartesi kek pişiriyorum.", topic: "verbs", note: "„backen“ fırın işi (kek, ekmek); tavada pişirmek = „braten“; suda = „kochen“." },
  { id: "de-a1.w624", ext: 1, t: "danken", pos: "v", n: "teşekkür etmek", ex: "Ich danke Ihnen für Ihre Hilfe.", exn: "Yardımınız için size teşekkür ederim.", topic: "verbs", note: "Dativ ister: ich danke dir/Ihnen. Türkçe „-e teşekkür etmek“ ile paralel." },
  { id: "de-a1.w625", ext: 1, t: "rechnen", pos: "v", n: "hesaplamak; hesap yapmak", ex: "Ich rechne kurz.", exn: "Kısaca hesaplıyorum.", topic: "verbs", note: "rechnen = hesap yapmak; bezahlen = ödemek, karıştırma." },
  { id: "de-a1.w626", ext: 1, t: "Darf ich?", pos: "phr", n: "izin var mı?; yapabilir miyim?", ex: "Darf ich das Fenster öffnen?", exn: "Pencereyi açabilir miyim?", topic: "verbs", note: "Kısaltılmış soru: Darf ich? (+ mastar düşer). Nazik izin isteme kalıbı." },
  { id: "de-a1.w627", ext: 1, t: "Kann ich Ihnen helfen?", pos: "phr", n: "size yardım edebilir miyim?", ex: "Guten Tag, kann ich Ihnen helfen?", exn: "İyi günler, size yardım edebilir miyim?", topic: "verbs", note: "Dükkânda çalışanlar böyle sorar. „Ihnen“ = size (Dativ, resmî). „helfen“ Dativ ister." },
  { id: "de-a1.w628", ext: 1, t: "Ich muss gehen.", pos: "phr", n: "gitmem lazım", ex: "Es ist acht Uhr. Ich muss gehen.", exn: "Saat sekiz. Gitmem lazım.", topic: "verbs", note: "Modal fiil + sonda mastar. Nazik veda: „Ich muss jetzt leider gehen.“" },
  /* ---------- adj: Eigenschaften (neu) ---------- */
  { id: "de-a1.w629", ext: 1, t: "gelb", pos: "adj", n: "sarı", ex: "Die Banane ist gelb.", exn: "Muz sarı.", topic: "adj", note: "Renkler artikelsiz sıfat gibi: Der Bus ist gelb." },
  { id: "de-a1.w630", ext: 1, t: "braun", pos: "adj", n: "kahverengi", ex: "Mein Hund ist braun.", exn: "Köpeğim kahverengi.", topic: "adj", note: "„au“ = av. Braun [braun]." },
  { id: "de-a1.w631", ext: 1, t: "grau", pos: "adj", n: "gri", ex: "Der Himmel ist heute grau.", exn: "Gökyüzü bugün gri.", topic: "adj", note: "grau normal çekilir: graue Wolken (A2)." },
  { id: "de-a1.w632", ext: 1, t: "rosa", pos: "adj", n: "pembe", ex: "Die Tasche ist rosa.", exn: "Çanta pembe.", topic: "adj", note: "„rosa“ ve „lila“ çekimde değişmez (ein rosa Kleid)." },
  { id: "de-a1.w633", ext: 1, t: "lila", pos: "adj", n: "mor", ex: "Das Kleid ist lila.", exn: "Elbise mor.", topic: "adj", note: "„lila“ çekimde değişmez. Koyu mor için: violett." },
  { id: "de-a1.w634", ext: 1, t: "orange", pos: "adj", n: "turuncu", ex: "Die Jacke ist orange.", exn: "Ceket turuncu.", topic: "adj", note: "Meyve = die Orange; renk = orange (sıfat). Çekimde değişmez." },
  { id: "de-a1.w635", ext: 1, t: "hungrig", pos: "adj", n: "aç", ex: "Die Kinder sind hungrig.", exn: "Çocuklar aç.", topic: "adj", note: "Almancada „Ich habe Hunger“ daha doğaldır. „hungrig“ sıfat: Das Kind ist hungrig." },
  { id: "de-a1.w636", ext: 1, t: "durstig", pos: "adj", n: "susamış", ex: "Ich bin durstig.", exn: "Susadım.", topic: "adj", note: "Günlük dilde „Ich habe Durst“ denir. „durstig“ da doğrudur." },
  { id: "de-a1.w637", ext: 1, t: "fertig", pos: "adj", n: "hazır; bitmiş", ex: "Das Essen ist fertig.", exn: "Yemek hazır.", topic: "adj", note: "Hem „hazır“ hem „bitti“: „Bist du fertig?“ = Hazır mısın? / Bitirdin mi?" },
  { id: "de-a1.w638", ext: 1, t: "hübsch", pos: "adj", n: "güzel; şirin", ex: "Das Mädchen ist sehr hübsch.", exn: "Kız çok güzel.", topic: "adj", note: "„schön“den biraz daha küçük, sevimli güzellik." },
  { id: "de-a1.w639", ext: 1, t: "süß", pos: "adj", n: "tatlı; sevimli", ex: "Der Kuchen ist süß.", exn: "Kek tatlı.", topic: "adj", note: "Hem tadı (şeker gibi) hem sevimli (süßes Baby). „ß“ = keskin s." },
  { id: "de-a1.w640", ext: 1, t: "einfach", pos: "adj", n: "kolay; basit", ex: "Die Frage ist einfach.", exn: "Soru kolay.", topic: "adj", note: "„leicht“ ile aynı anlamda ama daha geneldir. Zıt: schwierig." },
  { id: "de-a1.w641", ext: 1, t: "schwierig", pos: "adj", n: "zor; güç", ex: "Deutsch ist nicht schwierig.", exn: "Almanca zor değil.", topic: "adj", note: "Zıt: einfach / leicht. „schwer“ hem zor hem ağır, „schwierig“ yalnızca zor." },
  { id: "de-a1.w642", ext: 1, t: "bunt", pos: "adj", n: "rengârenk", ex: "Das Kleid ist sehr bunt.", exn: "Elbise çok rengârenk.", topic: "adj", note: "Tek renk değil, çok renkli. „Bunte Kleider“ = renkli elbiseler." },
  /* ---------- small: Kleine Wörter (neu) ---------- */
  { id: "de-a1.w643", ext: 1, t: "dann", pos: "x", n: "sonra; o zaman", ex: "Ich kaufe Brot, dann gehe ich nach Hause.", exn: "Ekmek alıyorum, sonra eve gidiyorum.", topic: "small", note: "Cümle başında fiil hemen arkasından gelir: Dann gehe ich … (Dann ich gehe … yanlış)." },
  { id: "de-a1.w644", ext: 1, t: "dort", pos: "x", n: "orada", ex: "Wo ist die Post? – Dort, links.", exn: "Postane nerede? – Orada, solda.", topic: "small", note: "„hier“ = burada, „dort“ = oradaki (biraz uzak) yer. Yer sorusu: „Wo?“" },
  { id: "de-a1.w645", ext: 1, t: "zu", pos: "x", n: "çok (olumsuz); -e doğru", ex: "Der Kaffee ist zu kalt.", exn: "Kahve çok soğuk.", topic: "small", note: "Sıfattan önce „zu“ = fazla (sorun): zu heiß. Edat olarak: „zu Hause“, „zum Arzt“." },
  { id: "de-a1.w646", ext: 1, t: "mehr", pos: "x", n: "daha çok; daha fazla", ex: "Ich möchte mehr Wasser, bitte.", exn: "Daha fazla su istiyorum lütfen.", topic: "small", note: "„viel – mehr – am meisten“ düzensiz derece. Olumsuz: „nicht mehr“ = artık değil." },
  { id: "de-a1.w647", ext: 1, t: "man", pos: "x", n: "insan; (genel özne)", ex: "Hier kann man Brot kaufen.", exn: "Burada ekmek alınabilir.", topic: "small", note: "Genel özne. Türkçede çoğu zaman edilgen: „içilmez“. „man“ + 3. tekil fiil." },
  { id: "de-a1.w648", ext: 1, t: "für", pos: "x", n: "için", ex: "Das Geschenk ist für dich.", exn: "Hediye senin için.", topic: "small", note: "Her zaman akuzatif: für mich, für dich, für den Mann. Türkçe „için“ (sonra gelir), Almancada başta." },
  { id: "de-a1.w649", ext: 1, t: "ohne", pos: "x", n: "-sız; -siz; olmadan", ex: "Ich trinke Tee ohne Zucker.", exn: "Çayı şekersiz içerim.", topic: "small", note: "Akuzatif ister: ohne den Mann. Artikelsiz isimle: ohne Zucker (şeker olmadan)." },
  { id: "de-a1.w650", ext: 1, t: "nach", pos: "x", n: "-den sonra; -e (şehre)", ex: "Nach dem Essen trinke ich Tee.", exn: "Yemekten sonra çay içerim.", topic: "small", note: "Zaman: nach dem Kurs. Yön (şehir/ülke): nach Berlin. Her zaman Dativ." }
]);

/* ---------- Ergänzung nach Gegenlesen: w651 ff. ---------- */
K.addVocab('de-a1', [
  { id: "de-a1.w651", ext: 1, t: "die Gesundheitskarte", pl: "die Gesundheitskarten", pos: "n", n: "sağlık kartı (sigorta kartı)", ex: "Bitte bringen Sie Ihre Gesundheitskarte mit.", exn: "Lütfen sağlık kartınızı yanınızda getirin.", topic: "body", note: "Bileşik isim: Gesundheit (sağlık) + Karte; artikel son kelimeden gelir: die Karte → die Gesundheitskarte." },
  { id: "de-a1.w652", ext: 1, t: "die Bestellung", pl: "die Bestellungen", pos: "n", n: "sipariş", ex: "Ich hole die Bestellung um drei Uhr ab.", exn: "Siparişi saat üçte alıyorum.", topic: "food", note: "-ung ile biten isimler hep dişildir: die Bestellung, die Wohnung, die Zeitung." },
  { id: "de-a1.w653", ext: 1, t: "ansehen", pos: "v", n: "bakmak; (gidip) görmek, incelemek", ex: "Ich sehe mir die Wohnung am Samstag an.", exn: "Daireye cumartesi günü bakıyorum.", topic: "verbs", note: "Ayrılabilen fiil: ich sehe … an. Çekimli kısım ikinci sırada, „an“ sonda. „sehen“ gibi çekilir: du siehst … an." },
  { id: "de-a1.w654", ext: 1, t: "Sehr geehrte Damen und Herren", pos: "phr", n: "Sayın yetkililer (resmî mektup hitabı)", ex: "Sehr geehrte Damen und Herren, ich möchte einen Kurs buchen.", exn: "Sayın yetkililer, bir kurs için kayıt yaptırmak istiyorum.", topic: "greet", note: "Tanımadığın kişilere ya da bir kuruma yazarken kullanılır; sonuna virgül konur, sonraki cümle küçük harfle başlar." },
  { id: "de-a1.w655", ext: 1, t: "Freundliche Grüße", pos: "phr", n: "saygılarımla (mektup/e-posta sonu)", ex: "Vielen Dank und freundliche Grüße", exn: "Saygılarımla, Ali Kaya", topic: "greet", note: "E-posta ve mektubun sonuna yazılır, Türkçedeki „Saygılarımla“ gibi. Sonda virgül yok; isim bir alt satıra yazılır." },
  { id: "de-a1.w656", ext: 1, t: "Alles klar!", pos: "phr", n: "Tamam! / Anlaşıldı!", ex: "Wir treffen uns um acht. – Alles klar!", exn: "Saat sekizde buluşuyoruz. – Tamam!", topic: "small", note: "Bir teklifi ya da bilgiyi onaylarken söylenir; „Okay“ gibi, ama Almanca ve çok yaygın." },
  { id: "de-a1.w657", ext: 1, t: "Langsam, bitte.", pos: "phr", n: "yavaş lütfen", ex: "Langsam, bitte. Ich lerne noch Deutsch.", exn: "Almancayı daha yeni öğreniyorum.", topic: "greet", note: "„langsam“ yavaş demektir. Karşındaki hızlı konuşunca nazikçe söylenir." },
  { id: "de-a1.w658", ext: 1, t: "Ich habe einen Termin.", pos: "phr", n: "Randevum var.", ex: "Ich habe heute um zehn Uhr einen Termin.", exn: "Bugün saat ona randevum var.", topic: "work", note: "Sık yapılan hata: „eine Termin“ – doğrusu einen Termin (der Termin eril, Akkusativ)." },
  { id: "de-a1.w659", ext: 1, t: "Ich habe keine Zeit.", pos: "phr", n: "Vaktim yok.", ex: "Heute habe ich keine Zeit.", exn: "Bugün vaktim yok.", topic: "small", note: "„die Zeit“ dişil, olumsuzda keine: keine Zeit. „nicht Zeit“ denmez." },
  { id: "de-a1.w660", ext: 1, t: "Ich weiß nicht.", pos: "phr", n: "Bilmiyorum.", ex: "Wo ist der Bahnhof? – Ich weiß nicht.", exn: "Gar nerede? – Bilmiyorum.", topic: "small", note: "„wissen“ düzensizdir: ich weiß, du weißt, er weiß (er’de -t yok!). Sık yapılan hatalar: „ich weiße“, „er weißt“. „ß“ ile yazılır." },
  { id: "de-a1.w661", ext: 1, t: "Bis Montag!", pos: "phr", n: "Pazartesiye kadar! / Pazartesi görüşürüz!", ex: "Schönes Wochenende! Bis Montag!", exn: "İyi hafta sonları! Pazartesi görüşürüz!", topic: "greet", note: "„Bis“ + gün adı: Bis morgen, Bis Montag. Artikel kullanılmaz, „bis dem Montag“ denmez." },
  { id: "de-a1.w662", ext: 1, t: "Ich habe Glück.", pos: "phr", n: "Şanslıyım.", ex: "Der Bus kommt gleich, ich habe Glück.", exn: "Otobüs birazdan geliyor, şanslıyım.", topic: "small", note: "„das Glück“ hem şans hem mutluluk demektir. „Viel Glück!“ = Bol şans!" },
  { id: "de-a1.w663", ext: 1, t: "Das stimmt.", pos: "phr", n: "Doğru. / Haklısın.", ex: "Du kommst aus Izmir? – Ja, das stimmt.", exn: "İzmirli misin? – Evet, doğru.", topic: "small", note: "Bir bilginin doğru olduğunu onaylar. Karşılığı: „Das stimmt nicht.“ = Doğru değil." },
  { id: "de-a1.w664", ext: 1, t: "Hier, bitte.", pos: "phr", n: "Buyurun. (bir şey uzatırken)", ex: "Hier, bitte. Das ist mein Pass.", exn: "Buyurun. Bu benim pasaportum.", topic: "small", note: "Bir şeyi birine uzatırken söylenir. Karşı taraf „Danke!“ der." },
  { id: "de-a1.w665", ext: 1, t: "Das ist alles.", pos: "phr", n: "Hepsi bu kadar.", ex: "Ein Brot und Milch, das ist alles.", exn: "Bir ekmek ve süt, hepsi bu kadar.", topic: "shop", note: "Alışverişte „başka bir şey?“ sorusuna cevaptır." },
  { id: "de-a1.w666", ext: 1, t: "Ich komme gleich.", pos: "phr", n: "Hemen geliyorum.", ex: "Moment, ich komme gleich.", exn: "Bir dakika, hemen geliyorum.", topic: "small", note: "„gleich“ burada „hemen, birazdan“ demektir. „Ich bin gleich da“ da denir." }
]);
})(window.KOPRU);
